_HF_FIELD_LIMITS = {
    "headline": 90,
    "subline": 120,
    "caption": 120,
    "stat": 20,
    "label": 90,
    "cta": 40,
    "title": 90,
    "lines": 1100,
    "points": 1100,
    "words": 300,
    "data": 2000,
    "script": 900,
}


def hf_clean_fields(template_id: str, body: dict) -> dict:
    """Validate and trim one template job's words. Raises
    ValueError with a plain message; the create route turns it
    into a clean 422. The accent color must be a plain hex value
    so it can ride into CSS without escaping games."""
    spec = HF_TEMPLATES.get(template_id)
    if spec is None:
        raise ValueError("pick one of the templates on the list")
    out = {}
    for field in spec["fields"]:
        if field == "lines":
            out[field] = _hf_clean_lines(body.get(field))
            continue
        if field == "points":
            out[field] = _hf_clean_points(body.get(field))
            continue
        if field == "words":
            out[field] = _hf_clean_words(body.get(field))
            continue
        if field == "data":
            points = hf_parse_chart_data(body.get(field))
            out["points"] = points
            out[field] = "\n".join(
                f"{label}, {value:g}" for label, value in points)
            continue
        value = str(body.get(field) or "").strip()
        limit = _HF_FIELD_LIMITS[field]
        if len(value) > limit:
            raise ValueError(f"that text is too long, keep it under {limit} characters")
        out[field] = value
    required = {
        "title": ("headline",),
        "captions": ("caption",),
        "stat": ("stat", "label"),
        "promo": ("headline",),
        "story": ("title", "lines"),
        "sting": ("headline",),
        "explainer": ("headline", "points"),
        "explainer_pop": ("headline", "points"),
        "explainer_energy": ("headline", "points"),
        "kinetic": ("words",),
        "intro": ("headline",),
        "outro": ("headline",),
        "chart": ("title", "data"),
        "turntable3d": ("headline",),
        "globe3d": ("headline",),
        "citypin3d": ("headline",),
        "house3d": ("headline",),
        "bars3d": ("title", "data"),
        "presenter": ("script",),
        "showcase3d": ("headline",),
        "logodraw": ("headline",),
        "diagram": ("headline", "points"),
        "particles": ("headline",),
        "vectorscene": ("headline",),
    }[template_id]
    for field in required:
        if not out.get(field):
            raise ValueError("one of the boxes is empty, fill it in and try again")
    color = str(body.get("color") or "#6366f1").strip().lower()
    if not re.fullmatch(r"#[0-9a-f]{6}", color):
        raise ValueError("that color does not look right, pick one from the color box")
    out["color"] = color
    # The GIF option (2026-11-27): any template job may ask
    # for a GIF of its first stretch beside the MP4. The
    # worker makes it after the render and posts it back;
    # the flag rides the stored fields to the claim payload.
    out["gif"] = bool(body.get("gif"))
    if template_id == "presenter":
        # Where the mouth sits on the photo, as percents the
        # form's two small boxes carry. Defaults land where a
        # head and shoulders portrait usually keeps its mouth;
        # anything off the photo is refused, not clamped, so a
        # typo never silently moves the mouth.
        for key, default in (("mouth_x", 50.0), ("mouth_y", 68.0)):
            raw = body.get(key)
            if raw is None or raw == "":
                out[key] = default
                continue
            try:
                value = float(raw)
            except (TypeError, ValueError):
                raise ValueError("the mouth position boxes take numbers")
            if not 5.0 <= value <= 95.0:
                raise ValueError("keep the mouth position inside the photo")
            out[key] = value
    return out


def _hf_clean_lines(raw) -> str:
    """The story template's lines: one story line per scene,
    three to eight of them, each short enough to read on screen.
    Accepts the studio textarea text or a list. Stored as one
    newline joined string in the job's fields."""
    if isinstance(raw, (list, tuple)):
        items = [str(x) for x in raw]
    else:
        items = str(raw or "").split("\n")
    lines = []
    for item in items:
        line = " ".join(str(item).split())
        if not line:
            continue
        if len(line) > 120:
            raise ValueError("keep each story line under 120 characters")
        lines.append(line)
    if len(lines) < 3:
        raise ValueError("write at least three story lines, one on each row")
    if len(lines) > 8:
        raise ValueError("keep it to eight story lines at most")
    return "\n".join(lines)


def _hf_clean_points(raw) -> str:
    """The explainer templates' points: one short point per
    row, one to four of them, each short enough to read at a
    glance. Stored newline joined, the shape the composition
    builder splits back apart."""
    if isinstance(raw, (list, tuple)):
        items = [str(x) for x in raw]
    else:
        items = str(raw or "").split("\n")
    points = []
    for item in items:
        line = " ".join(str(item).split())
        if not line:
            continue
        if len(line) > 90:
            raise ValueError("keep each point under 90 characters")
        points.append(line)
    if not points:
        raise ValueError("write at least one point, one on each row")
    if len(points) > 4:
        raise ValueError("keep it to four points at most")
    return "\n".join(points)


def _hf_clean_words(raw) -> str:
    """The kinetic type template's lines: two to six short
    lines, each one a punch of a few words, shown one at a
    time at full screen size."""
    if isinstance(raw, (list, tuple)):
        items = [str(x) for x in raw]
    else:
        items = str(raw or "").split("\n")
    words = []
    for item in items:
        line = " ".join(str(item).split())
        if not line:
            continue
        if len(line) > 42:
            raise ValueError("keep each line under 42 characters")
        words.append(line)
    if len(words) < 2:
        raise ValueError("write at least two lines, one on each row")
    if len(words) > 6:
        raise ValueError("keep it to six lines at most")
    return "\n".join(words)


def hf_kinetic_duration(count: int) -> float:
    """The kinetic type length: a beat to land, one and a
    half seconds a line, and a short hold on the last one."""
    return round(0.6 + 1.5 * count + 0.9, 2)


def _hf_chart_value(text: str):
    """One chart value as a float, or None when the text is
    not a plain number. Currency signs, thousands commas and
    a trailing percent sign are presentation, not value."""
    t = str(text or "").strip().rstrip("%").replace(",", "")
    t = t.lstrip("$£€").strip()
    if not t:
        return None
    try:
        value = float(t)
    except ValueError:
        return None
    if value != value or value in (float("inf"), float("-inf")):
        return None
    return value


def hf_parse_chart_data(raw) -> list:
    """Parse pasted chart data into [[label, value], ...].

    One point per row, in any of the shapes a person pastes:
    'Label, 120', 'Label: 120', 'Label 120', or a bare number
    (its label becomes 'Point N'). A first row that does not
    parse while the rest do is read as a header and skipped.
    Two to twelve points, labels under 24 characters, values
    at zero or above (the bars grow up from one baseline)."""
    rows = []
    for line in str(raw or "").replace(";", "\n").split("\n"):
        line = line.strip().strip(",").strip()
        if line:
            rows.append(line)
    points = []
    failed_first = False
    for idx, line in enumerate(rows):
        label = None
        value = None
        if "," in line:
            head, _, tail = line.partition(",")
            value = _hf_chart_value(tail)
            if value is not None:
                label = head.strip().strip(",").strip()
        if value is None and "\t" in line:
            head, _, tail = line.rpartition("\t")
            value = _hf_chart_value(tail)
            if value is not None:
                label = head.strip()
        if value is None and ":" in line:
            head, _, tail = line.rpartition(":")
            value = _hf_chart_value(tail)
            if value is not None:
                label = head.strip()
        if value is None:
            value = _hf_chart_value(line)
            if value is not None:
                label = ""
        if value is None and " " in line:
            head, _, tail = line.rpartition(" ")
            value = _hf_chart_value(tail)
            if value is not None:
                label = head.strip()
        if value is None:
            if idx == 0:
                failed_first = True
                continue
            raise ValueError(
                f"could not read the number in '{line[:40]}', "
                "use one row per point, like 'Label, 120'")
        if value < 0:
            raise ValueError("keep the numbers at zero or above")
        if not label:
            label = f"Point {len(points) + 1}"
        if len(label) > 24:
            raise ValueError("keep each label under 24 characters")
        points.append([label, value])
    if failed_first and len(points) < 2:
        raise ValueError(
            "could not read those numbers, use one row per "
            "point, like 'Label, 120'")
    if len(points) < 2:
        raise ValueError("add at least two points, one on each row")
    if len(points) > 12:
        raise ValueError("keep it to twelve points at most")
    return points


def _hf_fmt_value(value: float) -> str:
    """A chart value the way a person reads it: whole numbers
    with thousands commas, decimals trimmed to two places."""
    if value == int(value):
        return f"{int(value):,}"
    return f"{value:,.2f}".rstrip("0").rstrip(".")


def hf_story_plan(title: str, lines: list) -> list:
    """The animated story short's scene plan, the single source
    of truth the composition, the scene script and the audio
    generator all read. A title scene, one scene per story line
    timed to a reading pace, and a closing scene in golden
    light. Boundaries land on whole frames at 30 frames a
    second. Camera programs cycle the town framings."""
    fps = 30
    spans = []
    frame = 0

    def add(kind, line, light, program, seconds):
        nonlocal frame
        frames = max(1, round(seconds * fps))
        spans.append({
            "a": round(frame / fps, 4),
            "b": round((frame + frames) / fps, 4),
            "kind": kind, "line": line, "light": light,
            "program": program,
        })
        frame += frames

    add("title", -1, "day", 0, 4.5)
    last = len(lines) - 1
    for i, line in enumerate(lines):
        words = len(str(line).split())
        seconds = min(7.5, max(4.2, 2.4 + 0.38 * words))
        add("line", i, "golden" if i == last else "day", 1 + (i % 5), seconds)
    add("outro", -1, "golden", 6, 3.5)
    return spans


def _hf_page(duration: float, accent: str, clips: str, timeline: str) -> str:
    """The shared composition shell: a vertical stage, the GSAP
    library the worker copies in beside this file, and one
    seekable timeline registered the way the renderer expects."""
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1080, height=1920" />
    <script src="gsap.min.js"></script>
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}
      html, body {{ margin: 0; width: 1080px; height: 1920px; overflow: hidden; background: #0c0c0f; }}
      #root {{ position: relative; width: 1080px; height: 1920px; background: #0c0c0f;
        font-family: sans-serif; color: #f4f4f1; overflow: hidden; }}
      .bar {{ position: absolute; left: 90px; top: 780px; width: 180px; height: 14px;
        background: {accent}; border-radius: 7px; }}
      .headline {{ position: absolute; left: 90px; top: 840px; width: 900px;
        font-size: 104px; font-weight: 700; line-height: 1.08; letter-spacing: -0.02em; }}
      .subline {{ position: absolute; left: 90px; top: 1240px; width: 860px;
        font-size: 46px; font-weight: 400; line-height: 1.3; color: #b8b8c0; }}
      .statnum {{ position: absolute; left: 90px; top: 800px; width: 900px;
        font-size: 230px; font-weight: 800; line-height: 1.0; color: {accent}; }}
      .statlabel {{ position: absolute; left: 90px; top: 1120px; width: 860px;
        font-size: 54px; font-weight: 500; line-height: 1.3; }}
      .cta {{ position: absolute; left: 90px; top: 1560px; padding: 28px 44px;
        background: {accent}; color: #ffffff; font-size: 44px; font-weight: 600;
        border-radius: 999px; }}
      .bgvideo {{ position: absolute; left: 0; top: 0; width: 1080px; height: 1920px;
        object-fit: cover; }}
      .capwrap {{ position: absolute; left: 60px; top: 1330px; width: 960px;
        text-align: center; }}
      .capbar {{ display: inline-block; width: 150px; height: 12px; border-radius: 6px;
        background: {accent}; margin-bottom: 30px; }}
      .caption {{ font-size: 76px; font-weight: 700; line-height: 1.2;
        text-shadow: 0 4px 30px rgba(0,0,0,0.85); }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0"
      data-duration="{duration:g}" data-width="1080" data-height="1920" data-fps="30">
{clips}
    </div>
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
{timeline}
      window.__timelines["main"] = tl;
    </script>
  </body>
</html>
"""


def build_hf_composition(template_id: str, fields: dict,
                         source_duration: float = 0.0) -> str:
    """Build one job's composition HTML from its fixed template
    and its escaped words. Called at claim time, so the words the
    renderer sees are exactly the words stored on the job."""
    import html as _html

    esc = _html.escape
    accent = fields.get("color") or "#6366f1"
    if template_id == "title":
        clips = f"""      <div class="bar clip" data-start="0" data-duration="6" data-track-index="0"></div>
      <h1 class="headline clip" data-start="0" data-duration="6" data-track-index="1">{esc(fields.get("headline") or "")}</h1>
      <p class="subline clip" data-start="0" data-duration="6" data-track-index="2">{esc(fields.get("subline") or "")}</p>"""
        timeline = """      tl.fromTo(".bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.5, ease: "power3.out" }, 0.2);
      tl.fromTo(".headline", { opacity: 0, y: 60 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.35);
      tl.fromTo(".subline", { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.6);
      tl.to([".bar", ".headline", ".subline"], { opacity: 0, duration: 0.5, ease: "power2.in" }, 5.4);"""
        return _hf_page(6.0, accent, clips, timeline)
    if template_id == "stat":
        clips = f"""      <div class="statnum clip" data-start="0" data-duration="6" data-track-index="0">{esc(fields.get("stat") or "")}</div>
      <p class="statlabel clip" data-start="0" data-duration="6" data-track-index="1">{esc(fields.get("label") or "")}</p>"""
        timeline = """      tl.fromTo(".statnum", { opacity: 0, scale: 0.82, transformOrigin: "left center" }, { opacity: 1, scale: 1, duration: 0.55, ease: "back.out(1.6)" }, 0.25);
      tl.fromTo(".statlabel", { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.55, ease: "power3.out" }, 0.55);
      tl.to([".statnum", ".statlabel"], { opacity: 0, duration: 0.5, ease: "power2.in" }, 5.4);"""
        return _hf_page(6.0, accent, clips, timeline)
    if template_id == "promo":
        cta = fields.get("cta") or ""
        cta_clip = (
            f"""      <div class="cta clip" data-start="0" data-duration="7" data-track-index="3">{esc(cta)}</div>"""
            if cta else "")
        clips = f"""      <div class="bar clip" data-start="0" data-duration="7" data-track-index="0"></div>
      <h1 class="headline clip" data-start="0" data-duration="7" data-track-index="1">{esc(fields.get("headline") or "")}</h1>
      <p class="subline clip" data-start="0" data-duration="7" data-track-index="2">{esc(fields.get("subline") or "")}</p>
{cta_clip}"""
        timeline = """      tl.fromTo(".bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.5, ease: "power3.out" }, 0.2);
      tl.fromTo(".headline", { opacity: 0, y: 60 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.35);
      tl.fromTo(".subline", { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.6);
      tl.fromTo(".cta", { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.55, ease: "power3.out" }, 0.85);
      tl.to([".bar", ".headline", ".subline", ".cta"], { opacity: 0, duration: 0.5, ease: "power2.in" }, 6.4);"""
        return _hf_page(7.0, accent, clips, timeline)
    if template_id == "captions":
        dur = max(1.0, min(float(source_duration or 0), TEMPLATE_MAX_SOURCE_SECONDS))
        dur = round(dur, 2)
        clips = f"""      <video class="bgvideo clip" data-start="0" data-duration="{dur:g}" data-track-index="0" src="source.mp4" muted playsinline></video>
      <div class="capwrap clip" data-start="0" data-duration="{dur:g}" data-track-index="1">
        <span class="capbar"></span>
        <p class="caption">{esc(fields.get("caption") or "")}</p>
      </div>"""
        timeline = """      tl.fromTo(".capwrap", { opacity: 0, y: 50 }, { opacity: 1, y: 0, duration: 0.45, ease: "back.out(1.8)" }, 0.3);"""
        return _hf_page(dur, accent, clips, timeline)
    if template_id == "sting":
        # Timing follows the motion design tables the wing was
        # built under: a short anticipation hold, a dramatic
        # reveal for the ring, a standard word stagger, and an
        # exit at about seventy percent of the entrance time.
        words = " ".join(
            f'<span class="sting-word" style="display:inline-block;">{esc(w)}</span>'
            for w in (fields.get("headline") or "").split())
        sub = fields.get("subline") or ""
        sub_clip = (
            f"""      <p id="sting-sub" style="position:absolute;left:90px;top:1180px;width:900px;text-align:center;font-size:44px;font-weight:400;color:#b8b8c0;">{esc(sub)}</p>"""
            if sub else "")
        clips = f"""      <div class="clip" data-start="0" data-duration="4" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <svg width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;left:0;top:0;">
          <circle id="sting-dot" cx="540" cy="740" r="26" fill="{accent}" style="transform-box:fill-box;transform-origin:center;" />
          <circle id="sting-ring" cx="540" cy="740" r="150" fill="none" stroke="{accent}" stroke-width="10" stroke-linecap="round" stroke-dasharray="943" stroke-dashoffset="943" transform="rotate(-90 540 740)" />
        </svg>
        <h1 id="sting-head" style="position:absolute;left:90px;top:990px;width:900px;text-align:center;font-size:92px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;">{words}</h1>
{sub_clip}
        <div id="sting-sweep" style="position:absolute;top:0;left:0;width:260px;height:1920px;background:linear-gradient(100deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.10) 50%, rgba(255,255,255,0) 100%);"></div>
      </div>"""
        timeline = """      tl.fromTo("#sting-dot", { scale: 0 }, { scale: 1, duration: 0.35, ease: "expo.out" }, 0.1);
      tl.to("#sting-ring", { strokeDashoffset: 0, duration: 0.95, ease: "power2.inOut" }, 0.3);
      tl.fromTo(".sting-word", { opacity: 0, y: 34 }, { opacity: 1, y: 0, duration: 0.5, ease: "expo.out", stagger: 0.08 }, 1.15);
      tl.fromTo("#sting-sub", { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.45, ease: "expo.out" }, 1.75);
      tl.fromTo("#sting-sweep", { x: -320 }, { x: 1420, duration: 1.1, ease: "sine.inOut" }, 2.1);
      tl.to(["#sting-ring", "#sting-dot", "#sting-head", "#sting-sub"], { opacity: 0, duration: 0.65, ease: "power2.in" }, 3.3);"""
        return _hf_page(4.0, accent, clips, timeline)
    if template_id in ("explainer", "explainer_pop",
                       "explainer_energy"):
        return _hf_explainer_page(template_id, fields)
    if template_id == "kinetic":
        lines = [ln for ln in (fields.get("words") or "").split("\n")
                 if ln.strip()]
        duration = hf_kinetic_duration(len(lines))
        clips = []
        timeline = []
        for i, line in enumerate(lines):
            start = 0.6 + i * 1.5
            size = 170 if len(line) <= 10 else \
                128 if len(line) <= 20 else 96
            color = accent if i == len(lines) - 1 else "#f4f4f1"
            clips.append(f"""      <div id="kin-{i}" class="clip" data-start="{start:g}" data-duration="1.5" data-track-index="{i}" style="position:absolute;left:60px;top:760px;width:960px;text-align:center;font-size:{size}px;font-weight:800;line-height:1.1;letter-spacing:-0.01em;color:{color};opacity:0;">{esc(line)}</div>""")
            timeline.append(f"""      tl.fromTo("#kin-{i}", {{ opacity: 0, scale: 0.72 }}, {{ opacity: 1, scale: 1, duration: 0.42, ease: "expo.out" }}, {start:g});""")
            if i < len(lines) - 1:
                timeline.append(f"""      tl.to("#kin-{i}", {{ opacity: 0, y: -56, duration: 0.3, ease: "power2.in" }}, {start + 1.12:g});""")
        return _hf_page(duration, accent, "\n".join(clips),
                        "\n".join(timeline))
    if template_id == "intro":
        # The sting's ring and word reveal, but the lockup
        # holds at the end instead of fading: an intro ends on
        # the name so the content can cut in under it.
        words = " ".join(
            f'<span class="intro-word" style="display:inline-block;">{esc(w)}</span>'
            for w in (fields.get("headline") or "").split())
        sub = fields.get("subline") or ""
        sub_clip = (
            f"""      <p id="intro-sub" style="position:absolute;left:90px;top:1180px;width:900px;text-align:center;font-size:44px;font-weight:400;color:#b8b8c0;">{esc(sub)}</p>"""
            if sub else "")
        clips = f"""      <div class="clip" data-start="0" data-duration="5" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <svg width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;left:0;top:0;">
          <circle id="intro-dot" cx="540" cy="740" r="26" fill="{accent}" style="transform-box:fill-box;transform-origin:center;" />
          <circle id="intro-ring" cx="540" cy="740" r="150" fill="none" stroke="{accent}" stroke-width="10" stroke-linecap="round" stroke-dasharray="943" stroke-dashoffset="943" transform="rotate(-90 540 740)" />
        </svg>
        <h1 id="intro-head" style="position:absolute;left:90px;top:990px;width:900px;text-align:center;font-size:92px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;">{words}</h1>
{sub_clip}
        <div id="intro-sweep" style="position:absolute;top:0;left:0;width:260px;height:1920px;background:linear-gradient(100deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.10) 50%, rgba(255,255,255,0) 100%);"></div>
      </div>"""
        timeline = """      tl.fromTo("#intro-dot", { scale: 0 }, { scale: 1, duration: 0.35, ease: "expo.out" }, 0.1);
      tl.to("#intro-ring", { strokeDashoffset: 0, duration: 0.95, ease: "power2.inOut" }, 0.3);
      tl.fromTo(".intro-word", { opacity: 0, y: 34 }, { opacity: 1, y: 0, duration: 0.5, ease: "expo.out", stagger: 0.08 }, 1.15);
      tl.fromTo("#intro-sub", { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.45, ease: "expo.out" }, 1.75);
      tl.fromTo("#intro-sweep", { x: -320 }, { x: 1420, duration: 1.1, ease: "sine.inOut" }, 2.1);"""
        return _hf_page(5.0, accent, clips, timeline)
    if template_id == "outro":
        # The end card: the lockup walks in and holds, so the
        # last frame is the name, the line and the button.
        cta = fields.get("cta") or ""
        cta_clip = (
            f"""      <div id="outro-cta" style="position:absolute;left:50%;top:1250px;transform:translateX(-50%);padding:26px 46px;background:{accent};color:#ffffff;font-size:42px;font-weight:600;border-radius:999px;">{esc(cta)}</div>"""
            if cta else "")
        sub = fields.get("subline") or ""
        sub_clip = (
            f"""      <p id="outro-sub" style="position:absolute;left:90px;top:1090px;width:900px;text-align:center;font-size:46px;font-weight:400;color:#b8b8c0;">{esc(sub)}</p>"""
            if sub else "")
        clips = f"""      <div class="clip" data-start="0" data-duration="6" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <svg width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;left:0;top:0;">
          <circle id="outro-ring" cx="540" cy="700" r="110" fill="none" stroke="{accent}" stroke-width="9" stroke-linecap="round" stroke-dasharray="692" stroke-dashoffset="692" transform="rotate(-90 540 700)" />
          <circle id="outro-dot" cx="540" cy="700" r="20" fill="{accent}" style="transform-box:fill-box;transform-origin:center;" />
        </svg>
        <h1 id="outro-head" style="position:absolute;left:90px;top:900px;width:900px;text-align:center;font-size:88px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;">{esc(fields.get("headline") or "")}</h1>
{sub_clip}
{cta_clip}
      </div>"""
        timeline = """      tl.fromTo("#outro-dot", { scale: 0 }, { scale: 1, duration: 0.35, ease: "expo.out" }, 0.15);
      tl.to("#outro-ring", { strokeDashoffset: 0, duration: 0.85, ease: "power2.inOut" }, 0.3);
      tl.fromTo("#outro-head", { opacity: 0, y: 44 }, { opacity: 1, y: 0, duration: 0.6, ease: "expo.out" }, 0.75);
      tl.fromTo("#outro-sub", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.5, ease: "expo.out" }, 1.15);
      tl.fromTo("#outro-cta", { opacity: 0, y: 30 }, { opacity: 1, y: 0, duration: 0.5, ease: "back.out(1.7)" }, 1.5);"""
        return _hf_page(6.0, accent, clips, timeline)
    if template_id == "chart":
        # The data video: bars grow from one baseline in a
        # stagger and each value lands above its bar as the
        # bar settles. Values are printed fully formed rather
        # than counted up: the renderer seeks the timeline, so
        # a printed value is exact at every frame, where a
        # text tween would depend on seek callbacks.
        points = fields.get("points") or []
        maxv = max((v for _l, v in points), default=0) or 1
        n = max(1, len(points))
        slot = 920.0 / n
        bar_w = min(150.0, slot * 0.55)
        base_y = 1480
        max_h = 760
        parts = [f"""      <div class="clip" data-start="0" data-duration="9" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <div id="chart-bar" style="position:absolute;left:90px;top:290px;width:170px;height:14px;background:{accent};border-radius:7px;"></div>
        <h1 id="chart-title" style="position:absolute;left:90px;top:346px;width:900px;font-size:72px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;">{esc(fields.get("title") or "")}</h1>
        <div style="position:absolute;left:80px;top:{base_y}px;width:920px;height:3px;background:#3a3a42;"></div>"""]
        timeline = ["""      tl.fromTo("#chart-bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.5, ease: "power3.out" }, 0.2);""",
                    """      tl.fromTo("#chart-title", { opacity: 0, y: 40 }, { opacity: 1, y: 0, duration: 0.55, ease: "power3.out" }, 0.35);"""]
        for i, (label, value) in enumerate(points):
            h = max(8, round(max_h * value / maxv))
            x = 80 + slot * i + (slot - bar_w) / 2
            start = 0.7 + i * 0.22
            parts.append(f"""        <div id="chart-bar-{i}" style="position:absolute;left:{x:.0f}px;top:{base_y - h}px;width:{bar_w:.0f}px;height:{h}px;background:linear-gradient(180deg, {accent}, {accent}b3);border-radius:12px 12px 0 0;transform-origin:50% 100%;"></div>
        <div id="chart-val-{i}" style="position:absolute;left:{80 + slot * i:.0f}px;top:{base_y - h - 88}px;width:{slot:.0f}px;text-align:center;font-size:54px;font-weight:800;">{_hf_fmt_value(value)}</div>
        <div id="chart-cat-{i}" style="position:absolute;left:{80 + slot * i:.0f}px;top:{base_y + 26}px;width:{slot:.0f}px;text-align:center;font-size:32px;color:#b8b8c0;">{esc(label)}</div>""")
            timeline.append(f"""      tl.fromTo("#chart-bar-{i}", {{ scaleY: 0 }}, {{ scaleY: 1, duration: 0.85, ease: "power3.out" }}, {start:g});""")
            timeline.append(f"""      tl.fromTo("#chart-cat-{i}", {{ opacity: 0 }}, {{ opacity: 1, duration: 0.4, ease: "power1.out" }}, {start + 0.3:g});""")
            timeline.append(f"""      tl.fromTo("#chart-val-{i}", {{ opacity: 0, y: 18, scale: 0.7 }}, {{ opacity: 1, y: 0, scale: 1, duration: 0.45, ease: "back.out(1.8)" }}, {start + 0.55:g});""")
        parts.append("      </div>")
        return _hf_page(9.0, accent, "\n".join(parts),
                        "\n".join(timeline))
    if template_id == "diagram":
        return _hf_diagram_page(fields)
    if template_id == "particles":
        return _hf_particles_page(fields)
    if template_id == "vectorscene":
        return _hf_vectorscene_page(fields)
    if template_id == "logodraw":
        return _hf_logodraw_page(fields)
    if template_id in FORGE3D_TEMPLATES:
        return _hf_forge3d_page(template_id, fields)
    if template_id == "presenter":
        return _hf_presenter_page(fields)
    if template_id == "story":
        return _hf_story_page(fields)
    raise ValueError(f"unknown template {template_id}")


def _hf_explainer_page(template_id: str, fields: dict) -> str:
    """The explainer family: one headline, then the points
    arriving one at a time under it. The three styles share
    the layout and differ in how things move, the shape of
    the playbooks they came from: the default is calm fades
    and slides, pop lands each point as a pill with a spring,
    and energy comes in fast from the side, bigger and
    louder."""
    import html as _html

    esc = _html.escape
    accent = fields.get("color") or "#6366f1"
    duration = float(HF_TEMPLATES[template_id]["duration"])
    points = [p for p in (fields.get("points") or "").split("\n")
              if p.strip()]
    headline_size = 110 if template_id == "explainer_energy" else 96
    parts = [f"""      <div class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <div id="expl-bar" style="position:absolute;left:90px;top:520px;width:180px;height:14px;background:{accent};border-radius:7px;"></div>
        <h1 id="expl-head" style="position:absolute;left:90px;top:580px;width:900px;font-size:{headline_size}px;font-weight:800;line-height:1.1;letter-spacing:-0.015em;">{esc(fields.get("headline") or "")}</h1>"""]
    timeline = []
    if template_id == "explainer_energy":
        timeline.append("""      tl.fromTo("#expl-bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.3, ease: "power4.out" }, 0.12);""")
        timeline.append("""      tl.fromTo("#expl-head", { opacity: 0, x: -70 }, { opacity: 1, x: 0, duration: 0.38, ease: "power4.out" }, 0.22);""")
    elif template_id == "explainer_pop":
        timeline.append("""      tl.fromTo("#expl-bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.45, ease: "back.out(1.8)" }, 0.2);""")
        timeline.append("""      tl.fromTo("#expl-head", { opacity: 0, scale: 0.85, transformOrigin: "left center" }, { opacity: 1, scale: 1, duration: 0.5, ease: "back.out(1.7)" }, 0.3);""")
    else:
        timeline.append("""      tl.fromTo("#expl-bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.5, ease: "power3.out" }, 0.2);""")
        timeline.append("""      tl.fromTo("#expl-head", { opacity: 0, y: 56 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.35);""")
    for i, point in enumerate(points):
        top = 1000 + i * 168
        if template_id == "explainer_pop":
            parts.append(f"""        <div id="expl-row-{i}" style="position:absolute;left:90px;top:{top}px;width:900px;padding:30px 42px;background:{accent}26;border:2px solid {accent};border-radius:999px;font-size:54px;font-weight:600;">{esc(point)}</div>""")
            start = 0.9 + i * 0.6
            timeline.append(f"""      tl.fromTo("#expl-row-{i}", {{ opacity: 0, scale: 0.6 }}, {{ opacity: 1, scale: 1, duration: 0.5, ease: "back.out(2.2)" }}, {start:g});""")
        elif template_id == "explainer_energy":
            parts.append(f"""        <div id="expl-row-{i}" style="position:absolute;left:90px;top:{top}px;width:900px;font-size:60px;font-weight:700;"><span style="display:inline-block;width:26px;height:26px;border-radius:50%;background:{accent};margin-right:26px;vertical-align:middle;"></span>{esc(point)}</div>""")
            start = 0.75 + i * 0.42
            timeline.append(f"""      tl.fromTo("#expl-row-{i}", {{ opacity: 0, x: -90, rotation: -2 }}, {{ opacity: 1, x: 0, rotation: 0, duration: 0.42, ease: "power4.out" }}, {start:g});""")
        else:
            parts.append(f"""        <div id="expl-row-{i}" style="position:absolute;left:90px;top:{top}px;width:900px;font-size:58px;font-weight:600;line-height:1.25;"><span style="display:inline-block;width:24px;height:24px;border-radius:50%;background:{accent};margin-right:26px;vertical-align:middle;"></span>{esc(point)}</div>""")
            start = 0.95 + i * 0.8
            timeline.append(f"""      tl.fromTo("#expl-row-{i}", {{ opacity: 0, y: 44 }}, {{ opacity: 1, y: 0, duration: 0.55, ease: "power3.out" }}, {start:g});""")
    parts.append("      </div>")
    timeline.append(f"""      tl.to("#root > div", {{ opacity: 0, duration: 0.5, ease: "power2.in" }}, {duration - 0.6:g});""")
    return _hf_page(duration, accent, "\n".join(parts),
                    "\n".join(timeline))


def _hf_diagram_page(fields: dict) -> str:
    """The diagram explainer (2026-11-27, Motion Canvas's
    shape, original code): the points become a chain of step
    cards down the middle of the stage. Each connector draws
    itself in, a signal pulse rides it, and the next card
    lights up as the pulse lands, the way a diagram in Motion
    Canvas walks a viewer through a process one signal at a
    time. Cards start dim and grey; activation is the accent
    border, a tinted fill and a small pop, in that order."""
    import html as _html

    esc = _html.escape
    accent = fields.get("color") or "#6366f1"
    duration = float(HF_TEMPLATES["diagram"]["duration"])
    points = [p for p in (fields.get("points") or "").split("\n")
              if p.strip()]
    r, g, b = (int(accent[i:i + 2], 16) for i in (1, 3, 5))
    tint = f"rgba({r},{g},{b},0.18)"
    node_h, conn = 168, 84
    n = len(points)
    y0 = 800 if n >= 3 else (848 if n == 2 else 908)
    svg_parts = []
    node_parts = []
    timeline = [
        """      tl.fromTo("#dg-bar", { scaleX: 0, transformOrigin: "left center" }, { scaleX: 1, duration: 0.5, ease: "power3.out" }, 0.25);""",
        """      tl.fromTo("#dg-head", { opacity: 0, y: 48 }, { opacity: 1, y: 0, duration: 0.6, ease: "power3.out" }, 0.4);""",
    ]
    for i, point in enumerate(points):
        top = y0 + i * (node_h + conn)
        act = 1.15 + i * 1.25
        if i > 0:
            y_from = y0 + (i - 1) * (node_h + conn) + node_h
            y_to = y_from + conn
            draw = act - 0.62
            svg_parts.append(f"""          <line id="dg-link-{i}" x1="540" y1="{y_from}" x2="540" y2="{y_to}" stroke="{accent}" stroke-width="6" stroke-linecap="round" pathLength="1" style="stroke-dasharray:1;stroke-dashoffset:1;" />
          <circle id="dg-pulse-{i}" cx="540" cy="{y_from + 8}" r="34" fill="{accent}" opacity="0" />
          <circle id="dg-dot-{i}" cx="540" cy="{y_from + 8}" r="13" fill="{accent}" opacity="0" />""")
            timeline.append(f"""      tl.to("#dg-link-{i}", {{ strokeDashoffset: 0, duration: 0.38, ease: "power2.inOut" }}, {draw:g});""")
            timeline.append(f"""      tl.fromTo("#dg-dot-{i}", {{ attr: {{ cy: {y_from + 8} }}, opacity: 0 }}, {{ attr: {{ cy: {y_to - 8} }}, opacity: 1, duration: 0.5, ease: "power1.inOut" }}, {draw + 0.04:g});""")
            timeline.append(f"""      tl.fromTo("#dg-pulse-{i}", {{ attr: {{ cy: {y_from + 8} }}, opacity: 0 }}, {{ attr: {{ cy: {y_to - 8} }}, opacity: 0.25, duration: 0.5, ease: "power1.inOut" }}, {draw + 0.04:g});""")
            timeline.append(f"""      tl.to(["#dg-dot-{i}", "#dg-pulse-{i}"], {{ opacity: 0, duration: 0.12, ease: "power1.out" }}, {draw + 0.56:g});""")
        node_parts.append(f"""        <div id="dg-node-{i}" style="position:absolute;left:190px;top:{top}px;width:700px;min-height:{node_h}px;padding:30px 38px;background:rgba(255,255,255,0.03);border:3px solid #3a3a42;border-radius:28px;">
          <div style="font-size:26px;font-weight:700;letter-spacing:0.14em;color:{accent};">STEP {i + 1}</div>
          <p id="dg-text-{i}" style="font-size:46px;font-weight:650;line-height:1.22;color:#b8b8c0;margin-top:8px;">{esc(point)}</p>
        </div>""")
        timeline.append(f"""      tl.fromTo("#dg-node-{i}", {{ opacity: 0.45, scale: 0.92 }}, {{ opacity: 1, scale: 1, duration: 0.45, ease: "back.out(1.8)" }}, {act:g});""")
        timeline.append(f"""      tl.to("#dg-node-{i}", {{ borderColor: "{accent}", backgroundColor: "{tint}", duration: 0.4, ease: "power2.out" }}, {act:g});""")
        timeline.append(f"""      tl.to("#dg-text-{i}", {{ color: "#f4f4f1", duration: 0.4, ease: "power2.out" }}, {act:g});""")
    timeline.append(f"""      tl.to("#root > div", {{ opacity: 0, duration: 0.5, ease: "power2.in" }}, {duration - 0.6:g});""")
    clips = f"""      <div class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <div id="dg-bar" style="position:absolute;left:90px;top:296px;width:180px;height:14px;background:{accent};border-radius:7px;"></div>
        <h1 id="dg-head" style="position:absolute;left:90px;top:352px;width:900px;font-size:82px;font-weight:800;line-height:1.1;letter-spacing:-0.015em;">{esc(fields.get("headline") or "")}</h1>
        <svg width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;left:0;top:0;">
{chr(10).join(svg_parts)}
        </svg>
{chr(10).join(node_parts)}
      </div>"""
    return _hf_page(duration, accent, clips, "\n".join(timeline))


def _hf_particles_page(fields: dict) -> str:
    """The particle burst (2026-11-27, Proton's shape,
    original code): a burst of sparks fires from the middle
    of the stage as the headline lands, a smaller echo burst
    follows, and embers rise through the whole piece. Every
    particle is a plain element with its own tweens, placed
    by a seeded generator at build time, so the page is
    deterministic and a frame is a pure function of the seek
    time exactly like the rest of the wing. Ballistics are
    split the way the renderer's tweens can carry them: the
    rise decelerates, the fall accelerates, the drift out
    eases off like drag."""
    import html as _html
    import math
    import random

    esc = _html.escape
    accent = fields.get("color") or "#6366f1"
    duration = float(HF_TEMPLATES["particles"]["duration"])
    rng = random.Random(20261127)
    palette = [accent, "#ffffff", "#f5d67a", accent]
    parts = [f"""      <div id="pt-clip" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <div id="pt-glow" style="position:absolute;left:190px;top:530px;width:700px;height:700px;border-radius:50%;background:radial-gradient(circle, {accent}59 0%, rgba(0,0,0,0) 70%);opacity:0;"></div>"""]
    timeline = [
        """      tl.fromTo("#pt-glow", { scale: 0.4, opacity: 0 }, { scale: 1.15, opacity: 0.55, duration: 0.9, ease: "expo.out" }, 0.45);""",
        """      tl.to("#pt-glow", { opacity: 0.3, duration: 1.2, ease: "power1.inOut" }, 1.6);""",
    ]

    def burst(ox, oy, start, count, power, tag):
        for i in range(count):
            ang = rng.uniform(0, 2 * math.pi)
            dist = rng.uniform(110, 520) * power
            dx = math.cos(ang) * dist
            up = rng.uniform(50, 260) * power + max(0.0, -math.sin(ang)) * 120 * power
            drop = rng.uniform(230, 520) * power
            life = rng.uniform(1.5, 2.8) * (0.8 + 0.3 * power)
            size = rng.uniform(5, 15)
            color = palette[rng.randrange(len(palette))]
            rect = rng.random() < 0.35
            rad = "3px" if rect else "50%"
            parts.append(f"""        <div id="pt-{tag}-{i}" style="position:absolute;left:{ox - size / 2:.0f}px;top:{oy - size / 2:.0f}px;width:{size:.0f}px;height:{size:.0f}px;border-radius:{rad};background:{color};opacity:0;"></div>""")
            timeline.append(f"""      tl.fromTo("#pt-{tag}-{i}", {{ x: 0 }}, {{ x: {dx:.0f}, duration: {life:.2f}, ease: "power1.out" }}, {start:.2f});""")
            timeline.append(f"""      tl.fromTo("#pt-{tag}-{i}", {{ y: 0 }}, {{ y: {-up:.0f}, duration: {life * 0.42:.2f}, ease: "power2.out" }}, {start:.2f});""")
            timeline.append(f"""      tl.to("#pt-{tag}-{i}", {{ y: {drop:.0f}, duration: {life * 0.58:.2f}, ease: "power2.in" }}, {start + life * 0.42:.2f});""")
            timeline.append(f"""      tl.fromTo("#pt-{tag}-{i}", {{ opacity: 0 }}, {{ opacity: 1, duration: 0.07, ease: "power1.out" }}, {start:.2f});""")
            timeline.append(f"""      tl.to("#pt-{tag}-{i}", {{ opacity: 0, duration: 0.5, ease: "power1.in" }}, {start + life - 0.5:.2f});""")
            if rect:
                rot = rng.uniform(-260, 260)
                timeline.append(f"""      tl.to("#pt-{tag}-{i}", {{ rotation: {rot:.0f}, duration: {life:.2f}, ease: "none" }}, {start:.2f});""")

    burst(540, 880, 0.55, 76, 1.0, "a")
    burst(540, 880, 3.05, 30, 0.62, "b")
    for i in range(20):
        x0 = rng.uniform(30, 1050)
        size = rng.uniform(4, 8)
        dur = rng.uniform(5.2, 6.0)
        sway = rng.uniform(18, 52) * rng.choice((-1, 1))
        rise = rng.uniform(1850, 1980)
        color = palette[rng.randrange(len(palette))]
        parts.append(f"""        <div id="pt-e-{i}" style="position:absolute;left:{x0:.0f}px;top:1952px;width:{size:.0f}px;height:{size:.0f}px;border-radius:50%;background:{color};opacity:0;"></div>""")
        timeline.append(f"""      tl.to("#pt-e-{i}", {{ y: {-rise:.0f}, duration: {dur:.2f}, ease: "none" }}, 0);""")
        timeline.append(f"""      tl.fromTo("#pt-e-{i}", {{ x: 0 }}, {{ x: {sway:.0f}, duration: {dur / 2:.2f}, ease: "sine.inOut" }}, 0);""")
        timeline.append(f"""      tl.to("#pt-e-{i}", {{ x: 0, duration: {dur / 2:.2f}, ease: "sine.inOut" }}, {dur / 2:.2f});""")
        timeline.append(f"""      tl.fromTo("#pt-e-{i}", {{ opacity: 0 }}, {{ opacity: 0.75, duration: 0.7, ease: "power1.out" }}, 0);""")
        timeline.append(f"""      tl.to("#pt-e-{i}", {{ opacity: 0, duration: 0.9, ease: "power1.in" }}, {dur - 0.9:.2f});""")
    sub = fields.get("subline") or ""
    sub_clip = (
        f"""        <p id="pt-sub" style="position:absolute;left:90px;top:1006px;width:900px;text-align:center;font-size:46px;font-weight:400;color:#b8b8c0;">{esc(sub)}</p>"""
        if sub else "")
    parts.append(f"""        <h1 id="pt-head" style="position:absolute;left:70px;top:796px;width:940px;text-align:center;font-size:98px;font-weight:800;line-height:1.1;letter-spacing:-0.015em;text-shadow:0 6px 44px rgba(0,0,0,0.55);">{esc(fields.get("headline") or "")}</h1>
{sub_clip}
      </div>""")
    timeline.append("""      tl.fromTo("#pt-head", { opacity: 0, scale: 0.8 }, { opacity: 1, scale: 1, duration: 0.55, ease: "back.out(1.6)" }, 0.5);""")
    if sub:
        timeline.append("""      tl.fromTo("#pt-sub", { opacity: 0, y: 26 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, 0.95);""")
    timeline.append(f"""      tl.to("#pt-clip", {{ opacity: 0, duration: 0.5, ease: "power2.in" }}, {duration - 0.55:g});""")
    return _hf_page(duration, accent, "\n".join(parts),
                    "\n".join(timeline))


def _hf_vectorscene_page(fields: dict) -> str:
    """The vector scene (2026-11-27, Two.js's shape, original
    code): a flat illustrated landscape drawn as one SVG. The
    sun rises in the accent color, three hill layers settle
    at three speeds for parallax, a pale path draws itself
    up the near hill, clouds drift and the stars give up the
    sky as the light comes. The words wait for the scene to
    exist, then land in the sky as the follow-through layer."""
    import html as _html
    import random

    esc = _html.escape
    accent = fields.get("color") or "#6366f1"
    duration = float(HF_TEMPLATES["vectorscene"]["duration"])
    rng = random.Random(20261127)
    stars = "\n".join(
        f"""          <circle cx="{rng.uniform(20, 1060):.0f}" cy="{rng.uniform(36, 700):.0f}" r="{rng.uniform(1.8, 4.4):.1f}" fill="#ffffff" />"""
        for _ in range(26))
    clouds = []
    for i, (cx, cy, s, op) in enumerate((
            (190, 300, 1.0, 0.13), (770, 205, 0.75, 0.16),
            (520, 445, 0.6, 0.09))):
        clouds.append(f"""        <g id="vs-cloud-{i}" opacity="0">
          <ellipse cx="{cx}" cy="{cy}" rx="{120 * s:.0f}" ry="{34 * s:.0f}" fill="#ffffff" opacity="{op}" />
          <ellipse cx="{cx + 70 * s:.0f}" cy="{cy + 8 * s:.0f}" rx="{86 * s:.0f}" ry="{26 * s:.0f}" fill="#ffffff" opacity="{op}" />
          <ellipse cx="{cx - 78 * s:.0f}" cy="{cy + 10 * s:.0f}" rx="{72 * s:.0f}" ry="{22 * s:.0f}" fill="#ffffff" opacity="{op}" />
        </g>""")
    sub = fields.get("subline") or ""
    sub_clip = (
        f"""        <p id="vs-sub" style="position:absolute;left:70px;top:486px;width:940px;text-align:center;font-size:44px;font-weight:400;color:#d8d5cc;text-shadow:0 4px 30px rgba(0,0,0,0.6);">{esc(sub)}</p>"""
        if sub else "")
    clips = f"""      <div id="vs-clip" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <svg width="1080" height="1920" viewBox="0 0 1080 1920" style="position:absolute;left:0;top:0;">
          <defs>
            <linearGradient id="vs-sky" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stop-color="#0b0b12" />
              <stop offset="1" stop-color="{accent}" stop-opacity="0.5" />
            </linearGradient>
          </defs>
          <rect width="1080" height="1920" fill="url(#vs-sky)" />
          <g id="vs-stars">
{stars}
          </g>
          <circle id="vs-glow" cx="540" cy="1052" r="330" fill="{accent}" opacity="0" />
          <circle id="vs-sun" cx="540" cy="1330" r="118" fill="{accent}" />
{"".join(clouds)}
          <path id="vs-hill-far" d="M-80,1240 C140,1120 300,1210 520,1150 C740,1090 900,1180 1160,1120 L1160,1920 L-80,1920 Z" fill="{accent}" opacity="0.3" />
          <path id="vs-hill-mid" d="M-80,1470 C160,1360 380,1450 620,1390 C860,1330 1020,1420 1160,1380 L1160,1920 L-80,1920 Z" fill="#1e1e2a" />
          <path id="vs-hill-near" d="M-80,1700 C200,1600 460,1690 720,1630 C940,1580 1060,1640 1160,1610 L1160,1920 L-80,1920 Z" fill="#12121a" />
          <path id="vs-river" d="M548,1920 C500,1790 620,1700 566,1590 C520,1496 610,1420 552,1330 C512,1268 560,1210 540,1150" fill="none" stroke="#f4f4f1" stroke-width="9" stroke-linecap="round" opacity="0.45" pathLength="1" style="stroke-dasharray:1;stroke-dashoffset:1;" />
          <g id="vs-bird-0" opacity="0"><path d="M0,0 Q12,-11 24,0 Q36,-11 48,0" fill="none" stroke="#0a0a10" stroke-width="5" stroke-linecap="round" transform="translate(712,238)" /></g>
          <g id="vs-bird-1" opacity="0"><path d="M0,0 Q12,-11 24,0 Q36,-11 48,0" fill="none" stroke="#0a0a10" stroke-width="5" stroke-linecap="round" transform="translate(806,308) scale(0.75)" /></g>
        </svg>
        <div id="vs-bar" style="position:absolute;left:50%;top:238px;width:170px;height:14px;margin-left:-85px;background:{accent};border-radius:7px;"></div>
        <h1 id="vs-head" style="position:absolute;left:70px;top:286px;width:940px;text-align:center;font-size:84px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;text-shadow:0 6px 44px rgba(0,0,0,0.55);">{esc(fields.get("headline") or "")}</h1>
{sub_clip}
      </div>"""
    timeline = """      tl.fromTo("#vs-hill-far", { y: 70 }, { y: 0, duration: 1.1, ease: "power3.out" }, 0.15);
      tl.fromTo("#vs-hill-mid", { y: 100 }, { y: 0, duration: 1.15, ease: "power3.out" }, 0.3);
      tl.fromTo("#vs-hill-near", { y: 130 }, { y: 0, duration: 1.2, ease: "power3.out" }, 0.45);
      tl.to("#vs-sun", { attr: { cy: 1052 }, duration: 2.9, ease: "power2.out" }, 0.5);
      tl.to("#vs-glow", { opacity: 0.16, duration: 2.2, ease: "power2.out" }, 0.5);
      tl.to("#vs-stars", { opacity: 0, duration: 1.6, ease: "power1.inOut" }, 2.7);
      tl.to("#vs-river", { strokeDashoffset: 0, duration: 1.9, ease: "power2.inOut" }, 2.5);
      tl.to("#vs-cloud-0", { opacity: 1, duration: 1.2, ease: "power1.out" }, 0.7);
      tl.to("#vs-cloud-1", { opacity: 1, duration: 1.2, ease: "power1.out" }, 0.85);
      tl.to("#vs-cloud-2", { opacity: 1, duration: 1.2, ease: "power1.out" }, 1.0);
      tl.fromTo("#vs-cloud-0", { x: -30 }, { x: 96, duration: 8, ease: "none" }, 0);
      tl.fromTo("#vs-cloud-1", { x: 24 }, { x: 132, duration: 8, ease: "none" }, 0);
      tl.fromTo("#vs-cloud-2", { x: -12 }, { x: 64, duration: 8, ease: "none" }, 0);
      tl.to("#vs-bird-0", { opacity: 0.85, duration: 0.8, ease: "power1.out" }, 3.4);
      tl.to("#vs-bird-1", { opacity: 0.85, duration: 0.8, ease: "power1.out" }, 3.7);
      tl.to("#vs-bird-0", { x: -150, duration: 4.4, ease: "none" }, 3.4);
      tl.to("#vs-bird-1", { x: -120, duration: 4.1, ease: "none" }, 3.7);
      tl.fromTo("#vs-bar", { scaleX: 0, transformOrigin: "center" }, { scaleX: 1, duration: 0.45, ease: "expo.out" }, 2.3);
      tl.fromTo("#vs-head", { opacity: 0, y: 36 }, { opacity: 1, y: 0, duration: 0.65, ease: "expo.out" }, 2.45);"""
    if sub:
        timeline += """
      tl.fromTo("#vs-sub", { opacity: 0, y: 22 }, { opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }, 2.85);"""
    timeline += f"""
      tl.to("#vs-clip", {{ opacity: 0, duration: 0.55, ease: "power1.in" }}, {duration - 0.6:g});"""
    return _hf_page(duration, accent, clips, timeline)


def _hf_story_page(fields: dict) -> str:
    """The animated story short's composition: the town scene
    script draws the film on a canvas, the story words ride as
    timed panels over it, and the worker writes the synthesized
    score beside this file as mix.wav before rendering."""
    import html as _html
    import json as _json

    esc = _html.escape
    title = fields.get("title") or ""
    lines = [ln for ln in (fields.get("lines") or "").split("\n") if ln.strip()]
    accent = fields.get("color") or "#6366f1"
    plan = hf_story_plan(title, lines)
    duration = plan[-1]["b"]
    props = {"title": title, "lines": lines, "color": accent,
             "duration": duration, "scenes": plan}
    props_js = _json.dumps(props).replace("</", "<\\/")
    title_span = plan[0]
    outro_span = plan[-1]
    clips = [
        f"""      <canvas id="gl" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" width="1080" height="1920" style="position:absolute;left:0;top:0;width:1080px;height:1920px;"></canvas>""",
        f"""      <audio id="mix" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="8" src="mix.wav"></audio>""",
        f"""      <div id="story-title" class="clip" data-start="0" data-duration="{title_span["b"]:g}" data-track-index="2" style="position:absolute;left:0;top:0;width:1080px;height:1920px;opacity:0;">
        <div id="story-bar" style="position:absolute;left:50%;top:796px;width:170px;height:14px;margin-left:-85px;background:{accent};border-radius:7px;"></div>
        <h1 style="position:absolute;left:70px;top:852px;width:940px;text-align:center;font-size:88px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;text-shadow:0 6px 44px rgba(0,0,0,0.55);">{esc(title)}</h1>
      </div>""",
    ]
    timeline = [
        """      tl.fromTo("#story-bar", { scaleX: 0, transformOrigin: "center" }, { scaleX: 1, duration: 0.55, ease: "expo.out" }, 0.3);""",
        """      tl.fromTo("#story-title", { opacity: 0, y: 44 }, { opacity: 1, y: 0, duration: 0.7, ease: "expo.out" }, 0.45);""",
        f"""      tl.to("#story-title", {{ opacity: 0, y: -30, duration: 0.45, ease: "power2.in" }}, {max(0.6, title_span["b"] - 0.5):g});""",
    ]
    for span in plan:
        if span["kind"] != "line":
            continue
        i = span["line"]
        a, b = span["a"], span["b"]
        clips.append(f"""      <div id="story-line-{i}" class="clip" data-start="{a:g}" data-duration="{b - a:g}" data-track-index="3" style="position:absolute;left:64px;bottom:118px;width:952px;opacity:0;background:rgba(10,10,16,0.58);border-radius:30px;padding:38px 44px;">
        <p style="font-size:52px;font-weight:600;line-height:1.32;color:#f7f4ec;text-shadow:0 2px 18px rgba(0,0,0,0.4);">{esc(lines[i])}</p>
      </div>""")
        timeline.append(f"""      tl.fromTo("#story-line-{i}", {{ opacity: 0, y: 46 }}, {{ opacity: 1, y: 0, duration: 0.6, ease: "expo.out" }}, {a + 0.3:g});""")
        timeline.append(f"""      tl.to("#story-line-{i}", {{ opacity: 0, y: -26, duration: 0.45, ease: "power2.in" }}, {b - 0.5:g});""")
    clips.append(f"""      <div id="story-outro" class="clip" data-start="{outro_span["a"]:g}" data-duration="{outro_span["b"] - outro_span["a"]:g}" data-track-index="2" style="position:absolute;left:0;top:0;width:1080px;height:1920px;opacity:0;">
        <h1 style="position:absolute;left:70px;top:826px;width:940px;text-align:center;font-size:64px;font-weight:800;line-height:1.15;text-shadow:0 6px 44px rgba(0,0,0,0.55);">{esc(title)}</h1>
        <p style="position:absolute;left:70px;top:1000px;width:940px;text-align:center;font-size:40px;color:#d8d5cc;">The end</p>
      </div>
      <div id="story-fade" style="position:absolute;left:0;top:0;width:1080px;height:1920px;background:#000000;opacity:0;"></div>""")
    timeline.append(f"""      tl.fromTo("#story-outro", {{ opacity: 0, y: 30 }}, {{ opacity: 1, y: 0, duration: 0.7, ease: "expo.out" }}, {outro_span["a"] + 0.35:g});""")
    timeline.append(f"""      tl.to("#story-fade", {{ opacity: 1, duration: 0.6, ease: "power1.in" }}, {duration - 0.6:g});""")
    clips_js = "\n".join(clips)
    timeline_js = "\n".join(timeline)
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1080, height=1920" />
    <script src="gsap.min.js"></script>
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}
      html, body {{ margin: 0; width: 1080px; height: 1920px; overflow: hidden; background: #0c0c0f; }}
      #root {{ position: relative; width: 1080px; height: 1920px; background: #0c0c0f;
        font-family: sans-serif; color: #f4f4f1; overflow: hidden; }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0"
      data-duration="{duration:g}" data-width="1080" data-height="1920" data-fps="24">
{clips_js}
    </div>
    <script>window.__motion = {props_js};</script>
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
{timeline_js}
      window.__timelines["main"] = tl;
    </script>
    <script src="motion-scene.js"></script>
  </body>
</html>
"""


