def _hf_forge3d_page(template_id: str, fields: dict) -> str:
    """A 3D motion template's composition: the forge3d scene
    bundle draws the scene on the canvas from the props, and
    the words ride as timed panels over it, the story page's
    shape with a lighter shell. Bars 3D carries its values in
    the scene itself, so it takes only its title as a panel."""
    import html as _html
    import json as _json

    esc = _html.escape
    spec = HF_TEMPLATES[template_id]
    duration = float(spec["duration"])
    accent = fields.get("color") or "#6366f1"
    props = {"template": template_id, "color": accent,
             "duration": duration}
    if template_id == "bars3d":
        props["points"] = fields.get("points") or []
    if template_id == "showcase3d":
        props["photo"] = fields.get("photo") or "photo.jpg"
    props_js = _json.dumps(props).replace("</", "<\\/")
    headline = fields.get("headline") or fields.get("title") or ""
    subline = fields.get("subline") or ""
    sub_clip = (
        f"""        <p id="forge3d-sub" style="position:absolute;left:70px;top:236px;width:940px;text-align:center;font-size:42px;font-weight:400;color:#d8d5cc;text-shadow:0 4px 30px rgba(0,0,0,0.6);opacity:0;">{esc(subline)}</p>"""
        if subline else "")
    clips = f"""      <canvas id="gl" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" width="1080" height="1920" style="position:absolute;left:0;top:0;width:1080px;height:1920px;"></canvas>
      <div id="forge3d-title" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="2" style="position:absolute;left:0;top:0;width:1080px;height:1920px;">
        <div id="forge3d-bar" style="position:absolute;left:50%;top:120px;width:170px;height:14px;margin-left:-85px;background:{accent};border-radius:7px;"></div>
        <h1 id="forge3d-head" style="position:absolute;left:70px;top:160px;width:940px;text-align:center;font-size:76px;font-weight:800;line-height:1.12;letter-spacing:-0.01em;text-shadow:0 6px 44px rgba(0,0,0,0.55);opacity:0;">{esc(headline)}</h1>
{sub_clip}
      </div>
      <div id="forge3d-fade" style="position:absolute;left:0;top:0;width:1080px;height:1920px;background:#000000;opacity:0;"></div>"""
    # The title choreography follows the principles pass
    # (2026-11-26): the accent bar draws in first
    # (anticipation), the headline lands on an expo-out
    # entrance, and the subline arrives after it as the
    # follow-through layer instead of appearing with it.
    sub_tl = (
        f"""      tl.fromTo("#forge3d-sub", {{ opacity: 0, y: 14 }}, {{ opacity: 1, y: 0, duration: 0.5, ease: "power3.out" }}, 1.05);
"""
        if subline else "")
    timeline = f"""      tl.fromTo("#forge3d-bar", {{ scaleX: 0, transformOrigin: "center" }}, {{ scaleX: 1, duration: 0.45, ease: "expo.out" }}, 0.3);
      tl.fromTo("#forge3d-head", {{ opacity: 0, y: 36 }}, {{ opacity: 1, y: 0, duration: 0.65, ease: "expo.out" }}, 0.45);
{sub_tl}      tl.to("#forge3d-fade", {{ opacity: 1, duration: 0.55, ease: "power1.in" }}, {duration - 0.55:g});"""
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1080, height=1920" />
    <script src="gsap.min.js"></script>
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}
      html, body {{ margin: 0; width: 1080px; height: 1920px; overflow: hidden; background: #0c0c0f; }}
      #root {{ position: relative; width: 1080px; height: 1920px; background: #0c0c0f;
        font-family: sans-serif; color: #f4f4f1; overflow: hidden; }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0"
      data-duration="{duration:g}" data-width="1080" data-height="1920" data-fps="24">
{clips}
    </div>
    <script>window.__motion = {props_js};</script>
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
{timeline}
      window.__timelines["main"] = tl;
    </script>
    <script src="forge3d-scene.js"></script>
  </body>
</html>
"""


def _hf_presenter_page(fields: dict) -> str:
    """The photo presenter's composition: the presenter scene
    bundle draws the talking photo on the canvas, the worker
    stages the photo under its own name beside this file,
    writes the voiceover as voice.wav and the mouth curve as
    mouth-curve.js, and the voice rides as the audio clip.
    The claim path fills duration and photo into the fields
    before building, so what renders is exactly what the
    worker staged."""
    import json as _json

    duration = float(fields.get("duration") or 0)
    accent = fields.get("color") or "#6366f1"
    props = {"color": accent, "duration": duration,
             "photo": fields.get("photo") or "photo.jpg",
             "mouthX": fields.get("mouth_x") or 50.0,
             "mouthY": fields.get("mouth_y") or 68.0}
    props_js = _json.dumps(props).replace("</", "<\\/")
    return f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1080, height=1920" />
    <script src="gsap.min.js"></script>
    <style>
      * {{ margin: 0; padding: 0; box-sizing: border-box; }}
      html, body {{ margin: 0; width: 1080px; height: 1920px; overflow: hidden; background: #0c0c0f; }}
      #root {{ position: relative; width: 1080px; height: 1920px; background: #0c0c0f;
        font-family: sans-serif; color: #f4f4f1; overflow: hidden; }}
    </style>
  </head>
  <body>
    <div id="root" data-composition-id="main" data-start="0"
      data-duration="{duration:g}" data-width="1080" data-height="1920" data-fps="24">
      <canvas id="gl" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="0" width="1080" height="1920" style="position:absolute;left:0;top:0;width:1080px;height:1920px;"></canvas>
      <audio id="voice" class="clip" data-start="0" data-duration="{duration:g}" data-track-index="8" src="voice.wav"></audio>
    </div>
    <script>window.__motion = {props_js};</script>
    <script src="mouth-curve.js"></script>
    <script>
      window.__timelines = window.__timelines || {{}};
      const tl = gsap.timeline({{ paused: true }});
      window.__timelines["main"] = tl;
    </script>
    <script src="presenter-scene.js"></script>
  </body>
</html>
"""


def hf_kaggle_push(token: str, script_text: str) -> tuple:
    """Start a worker run: one SaveKernel call against Kaggle's
    public API, pushing a fresh version of the worker kernel,
    which is what makes Kaggle run it. Returns (ok, detail). The
    token rides in the Authorization header only; nothing about
    it is logged here."""
    return kaggle_push(
        token, script_text, slug=HF_KERNEL_SLUG,
        title="Moonfactory Hyperframes Worker",
        datasets=[HF_TOOLCHAIN_DATASET, HF_KEY_DATASET], gpu=False)


def kaggle_push(token: str, script_text: str, slug: str,
                title: str, datasets: list, gpu: bool) -> tuple:
    """The general kernel push both Kaggle workers ride: one
    SaveKernel call against Kaggle's public API, pushing a
    fresh version of the worker kernel, which is what makes
    Kaggle run it. Returns (ok, detail). The token rides in
    the Authorization header only; nothing about it is logged
    here."""
    import requests as _requests

    payload = {
        # The push endpoint's "id" field is the numeric kernel id;
        # a kernel is created and addressed by its string "slug".
        "slug": slug,
        "newTitle": title,
        "text": script_text,
        "language": "python",
        "kernelType": "script",
        "isPrivate": True,
        "enableGpu": gpu,
        "enableTpu": False,
        "enableInternet": True,
        "datasetDataSources": datasets,
        "competitionDataSources": [],
        "kernelDataSources": [],
        "modelDataSources": [],
        "categoryIds": [],
    }
    try:
        resp = _requests.post(
            "https://www.kaggle.com/api/v1/kernels/push",
            headers={"Authorization": f"Bearer {token}"},
            json=payload, timeout=60,
        )
    except Exception as exc:
        return False, f"request failed: {exc}"[:200]
    if resp.status_code != 200:
        return False, f"kaggle answered {resp.status_code}"
    try:
        body = resp.json()
    except Exception:
        body = {}
    if body.get("error"):
        return False, str(body.get("error"))[:200]
    return True, "kernel version pushed"


