    @web.get("/api/challenge")
    def challenge(request: Request):
        if _rate_limited("challenge", client_ip(request), 30):
            raise HTTPException(status_code=429, detail="too many requests")
        challenge_id = pysecrets.token_hex(8)
        challenge = pysecrets.token_hex(16)
        meta[f"pow:{challenge_id}"] = {
            "challenge": challenge,
            "expires": _now() + 600,
            "used": False,
        }
        return {"challenge_id": challenge_id, "challenge": challenge,
                "difficulty_bits": POW_DIFFICULTY_BITS}

    # -- accounts ----------------------------------------------------------

    # Pending creations (entry flow, Jack, 2026-11-19): a signed
    # out visitor builds a whole creation and hits a create
    # button; the sign-up stores that creation on the new
    # account, and the verified return claims it, restores the
    # form, and fires it once. File payloads cannot survive the
    # email round trip, so the file fields never enter the
    # record: their names land in file_missing instead, and the
    # restored form asks for the file again before firing. Bot
    # check fields never enter either; the fire runs a fresh
    # check, like every submit.
    PENDING_CREATE_KINDS = (
        "video", "motion", "title", "short", "image", "first-frame",
        "drama")
    PENDING_FILE_FIELDS = {
        "start_image_png_b64": "start_image",
        "end_image_png_b64": "end_image",
        "source_image": "edit_image",
        "upload_id": "captions_clip",
    }
    PENDING_BOT_FIELDS = (
        "turnstile_token", "challenge_id", "challenge_nonce")

    def _clean_pending_create(value):
        """Validate and shrink one pending creation for storage
        on an account record. Returns the stored shape, or None
        when the value is not a creation this platform knows."""
        if not isinstance(value, dict):
            return None
        kind = value.get("kind")
        if kind not in PENDING_CREATE_KINDS:
            return None
        body = value.get("body")
        if not isinstance(body, dict):
            return None
        missing = []
        clean = {}
        for key, val in body.items():
            if key in PENDING_BOT_FIELDS:
                continue
            if key in PENDING_FILE_FIELDS:
                if val:
                    missing.append(PENDING_FILE_FIELDS[key])
                continue
            clean[key] = val
        if clean.get("model") == "magi2":
            # MAGI-2 references (2026-11-26): a reference file
            # rides as a data URL, which no pending record can
            # hold (the size cap above would refuse the whole
            # creation), so attached files are dropped from the
            # parked body and named as missing instead, the
            # same treatment every other file field gets.
            # Hosted references (https URLs) park as they are.
            # The instruction notes are rebuilt in step, so a
            # note never points at a reference that is gone.
            for arr_key, note_key in (
                    ("reference_image_urls", "images"),
                    ("reference_video_urls", "videos"),
                    ("reference_audio_urls", "audios")):
                arr = clean.get(arr_key)
                if not isinstance(arr, list):
                    continue
                notes_in = None
                all_notes = clean.get("reference_notes")
                if isinstance(all_notes, dict) and isinstance(
                        all_notes.get(note_key), list):
                    notes_in = all_notes[note_key]
                kept, kept_notes = [], []
                for i, item in enumerate(arr):
                    if isinstance(item, str) and \
                            item.startswith("data:"):
                        continue
                    kept.append(item)
                    kept_notes.append(
                        notes_in[i] if notes_in is not None
                        and i < len(notes_in) else "")
                if len(kept) != len(arr):
                    if "your reference files" not in missing:
                        missing.append("your reference files")
                    clean[arr_key] = kept
                    if isinstance(all_notes, dict):
                        all_notes[note_key] = kept_notes
                    sheet = clean.get("character_sheet_video")
                    if sheet is not None and arr_key == \
                            "reference_video_urls":
                        # The sheet flag counts into the
                        # original video order; a dropped file
                        # ahead of it shifts it, and a dropped
                        # sheet clears it.
                        try:
                            sheet = int(sheet)
                            dropped_before = sum(
                                1 for item in arr[:sheet + 1]
                                if isinstance(item, str)
                                and item.startswith("data:"))
                            if sheet < len(arr) and isinstance(
                                    arr[sheet], str) and \
                                    arr[sheet].startswith(
                                        "data:"):
                                clean[
                                    "character_sheet_video"] = None
                            else:
                                clean[
                                    "character_sheet_video"] = \
                                    sheet - dropped_before
                        except (TypeError, ValueError):
                            clean["character_sheet_video"] = None
        for name in value.get("file_missing") or []:
            if name in PENDING_FILE_FIELDS.values() and name not in missing:
                missing.append(name)
        if len(json.dumps(clean)) > 32768:
            return None
        return {"kind": kind, "body": clean, "file_missing": missing}

    @web.post("/api/signup")
    async def signup(request: Request):
        ip = client_ip(request)
        if _rate_limited("signup", ip, 5):
            raise HTTPException(status_code=429, detail="too many signups, slow down")
        body = await request.json()
        email = (body.get("email") or "").strip().lower()
        password = body.get("password") or ""
        if "@" not in email or "." not in email.split("@")[-1] or len(email) > 254:
            raise HTTPException(status_code=422, detail="a valid email is required")
        if len(password) < 8:
            raise HTTPException(status_code=422, detail="password must be at least 8 characters")
        # Legal acceptance (Jack, 2026-11-24): the endpoint
        # itself refuses a create that does not carry the
        # acceptance, whatever the client sent, and refuses
        # before the bot check so an unchecked attempt costs
        # nothing and parks nothing.
        acceptance = legal_acceptance_stamp(body)
        if acceptance is None:
            raise HTTPException(status_code=422,
                                detail=LEGAL_ACCEPTANCE_REQUIRED)
        if not _verify_bot_check(body, ip):
            raise HTTPException(status_code=403, detail="bot check failed")
        if users.get(f"email:{email}"):
            raise HTTPException(status_code=409, detail="an account with this email already exists")
        user = {
            "id": pysecrets.token_hex(8),
            "email": email,
            "pw": _hash_password(password),
            "terms_accepted_at": acceptance["accepted_at"],
            "legal_version": acceptance["legal_version"],
            "verified": False,
            "created_at": _now(),
            "plan": "free",
            "handle": None,
            "gallery_opt_out": False,
            "past_due": False,
            "balance_cents": 0,
            "net_paid_cents": 0.0,
            "cost_settled_cents": 0.0,
            "free_jobs_total": 0,
            "usage": {"period": _period(), "free_jobs": 0, "included_seconds": 0.0,
                      "included_cost_cents": 0.0},
        }
        # A creation built while signed out rides the sign-up
        # and waits on the account for the verified return.
        pending = _clean_pending_create(body.get("pending_create"))
        if pending:
            user["pending_create"] = pending
        save_user(user)
        # The acceptance log (Jack, 2026-11-24): the sign-up
        # acceptance joins the append only evidence trail,
        # behind the stamp fields on the record above.
        record_acceptance(user, ACCEPTANCE_SIGNUP_LEGAL,
                          legal_version=acceptance["legal_version"])
        token = pysecrets.token_urlsafe(32)
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        meta[f"verify:{token_hash}"] = {"user_id": user["id"], "expires": _now() + 24 * 3600}
        link = f"{base_url(request)}/api/verify?token={token}"
        mode = _send_email(
            email,
            "Verify your Moonfactory account",
            "Welcome to Moonfactory.\n\n"
            "Open the link below to verify your email.\n"
            f"{link}\n\n"
            "The link works for 24 hours. If you did not sign up, ignore this email.\n",
        )
        return {"status": "pending_verification", "email_mode": mode}

    @web.get("/api/verify")
    def verify(token: str, request: Request):
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        record = meta.get(f"verify:{token_hash}")
        if not record or record["expires"] < _now():
            raise HTTPException(status_code=400, detail="this verification link is invalid or expired")
        user = users.get(f"id:{record['user_id']}")
        if not user:
            raise HTTPException(status_code=400, detail="account not found")
        user["verified"] = True
        save_user(user)
        meta[f"verify:{token_hash}"] = {"user_id": record["user_id"], "expires": 0}
        return RedirectResponse(url="/app?verified=1", status_code=303)

    @web.post("/api/login")
    async def login(request: Request):
        ip = client_ip(request)
        if _rate_limited("login", ip, 10):
            raise HTTPException(status_code=429, detail="too many attempts, slow down")
        body = await request.json()
        email = (body.get("email") or "").strip().lower()
        # Progressive per-account delay (security fix,
        # 2026-11-27, login-no-botcheck-scrypt): login has no
        # bot-check token channel in the shipped client, so
        # the cost is imposed here instead -- after five
        # failures the account demands a growing pause
        # between attempts (2, 4, 8 ... up to 300 seconds),
        # keyed by account, so rotating IPs buys nothing.
        # An unknown email spends the same scrypt against a
        # dummy hash, so existence is not oracleable by cost
        # or timing either.
        fail_key = f"loginfail:{email}"
        fails = meta.get(fail_key) or {"count": 0, "last": 0}
        if _now() - float(fails.get("last") or 0) > 3600:
            fails = {"count": 0, "last": 0}
        if int(fails.get("count") or 0) >= 5:
            wait = min(2 ** (int(fails["count"]) - 5), 300)
            if _now() - float(fails.get("last") or 0) < wait:
                raise HTTPException(
                    status_code=429,
                    detail="too many attempts, slow down")
        user = users.get(f"email:{email}")
        if not user:
            _check_password(body.get("password") or "",
                            _DUMMY_PW_HASH)
            meta[fail_key] = {
                "count": int(fails.get("count") or 0) + 1,
                "last": _now()}
            raise HTTPException(status_code=401, detail="email or password is wrong")
        if not _check_password(body.get("password") or "", user["pw"]):
            meta[fail_key] = {
                "count": int(fails.get("count") or 0) + 1,
                "last": _now()}
            raise HTTPException(status_code=401, detail="email or password is wrong")
        if fail_key in meta:
            del meta[fail_key]
        if user.get("verified") is False:
            # Security fix (2026-11-27, pre-account-takeover):
            # a password proves nothing until the mailbox has
            # been verified once; before that, anyone could
            # have registered it. The reset flow below is the
            # way back in: its link goes to the mailbox and
            # verifies the account as it sets the password.
            raise HTTPException(
                status_code=403,
                detail="verify your email first. Use the link from sign up, or reset your password to get a fresh one")
        resp = JSONResponse({"status": "ok", "user": public_user(user)})
        resp.set_cookie(
            "mf_session", _make_session(user["id"],
                                        user.get("session_epoch", "")),
            max_age=7 * 24 * 3600, httponly=True, samesite="lax", secure=True,
        )
        return resp

    # -- Social sign-in: Google (Jack, 2026-11-25) ------------
    # The dialog's Continue with Google runs the standard
    # authorization code flow, wired end to end in code and
    # live the moment the deployment carries the credentials:
    # with no GOOGLE_OAUTH_CLIENT_ID / GOOGLE_OAUTH_CLIENT_SECRET
    # in the secret the start route 404s and /api/config tells
    # the studio to keep the button hidden, so a button that
    # cannot answer never ships. Accounts resolve by the email
    # Google has verified: an existing account signs in (and
    # its email counts as verified from this sign-in, Google
    # proved the mailbox), a new email creates the account on
    # the spot, already verified. A creation built while
    # signed out rides the round trip parked server side and
    # lands on the account, the same one home the sign-up
    # path uses, and the verified return claims and fires it.
    # The acceptance mechanism differs from the email form in
    # exactly one way: there is no checkbox on this path. The
    # dialog's by-continuing line (Terms, Privacy Policy, and
    # Acceptable Use Policy, named with links under the
    # buttons) is what the click accepts, so a new account
    # stamps terms_accepted_at and LEGAL_VERSION at creation
    # and writes the same signup_legal entry to the append
    # only acceptance log the checkbox path writes.

    def _google_oauth_configured() -> bool:
        return bool(os.environ.get("GOOGLE_OAUTH_CLIENT_ID")
                    and os.environ.get("GOOGLE_OAUTH_CLIENT_SECRET"))

    @web.post("/api/auth/park")
    async def oauth_park(request: Request):
        """Park a signed out visitor's creation for the social
        sign-in round trip; the park id rides the OAuth state
        and the callback lands the creation on the account."""
        ip = client_ip(request)
        if _rate_limited("oauth-park", ip, 5):
            raise HTTPException(status_code=429, detail="too many attempts, slow down")
        body = await request.json()
        pending = _clean_pending_create(body.get("pending_create"))
        if not pending:
            raise HTTPException(status_code=422, detail="that creation cannot be saved")
        park_id = pysecrets.token_urlsafe(18)
        # Security fix (2026-11-27, oauth-park-unbound): the
        # park is bound to the browser that parked it. A
        # nonce cookie is set here and only its hash is
        # stored; the OAuth callback lands the creation only
        # when the returning browser presents the same nonce,
        # so a park id leaked or planted in another browser's
        # sign-in flow claims nothing.
        bind = pysecrets.token_urlsafe(24)
        meta[f"oauth-park:{park_id}"] = {
            "pending_create": pending, "expires": _now() + 30 * 60,
            "bind_hash": hashlib.sha256(bind.encode()).hexdigest()}
        resp = JSONResponse({"park": park_id})
        resp.set_cookie("mf_park_bind", bind, max_age=30 * 60,
                        httponly=True, samesite="lax", secure=True, path="/")
        return resp

    def _oauth_bind_ok(request: Request, record) -> bool:
        """The OAuth state is bound to the browser that
        started the flow (security fix, 2026-11-27,
        oauth-state-not-browser-bound): the start route sets
        a nonce cookie and stores only its hash in the state
        record; the callback requires the same browser back,
        so a callback URL captured or planted in another
        browser signs nobody in (login CSRF)."""
        want = (record or {}).get("bind_hash") or ""
        got = request.cookies.get("mf_oauth_bind") or ""
        if not want or not got:
            return False
        digest = hashlib.sha256(got.encode()).hexdigest()
        return hmac.compare_digest(digest, want)

    def _land_parked_create(user: dict, record, request: Request):
        """Land a parked creation on a freshly signed in
        account, under the park rules (security fix,
        2026-11-27, oauth-park-unbound-pending-create):
        only for the browser that parked it, never over a
        creation the account already holds from its own
        session, and always flagged needs_confirm so the
        studio shows it for an explicit start instead of
        firing it on sign-in."""
        park_id = (record or {}).get("park") or ""
        if not park_id:
            return
        parked = meta.get(f"oauth-park:{park_id}")
        if not parked or parked.get("expires", 0) <= _now() \
                or not parked.get("pending_create"):
            return
        bind = request.cookies.get("mf_park_bind") or ""
        want = parked.get("bind_hash") or ""
        if not bind or not want or not hmac.compare_digest(
                hashlib.sha256(bind.encode()).hexdigest(), want):
            return
        meta[f"oauth-park:{park_id}"] = {
            "pending_create": None, "expires": 0}
        if user.get("pending_create"):
            return
        pending = dict(parked["pending_create"])
        pending["needs_confirm"] = True
        user["pending_create"] = pending
        save_user(user)

    @web.get("/api/auth/google/start")
    def google_oauth_start(request: Request, park: str = ""):
        import urllib.parse

        if not _google_oauth_configured():
            raise HTTPException(status_code=404, detail="not found")
        park_id = ""
        if park:
            record = meta.get(f"oauth-park:{park}")
            if record and record.get("expires", 0) > _now():
                park_id = park
        state = pysecrets.token_urlsafe(24)
        bind = pysecrets.token_urlsafe(24)
        meta[f"oauth-state:{state}"] = {
            "park": park_id, "expires": _now() + 10 * 60,
            "bind_hash": hashlib.sha256(bind.encode()).hexdigest()}
        query = urllib.parse.urlencode({
            "client_id": os.environ["GOOGLE_OAUTH_CLIENT_ID"],
            "redirect_uri": f"{base_url(request)}/api/auth/google/callback",
            "response_type": "code",
            "scope": "openid email profile",
            "state": state,
        })
        resp = RedirectResponse(
            url=f"https://accounts.google.com/o/oauth2/v2/auth?{query}",
            status_code=303)
        resp.set_cookie("mf_oauth_bind", bind, max_age=10 * 60,
                        httponly=True, samesite="lax", secure=True, path="/api/auth")
        return resp

    @web.get("/api/auth/google/callback")
    def google_oauth_callback(request: Request, code: str = "",
                              state: str = "", error: str = ""):
        def fail():
            return RedirectResponse(url="/app?oauth=error",
                                    status_code=303)

        if not _google_oauth_configured() or error or not code \
                or not state:
            return fail()
        record = meta.get(f"oauth-state:{state}")
        if not record or record.get("expires", 0) < _now():
            return fail()
        if not _oauth_bind_ok(request, record):
            return fail()
        # One time: the state is spent whatever happens next.
        meta[f"oauth-state:{state}"] = {"park": "", "expires": 0}
        try:
            token_resp = requests.post(
                "https://oauth2.googleapis.com/token",
                data={
                    "code": code,
                    "client_id": os.environ["GOOGLE_OAUTH_CLIENT_ID"],
                    "client_secret":
                        os.environ["GOOGLE_OAUTH_CLIENT_SECRET"],
                    "redirect_uri":
                        f"{base_url(request)}/api/auth/google/callback",
                    "grant_type": "authorization_code",
                }, timeout=15)
            if token_resp.status_code != 200:
                return fail()
            access_token = token_resp.json().get("access_token")
            if not access_token:
                return fail()
            info_resp = requests.get(
                "https://openidconnect.googleapis.com/v1/userinfo",
                headers={"Authorization": f"Bearer {access_token}"},
                timeout=15)
            if info_resp.status_code != 200:
                return fail()
            info = info_resp.json()
        except Exception:  # noqa: BLE001
            return fail()
        email = (info.get("email") or "").strip().lower()
        # Only a Google-verified email can create or enter an
        # account here; anything else is not an identity.
        if not email or info.get("email_verified") is not True:
            return fail()
        user = users.get(f"email:{email}")
        if not user:
            # A new account from a provider-verified email: the
            # record mirrors sign-up's, with no password (the
            # provider is the credential, so password sign-in
            # simply never matches), the acceptance stamped
            # from the by-continuing line, and the email already
            # verified by Google.
            user = {
                "id": pysecrets.token_hex(8),
                "email": email,
                "pw": "",
                "auth_provider": "google",
                "terms_accepted_at": _now(),
                "legal_version": LEGAL_VERSION,
                "verified": True,
                "created_at": _now(),
                "plan": "free",
                "handle": None,
                "gallery_opt_out": False,
                "past_due": False,
                "balance_cents": 0,
                "net_paid_cents": 0.0,
                "cost_settled_cents": 0.0,
                "free_jobs_total": 0,
                "usage": {"period": _period(), "free_jobs": 0,
                          "included_seconds": 0.0,
                          "included_cost_cents": 0.0},
            }
            save_user(user)
            record_acceptance(user, ACCEPTANCE_SIGNUP_LEGAL,
                              legal_version=LEGAL_VERSION)
        elif not user.get("verified"):
            # Google proved this mailbox, so an account still
            # waiting on its verification link is verified by
            # this sign-in. Security fix (2026-11-27,
            # pre-account-takeover): a password set before
            # this moment was registered by whoever held the
            # address first, and the mailbox owner may never
            # have chosen it, so it does not survive the
            # merge. The owner sets a new one through the
            # verified reset flow or the account panel.
            user["verified"] = True
            if user.get("pw"):
                user["pw"] = ""
                user["pw_cleared_by_social_merge"] = True
            save_user(user)
        _land_parked_create(user, record, request)
        resp = RedirectResponse(url="/app", status_code=303)
        resp.set_cookie(
            "mf_session", _make_session(user["id"],
                                        user.get("session_epoch", "")),
            max_age=7 * 24 * 3600, httponly=True, samesite="lax", secure=True,
        )
        return resp

    # -- Social sign-in: X and Telegram (Jack, 2026-11-25) ---
    # Jack's call, made knowing the trade: neither X nor
    # Telegram can hand this platform a verified email (X's
    # OAuth user lookup returns none; Telegram's login returns
    # a Telegram identity only). These accounts are therefore
    # keyed by the provider's own user id instead of an email:
    # no email on the record, no password (password sign-in
    # simply never matches, exactly as with Google accounts),
    # no verification step (the provider is the verification),
    # and the acceptance stamps exactly as the Google path
    # stamps it, because the dialog's by-continuing line is on
    # screen when the button is clicked. Everything downstream
    # (sessions, free clips, the 18+ gate, billing) reads the
    # same user record and never learns the difference.
    # X runs the redirect flow, mirroring Google's shape with
    # PKCE added (X requires it): start, one-time server-side
    # state spent before the token exchange, user lookup.
    # Telegram is not a redirect flow at all: its Login Widget
    # answers in the page, the browser posts the widget's
    # payload here, and the payload is believed only after the
    # HMAC check against the bot token passes and its
    # auth_date is fresh. A creation built while signed out
    # never leaves the page on the Telegram path, so it fires
    # in place like the email sign-in; on the X path it rides
    # the /api/auth/park round trip like Google's.

    def _x_oauth_configured() -> bool:
        return bool(os.environ.get("X_CLIENT_ID")
                    and os.environ.get("X_CLIENT_SECRET"))

    def _telegram_bot_username() -> str:
        return (os.environ.get("TELEGRAM_BOT_USERNAME") or ""
                ).strip().lstrip("@")

    def _telegram_configured() -> bool:
        # The widget needs both halves: the bot token keys the
        # HMAC check, and the bot username names the widget.
        # The username is read from the secret rather than
        # derived with a getMe call, so /api/config answers
        # without a network call and the state is exact.
        return bool(os.environ.get("TELEGRAM_BOT_TOKEN")
                    and _telegram_bot_username())

    def _provider_account(provider: str, provider_id: str,
                          display_name: str = "") -> dict:
        """Resolve the account a provider identity owns, or
        create it on first sign-in. The provider index is only
        a pointer: the record is reloaded through the id index
        (the one sessions resolve) before it is trusted, so a
        stamp written anywhere else (a suspension, a session
        epoch) is the record the sign-in sees."""
        found = users.get(f"{provider}:{provider_id}")
        user = None
        if found:
            user = users.get(f"id:{found['id']}") or found
        if user is not None:
            if display_name \
                    and user.get("display_name") != display_name:
                user["display_name"] = display_name
                save_user(user)
            return user
        # A new account from a provider identity: the record
        # mirrors the Google path's, with the provider's user
        # id in place of the email, the profile's display name
        # where the provider gave one, the acceptance stamped
        # from the by-continuing line, and the account already
        # verified (the provider proved the identity).
        user = {
            "id": pysecrets.token_hex(8),
            "email": None,
            "pw": "",
            "auth_provider": provider,
            "provider_id": str(provider_id),
            "display_name": display_name or None,
            "terms_accepted_at": _now(),
            "legal_version": LEGAL_VERSION,
            "verified": True,
            "created_at": _now(),
            "plan": "free",
            "handle": None,
            "gallery_opt_out": False,
            "past_due": False,
            "balance_cents": 0,
            "net_paid_cents": 0.0,
            "cost_settled_cents": 0.0,
            "free_jobs_total": 0,
            "usage": {"period": _period(), "free_jobs": 0,
                      "included_seconds": 0.0,
                      "included_cost_cents": 0.0},
        }
        save_user(user)
        record_acceptance(user, ACCEPTANCE_SIGNUP_LEGAL,
                          legal_version=LEGAL_VERSION)
        return user

    def _social_signin_redirect(user: dict, record,
                                request: Request) -> RedirectResponse:
        """The shared tail of a redirect social sign-in: land
        the parked creation on the account and issue the login
        session cookie, the same landing the Google callback
        performs."""
        _land_parked_create(user, record, request)
        resp = RedirectResponse(url="/app", status_code=303)
        resp.set_cookie(
            "mf_session", _make_session(user["id"],
                                        user.get("session_epoch", "")),
            max_age=7 * 24 * 3600, httponly=True, samesite="lax", secure=True,
        )
        return resp

    @web.get("/api/auth/x/start")
    def x_oauth_start(request: Request, park: str = ""):
        import base64
        import urllib.parse

        if not _x_oauth_configured():
            raise HTTPException(status_code=404, detail="not found")
        park_id = ""
        if park:
            record = meta.get(f"oauth-park:{park}")
            if record and record.get("expires", 0) > _now():
                park_id = park
        # PKCE (X requires it): the verifier stays server side
        # in the state record; only its SHA256 challenge rides
        # the authorize request.
        verifier = pysecrets.token_urlsafe(48)
        challenge = base64.urlsafe_b64encode(
            hashlib.sha256(verifier.encode()).digest()
        ).decode().rstrip("=")
        state = pysecrets.token_urlsafe(24)
        bind = pysecrets.token_urlsafe(24)
        meta[f"oauth-state:x:{state}"] = {
            "park": park_id, "verifier": verifier,
            "expires": _now() + 10 * 60,
            "bind_hash": hashlib.sha256(bind.encode()).hexdigest()}
        query = urllib.parse.urlencode({
            "client_id": os.environ["X_CLIENT_ID"],
            "redirect_uri": f"{base_url(request)}/api/auth/x/callback",
            "response_type": "code",
            "scope": "tweet.read users.read",
            "state": state,
            "code_challenge": challenge,
            "code_challenge_method": "S256",
        })
        resp = RedirectResponse(
            url=f"https://twitter.com/i/oauth2/authorize?{query}",
            status_code=303)
        resp.set_cookie("mf_oauth_bind", bind, max_age=10 * 60,
                        httponly=True, samesite="lax", secure=True, path="/api/auth")
        return resp

    @web.get("/api/auth/x/callback")
    def x_oauth_callback(request: Request, code: str = "",
                         state: str = "", error: str = ""):
        def fail():
            return RedirectResponse(url="/app?oauth=error",
                                    status_code=303)

        if not _x_oauth_configured() or error or not code \
                or not state:
            return fail()
        record = meta.get(f"oauth-state:x:{state}")
        if not record or record.get("expires", 0) < _now() \
                or not record.get("verifier"):
            return fail()
        if not _oauth_bind_ok(request, record):
            return fail()
        # One time: the state (and its PKCE verifier) is spent
        # whatever happens next.
        meta[f"oauth-state:x:{state}"] = {
            "park": "", "verifier": "", "expires": 0}
        try:
            token_resp = requests.post(
                "https://api.twitter.com/2/oauth2/token",
                data={
                    "code": code,
                    "grant_type": "authorization_code",
                    "redirect_uri":
                        f"{base_url(request)}/api/auth/x/callback",
                    "code_verifier": record["verifier"],
                },
                auth=(os.environ["X_CLIENT_ID"],
                      os.environ["X_CLIENT_SECRET"]),
                timeout=15)
            if token_resp.status_code != 200:
                return fail()
            access_token = token_resp.json().get("access_token")
            if not access_token:
                return fail()
            info_resp = requests.get(
                "https://api.twitter.com/2/users/me",
                headers={"Authorization": f"Bearer {access_token}"},
                timeout=15)
            if info_resp.status_code != 200:
                return fail()
            info = (info_resp.json() or {}).get("data") or {}
        except Exception:  # noqa: BLE001
            return fail()
        x_id = str(info.get("id") or "")
        if not x_id:
            return fail()
        display_name = (info.get("name") or "").strip()
        if not display_name and info.get("username"):
            display_name = "@" + str(info["username"]).strip()
        user = _provider_account("x", x_id, display_name)
        return _social_signin_redirect(user, record, request)

    @web.post("/api/auth/telegram/login")
    async def telegram_login(request: Request):
        """The Telegram Login Widget's answer, posted by the
        studio: the payload is an identity only when its hash
        verifies against the bot token and its auth_date is
        fresh (a day old at most, and not from the future
        beyond clock skew). The session issued is the login
        session, returned the way /api/login returns it,
        because the widget answers in the page and the sign-in
        completes there."""
        ip = client_ip(request)
        if _rate_limited("telegram-login", ip, 10):
            raise HTTPException(status_code=429,
                                detail="too many attempts, slow down")
        if not _telegram_configured():
            raise HTTPException(status_code=404, detail="not found")
        body = await request.json()
        if not isinstance(body, dict):
            raise HTTPException(status_code=422,
                                detail="that sign in cannot be read")
        if not telegram_login_hash_ok(
                os.environ["TELEGRAM_BOT_TOKEN"], body):
            raise HTTPException(
                status_code=401,
                detail="that Telegram sign in could not be verified")
        try:
            tg_id = int(body.get("id") or 0)
            auth_date = int(body.get("auth_date") or 0)
        except (TypeError, ValueError):
            raise HTTPException(
                status_code=401,
                detail="that Telegram sign in could not be verified")
        if not tg_id or auth_date < _now() - 24 * 3600 \
                or auth_date > _now() + 300:
            raise HTTPException(
                status_code=401,
                detail="that Telegram sign in is out of date")
        display_name = " ".join(
            part for part in [
                str(body.get("first_name") or "").strip(),
                str(body.get("last_name") or "").strip()] if part)
        if not display_name and body.get("username"):
            display_name = "@" + str(body["username"]).strip().lstrip("@")
        user = _provider_account("telegram", str(tg_id), display_name)
        resp = JSONResponse({"status": "ok", "user": public_user(user)})
        resp.set_cookie(
            "mf_session", _make_session(user["id"],
                                        user.get("session_epoch", "")),
            max_age=7 * 24 * 3600, httponly=True, samesite="lax", secure=True,
        )
        return resp

    @web.post("/api/logout")
    def logout(request: Request, mf_session: str = Cookie(default="")):
        # Revoke first, then clear: stamping a new session epoch
        # kills the token this browser holds even if the browser
        # never applies the cookie deletion below.
        user = current_user(request, mf_session)
        if user:
            import uuid

            user["session_epoch"] = uuid.uuid4().hex
            save_user(user)
        resp = JSONResponse({"status": "ok"})
        resp.delete_cookie("mf_session")
        # Belt and braces: also expire any duplicate of the
        # cookie sitting under the studio path.
        resp.headers.append(
            "set-cookie",
            'mf_session=""; expires=Thu, 01 Jan 1970 00:00:00 GMT; '
            "Max-Age=0; Path=/app; SameSite=lax",
        )
        return resp

    @web.get("/api/me")
    def me(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        return public_user(user)

    @web.post("/api/me/pending-create")
    async def store_pending_create(request: Request,
                                   mf_session: str = Cookie(default="")):
        """Park a signed out visitor's creation on their account
        (the sign-in-before-verification path: they signed in
        with an account whose email is not verified yet, so the
        creation waits server side for the verified return)."""
        user = require_user(request, mf_session)
        body = await request.json()
        pending = _clean_pending_create(body.get("pending_create"))
        if not pending:
            raise HTTPException(status_code=422, detail="that creation cannot be saved")
        user["pending_create"] = pending
        save_user(user)
        return {"stored": True}

    def _pending_gate_texts(pending) -> str:
        """Every user authored string in a pending creation,
        joined for the illegal content gate."""
        parts = []

        def walk(value, depth=0):
            if depth > 4:
                return
            if isinstance(value, str):
                parts.append(value)
            elif isinstance(value, dict):
                for item in value.values():
                    walk(item, depth + 1)
            elif isinstance(value, list):
                for item in value[:50]:
                    walk(item, depth + 1)

        walk((pending or {}).get("body") or {})
        return "\n".join(parts)[:20000]

    @web.post("/api/me/pending-create/claim")
    async def claim_pending_create(request: Request,
                                   mf_session: str = Cookie(default="")):
        """Hand the account's pending creation to the signed in
        studio and clear it in the same step, so a creation can
        be restored and fired at most once, from any browser.

        A creation that arrived through the OAuth park (not
        authored in this session) is flagged needs_confirm:
        the first claim only shows it, and it is handed over
        for firing only when the account owner confirms
        (security fix, 2026-11-27). A confirmed claim whose
        payload is illegal is dropped silently at this point,
        without recording a refusal against the account: the
        owner never authored it in session, so the refusal
        ladder must not run against them for it."""
        user = require_user(request, mf_session)
        pending = user.get("pending_create")
        if not pending:
            return {"pending_create": None}
        body = {}
        try:
            body = await request.json()
        except Exception:  # noqa: BLE001
            body = {}
        if pending.get("needs_confirm") and not body.get("confirm"):
            return {"pending_create": pending, "needs_confirm": True}
        if pending.get("needs_confirm") \
                and prompt_is_illegal(_pending_gate_texts(pending)):
            user.pop("pending_create", None)
            save_user(user)
            return {"pending_create": None}
        user.pop("pending_create", None)
        save_user(user)
        pending = dict(pending)
        pending.pop("needs_confirm", None)
        return {"pending_create": pending}

    @web.post("/api/me/password")
    async def set_my_password(request: Request,
                              mf_session: str = Cookie(default="")):
        """Set or change the signed in account's password
        (security fix, 2026-11-27: the eviction path the
        pre-account-takeover fix needs). An account that has
        a password must prove the current one; a social
        account setting its first password is already
        authenticated by its session. Either way the session
        epoch rotates, so every other session dies here."""
        user = require_user(request, mf_session)
        body = await request.json()
        new_password = body.get("new_password") or ""
        if len(new_password) < 8:
            raise HTTPException(
                status_code=422,
                detail="password must be at least 8 characters")
        if user.get("pw"):
            if not _check_password(body.get("current_password") or "",
                                   user["pw"]):
                raise HTTPException(
                    status_code=401, detail="current password is wrong")
        user["pw"] = _hash_password(new_password)
        user.pop("pw_cleared_by_social_merge", None)
        user["session_epoch"] = uuid.uuid4().hex
        save_user(user)
        resp = JSONResponse({"status": "ok"})
        resp.set_cookie(
            "mf_session", _make_session(user["id"],
                                        user.get("session_epoch", "")),
            max_age=7 * 24 * 3600, httponly=True, samesite="lax", secure=True)
        return resp

    @web.post("/api/auth/password-reset/request")
    async def password_reset_request(request: Request):
        """Email a password reset link (security fix,
        2026-11-27). The answer is the same whether or not
        the address has an account, so the endpoint cannot
        be used to enumerate accounts. The link verifies
        the account as it sets the new password: it is the
        recovery path for an unverified account and for an
        owner whose pre-registered password was cleared at
        a social merge."""
        ip = client_ip(request)
        if _rate_limited("pwreset", ip, 5):
            raise HTTPException(status_code=429,
                                detail="too many attempts, slow down")
        body = await request.json()
        email = (body.get("email") or "").strip().lower()
        user = users.get(f"email:{email}") if "@" in email else None
        if user:
            token = pysecrets.token_urlsafe(32)
            token_hash = hashlib.sha256(token.encode()).hexdigest()
            meta[f"pwreset:{token_hash}"] = {
                "user_id": user["id"], "expires": _now() + 3600}
            link = (f"{base_url(request)}/api/auth/password-reset"
                    f"?token={token}")
            _send_email(
                email,
                "Reset your Moonfactory password",
                "Open the link below to set a new password.\n"
                f"{link}\n\n"
                "The link works for one hour. If you did not ask "
                "for this, ignore this email and your password "
                "stays as it is.\n")
        return {"status": "ok"}

