    # -- start-image generation (Pass 3) --------------------------------
    # An image job is a normal platform job record (kind "image"):
    # same accounts, same holds, same Amendment 2 ceiling, same
    # Rule 8 failure restore as video jobs (mirror_image_status).
    # Gate decision: any account that could run the matching video
    # job may generate its start image. Free accounts generate for
    # their Draft clips, counted exactly like a Draft render
    # against the free ceilings, because the free tier is a capped
    # marketing budget and the first frame is part of that clip's
    # cost either way. The lane runs on Kaggle free compute at a
    # real cost of $0 (Jack, 2026-11-20), so the payment rails
    # below still resolve a method for the record but every
    # amount on them is 0: no included-budget debit, no balance
    # charge, no hold, for any account.

    def _image_params(body: dict):
        prompt = (body.get("prompt") or "").strip()
        if not prompt or len(prompt) > IMAGE_PROMPT_MAX_CHARS:
            raise HTTPException(
                status_code=422,
                detail=f"an image prompt of up to {IMAGE_PROMPT_MAX_CHARS} characters is required")
        aspect = body.get("aspect_ratio") or "9:16"
        if aspect not in HOUSE_ASPECTS:
            raise HTTPException(
                status_code=422,
                detail="aspect_ratio must be one of " + ", ".join(HOUSE_ASPECTS))
        return prompt, aspect

    def _image_payment(user: dict) -> dict:
        """Which rail an image job would pay from, before anything
        runs, mirroring the video lanes' order: free ceilings for
        accounts that have never paid, then a subscriber's included
        budget at raw cost, then balance at the floor price."""
        if user["plan"] == "free" and not is_paid(user):
            return {"method": "free"}
        if (user["plan"] == "creator"
                and included_budget_remaining(user) >= pricing.IMAGE_MEASURED_COST_CENTS):
            return {"method": "included",
                    "included_debit_cents": pricing.IMAGE_MEASURED_COST_CENTS}
        charge = pricing.image_price_cents(owner=is_owner(user))
        if int(user.get("balance_cents", 0)) >= charge or is_owner(user):
            # The owner pays from balance even when the balance
            # cannot cover it (Jack, 2026-11-17), so the quote
            # names the rail create will actually use for him.
            return {"method": "balance", "charge_cents": charge}
        return {"method": "insufficient", "charge_cents": charge,
                "balance_cents": int(user.get("balance_cents", 0))}

    @web.post("/api/images/quote")
    async def quote_image(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        body = await request.json()
        return quote_image_core(user, body)

    def quote_image_core(user: dict, body: dict) -> dict:
        """The one image quote behind both quote surfaces (the
        website's /api/images/quote and the customer API's
        /api/v1/images/quote): same account, same inputs, same
        price."""
        _image_params(body)
        if body.get("image_model"):
            lane = pricing.IMAGE_LANES.get(str(body["image_model"]))
            if not lane:
                raise HTTPException(status_code=400, detail="unknown image model")
            size = str(body.get("image_size") or "")
            if size not in lane["raw_cents"]:
                raise HTTPException(status_code=400, detail="pick a size this model makes")
            raw, debit = pricing.image_lane_price(
                str(body["image_model"]), size, owner=is_owner(user))
            # The quote names the exact integer cents creation
            # will charge, through the one shared rounding path
            # (Jack, 2026-11-23): the displayed price and the
            # charge cannot disagree, and a customer's fractional
            # 1.25x figure rounds up, never a cent short.
            charge = pricing.image_lane_charge_cents(
                str(body["image_model"]), size, owner=is_owner(user))
            return {
                "price_cents": charge,
                "raw_cost_cents": raw,
                "paid_only": not bool(lane.get("free")),
                "ceiling_ok": (
                    True if is_owner(user) else ceiling_allows(user, raw)),
                "balance_ok": int(user.get("balance_cents", 0)) >= charge,
            }
        return {
            **pricing.image_quote(owner=is_owner(user)),
            "payment": _image_payment(user),
            "ceiling_ok": (
                True if not is_paid(user) and user["plan"] == "free"
                else ceiling_allows(user, pricing.IMAGE_MEASURED_COST_CENTS)
            ),
        }

    @web.post("/api/images")
    async def create_image(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if _rate_limited("imagecreate", user["id"], 10):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        body = await request.json()
        if not bot_check_ok(body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        return create_image_core(user, body, client_ip(request))

    def create_image_core(user: dict, body: dict, ip: str):
        """The one image creation path behind both create
        surfaces (the website's /api/images and the customer
        API's /api/v1/images): the illegal content gate, the
        adult gate, the input classifier, the free tier rules,
        the hard cost ceiling, and the balance charge all run
        here, exactly as they do for a website image. The
        website wrapper above adds only its session auth, its
        pace limit, and the browser bot check."""
        prompt, aspect = _image_params(body)
        # The illegal-content gate (Jack, 2026-11-24), before
        # any lane pick, search, hold, or submit below.
        enforce_prompt_gate(
            user, str(body.get("image_model") or "image"),
            ip, prompt)
        if body.get("image_model"):
            # The curated image shelf: provider image models,
            # paid accounts only, charged per image at submit
            # and refunded in full if the image is not
            # delivered. The free lanes (2026-11-20) are the
            # exception: raw cost $0, open to every account,
            # and a free account spends them from its 5 free
            # generations like any free lane.
            lane_id = str(body["image_model"])
            lane = pricing.IMAGE_LANES.get(lane_id)
            if not lane:
                raise HTTPException(status_code=400, detail="unknown image model")
            free_lane = bool(lane.get("free"))
            served_free = False
            klein_on_kaggle = False
            if not free_lane and not is_paid(user):
                raise HTTPException(
                    status_code=402,
                    detail="image models are for paid accounts. The image maker built into Moonfactory stays free to try")
            size = str(body.get("image_size") or "")
            if size not in lane["raw_cents"]:
                raise HTTPException(
                    status_code=400,
                    detail=f"this image model makes {', '.join(lane['raw_cents'])} images")
            # The 18+ gate (Jack, 2026-11-24): an uncensored
            # image lane refuses an account without the one
            # time confirmation, here before the free count,
            # the stock search, the price, and the charge on
            # every shelf path below.
            adult_refusal = adult_gate_refusal(
                user, {"image_model": lane_id, "lane": "image",
                       "model": lane_id})
            if adult_refusal:
                raise HTTPException(status_code=403, detail=adult_refusal)
            if free_lane:
                free_reserved = False
                if user["plan"] == "free" and not is_paid(user):
                    # Atomic free-slot claim, as in create_job:
                    # the cap check and the count are one step.
                    slot_status, user = reserve_free_slot(user)
                    if slot_status == "cap":
                        raise HTTPException(
                            status_code=403,
                            detail=f"your free clips are used up. The free plan is {FREE_CLIPS_TOTAL} clips in total")
                    if slot_status == "ceiling":
                        raise HTTPException(
                            status_code=503,
                            detail="the free tier is paused")
                    served_free = True
                    free_reserved = True
                if lane["provider"] == "cloudflare" \
                        and not _cf_neuron_budget_allows(
                            _cf_neuron_estimate(lane_id, size)):
                    if lane_id == "flux2_klein4b":
                        # FLUX.2 Klein 4B carries a second
                        # free route (2026-11-20): the same
                        # model on the Kaggle house worker.
                        # With the day's neuron allowance
                        # spent, the job queues there instead
                        # of failing; both routes are $0 and
                        # the picker shows one entry either
                        # way. Schnell has no second route
                        # and still fails clean below.
                        klein_on_kaggle = True
                    else:
                        # Fail clean before anything is created:
                        # the shared daily free allowance is
                        # spent, and the route never spills to a
                        # paid one.
                        if free_reserved:
                            release_free_slot(user)
                        raise HTTPException(
                            status_code=503,
                            detail="the free image allowance is used up for today. It resets at midnight UTC")
                if lane["provider"] == "ovhcloud" \
                        and not _ovh_rate_allows():
                    # Fail clean before anything is created:
                    # the free SDXL lane is at its documented
                    # pace (2 images a minute without a
                    # project key, 400 with one), and the
                    # route never spills to a paid one.
                    if free_reserved:
                        release_free_slot(user)
                    raise HTTPException(
                        status_code=503,
                        detail="the free SDXL lane is busy right now. Wait a few seconds and try again")
            stock_pick = None
            if lane_id == "stock":
                # The stock lane searches before any job
                # exists: a description with no matching photo
                # fails clean right here, no job, no count, no
                # charge, and no fallback to a paid lane. The
                # winning photo's fields ride the job record
                # to the submit, which only downloads it.
                # Three stock sources stand behind the one
                # entry (2026-11-20), searched in order:
                # Pexels first (the key the shorts lane
                # already rides), then Unsplash, then
                # Pixabay. A source whose key is not stored
                # yet is skipped silently, and a source that
                # errors is skipped the same way; the first
                # source with a match wins.
                stock_sources = []
                pexels_key = shorts._env_value("PEXELS_API_KEY")
                if pexels_key:
                    stock_sources.append(
                        (shorts.pexels_search_photos, pexels_key))
                unsplash_key = shorts._env_value("UNSPLASH_ACCESS_KEY")
                if unsplash_key:
                    stock_sources.append(
                        (shorts.unsplash_search_photos,
                         unsplash_key))
                pixabay_key = shorts._env_value("PIXABAY_API_KEY")
                if pixabay_key:
                    stock_sources.append(
                        (shorts.pixabay_search_photos,
                         pixabay_key))
                if not stock_sources:
                    raise HTTPException(
                        status_code=503,
                        detail="the stock library is unavailable right now")
                stock_found = None
                stock_searched = False
                for search_photos, source_key in stock_sources:
                    try:
                        found_here = search_photos(
                            prompt, source_key)
                    except Exception:
                        continue
                    stock_searched = True
                    if found_here:
                        stock_found = found_here
                        break
                if stock_found is None and not stock_searched:
                    raise HTTPException(
                        status_code=503,
                        detail="the stock library is unavailable right now")
                if not stock_found:
                    # A 400, not a 404: the platform's 404
                    # handler rewrites every API 404 body to a
                    # bare Not Found, which would swallow this
                    # message, the one the user needs to act on.
                    raise HTTPException(
                        status_code=400,
                        detail="no stock photo matches that description. Try a few different words")
                stock_pick = stock_found[0]
            source_image = None
            input_verdict = None
            if lane.get("edit"):
                # Edit lanes take one source image alongside the
                # instruction: an https URL or an uploaded data
                # URL, the same forms the video lanes accept.
                # SpicyAPI caps the source image at 10 MB, which
                # is about 14M data-URL characters.
                source_image = str(body.get("source_image") or "")
                if (not source_image.startswith(("data:image/",
                                                  "https://"))
                        or len(source_image) > 14_000_000):
                    raise HTTPException(
                        status_code=400,
                        detail="this model edits one image. Add the image you want edited first")
            if source_image:
                # An edit never takes the Kaggle route: the
                # house image flow is text-to-image only, so an
                # edit job whose Cloudflare allowance is spent
                # fails clean at its submit instead of silently
                # dropping the source image.
                klein_on_kaggle = False
            reference_images = []
            reference_b64 = []
            extra_refs = []
            if body.get("character_id") or body.get("reference_images"):
                # Reference pictures (2026-11-27): a lane that
                # declares them (Nano Banana Pro) takes pictures
                # alongside the prompt: the picked character's
                # stored pictures, resolved here from the
                # character store, plus any pictures the user
                # adds as data URLs (an uploaded product photo,
                # or a library image the page sends the same
                # way). The guided movie flow's start frame
                # rides this path; every picture is judged
                # below with the edit source, by the same
                # classifier and the same gate, and the price
                # stays the lane's per image price.
                if not lane.get("references"):
                    raise HTTPException(
                        status_code=400,
                        detail="this image model does not take reference pictures")
                if body.get("character_id"):
                    character = _find_character(
                        user, str(body["character_id"]))
                    if not character:
                        raise HTTPException(
                            status_code=404, detail="unknown character")
                    for im in character.get("images") or []:
                        if im.get("b64"):
                            reference_b64.append(im["b64"])
                raw_refs = body.get("reference_images") or []
                if not isinstance(raw_refs, list):
                    raise HTTPException(
                        status_code=400,
                        detail="reference pictures must be a list")
                for ref in raw_refs:
                    ref = str(ref or "")
                    if not ref.startswith("data:image/") \
                            or len(ref) > 14_000_000:
                        raise HTTPException(
                            status_code=400,
                            detail="a reference picture must be an uploaded image")
                    extra_refs.append(ref)
                if len(reference_b64) + len(extra_refs) > 4:
                    raise HTTPException(
                        status_code=400,
                        detail="up to 4 reference pictures at a time")
                for raw in reference_b64:
                    data = base64.b64decode(raw)
                    mime = "image/png" if data.startswith(
                        b"\x89PNG") else "image/jpeg"
                    reference_images.append(
                        f"data:{mime};base64,{raw}")
                reference_images.extend(extra_refs)
            if lane.get("references_required") \
                    and not reference_images:
                # A reference-mode lane (Kling 2.1 Image,
                # 2026-11-27) has no text-to-image surface at
                # all: every documented mode is driven by a
                # reference picture, so a create without one
                # refuses here, before the price and the
                # charge, instead of failing at the provider.
                raise HTTPException(
                    status_code=400,
                    detail="this image model works from a reference picture. Add one first")
            # The input classifier (Jack, 2026-11-24): an edit
            # lane's source picture is judged at creation when
            # the platform holds its bytes (an uploaded data
            # URL). An https source is a remote URL the platform
            # never fetches at creation, so it stays unjudged
            # and stamps nothing. On a regular edit lane a
            # flagged or unjudged source refuses here, before
            # the price and the charge below; on an uncensored
            # edit lane the verdict only stamps.
            input_verdict = classify_input_images(
                b64_images=reference_b64,
                data_urls=tuple(
                    [source_image] if source_image else [])
                + tuple(extra_refs))
            refusal = input_gate_refusal(
                {"image_model": lane_id, "lane": "image",
                 "model": lane_id}, input_verdict)
            if refusal:
                raise HTTPException(status_code=400, detail=refusal)
            raw, debit = pricing.image_lane_price(
                lane_id, size, owner=is_owner(user))
            reload_state = {}
            if not is_owner(user) and not ceiling_allows(user, raw):
                attempt_auto_reload(user, reload_state)
            if not is_owner(user) and not ceiling_allows(user, raw):
                raise HTTPException(
                    status_code=402,
                    detail=reload_fail_detail(reload_state, "this image would pass what you have paid in. Top up first"))
            # The charge is the quote's figure, through the one
            # shared rounding path (Jack, 2026-11-23): a
            # customer's fractional 1.25x debit rounds UP to the
            # next whole cent, never a cent short; the owner
            # pays the provider's raw price untouched.
            charge = pricing.image_lane_charge_cents(
                lane_id, size, owner=is_owner(user))
            # The owner never balance blocks (Jack, 2026-11-17):
            # no reload attempt and no refusal; the charge below
            # is taken from his balance whatever it holds.
            if not is_owner(user):
                if int(user.get("balance_cents", 0)) < charge:
                    attempt_auto_reload(user, reload_state,
                                        needed_cents=charge)
                if int(user.get("balance_cents", 0)) < charge:
                    raise HTTPException(
                        status_code=402,
                        detail=reload_fail_detail(reload_state, "your balance is too low for this image. Top up first"))
            job_id = uuid.uuid4().hex[:16]
            job = {
                "id": job_id, "user_id": user["id"], "kind": "image",
                "lane": "image",
                "image_model": lane_id, "image_size": size,
                "provider": lane["provider"], "model": lane_id,
                "prompt": prompt, "status": "running",
                "created_at": _now(), "last_poll": 0,
                "created_ip": ip,
                "image_raw_cents": raw, "image_charge_cents": charge,
                "error": None,
                # Whether the user supplied the source image an
                # edit lane works from (the image itself is not
                # kept on the record): the gallery's image-input
                # bar reads this (job_has_image_input).
                "has_source_image": bool(
                    source_image or reference_images),
            }
            stamp_input_verdict(job, input_verdict)
            user["balance_cents"] = int(user.get("balance_cents", 0)) - charge
            save_user(user)
            jobs[job_id] = job
            _index_job(job)
            if stock_pick:
                job["stock_download_url"] = stock_pick["download_url"]
                job["stock_page_url"] = stock_pick["page_url"]
                job["stock_credit"] = stock_pick["credit"]
                # Which of the three sources won, and the
                # extra fields its terms ride on (2026-11-20):
                # an Unsplash win stores the photographer's
                # profile link beside their name, and the
                # download location the submit must call when
                # the photo is delivered.
                job["stock_source"] = stock_pick["provider"]
                if stock_pick.get("credit_url"):
                    job["stock_credit_url"] = \
                        stock_pick["credit_url"]
                if stock_pick.get("track_url"):
                    job["stock_track_url"] = \
                        stock_pick["track_url"]
                jobs[job_id] = job
            try:
                if klein_on_kaggle:
                    _queue_klein_on_kaggle(job, served_free)
                elif lane_id == "krea2_verite":
                    # Krea 2 Verite (2026-11-21): the lane's
                    # only route is the house Kaggle worker,
                    # so the job queues there at submit, the
                    # Klein conversion's shape with the paid
                    # charge kept on the record.
                    _queue_krea2_on_kaggle(job)
                elif lane_id == "longcat":
                    # LongCat-Image (2026-11-26): the lane's
                    # only route is the house Kaggle worker,
                    # so the job queues there at submit, the
                    # Krea conversion's shape on a clean lane.
                    _queue_longcat_on_kaggle(job)
                else:
                    _submit_provider_image(
                        job, prompt, source_image=source_image,
                        reference_images=reference_images or None)
            except Exception as exc:
                if lane_id == "flux2_klein4b" \
                        and not source_image \
                        and "free image allowance is used up" \
                        in str(exc):
                    # The budget check passed but the submit's
                    # own reservation found the allowance spent
                    # (a concurrent job took the last of it):
                    # the job takes the Kaggle route instead of
                    # failing, the same split as the check above.
                    klein_on_kaggle = True
                    _queue_klein_on_kaggle(job, served_free)
                else:
                    _fail_provider_image(
                        job, "the image model is unavailable right now, nothing was charged")
                    if free_reserved:
                        release_free_slot(user)
                    raise HTTPException(status_code=503, detail=MODEL_UNAVAILABLE)
            # Provider shelf photos count toward the 5 free
            # too (the free counter rule, 2026-11-20), once
            # the image is actually submitted. A free lane
            # serving a free account is a free tier job, so
            # it also moves the platform free ceiling. (A slot
            # reserved at the gate above is already counted.)
            if not free_reserved:
                count_generation(user, free_job=served_free)
            save_user(user)
            return {"job_id": job_id,
                    "status": "queued" if klein_on_kaggle
                    or lane_id == "krea2_verite"
                    or lane_id == "longcat"
                    else "running",
                    "charged_cents": charge}
        # Same in-flight limits as video jobs, counted together:
        # an image render is a render.
        limit = CONCURRENCY_PAID if is_paid(user) else CONCURRENCY_FREE
        in_flight = 0
        for other in _indexed_active_records(user["id"]):
            if (other.get("status") in ("queued", "running")
                    and other.get("provider") != "clip"
                    and not other.get("drama_parent")
                    and other.get("kind") not in (
                        "clip_job", "clip_output", "voice_clone")):
                in_flight += 1
        if in_flight >= limit:
            raise HTTPException(
                status_code=429,
                detail=f"you already have {in_flight} jobs in flight. Your plan allows {limit} at a time, and one needs to finish before the next starts")
        u = usage(user)
        charged = 0
        used_budget = 0.0
        job_cost_cents = 0.0
        is_free_job = False
        free_reserved = False
        if user["plan"] == "free" and not is_paid(user):
            # Atomic free-slot claim (check and count in one
            # step), as in create_job.
            slot_status, user = reserve_free_slot(user)
            if slot_status == "cap":
                raise HTTPException(
                    status_code=403,
                    detail=f"your free clips are used up. The free plan is {FREE_CLIPS_TOTAL} clips in total",
                )
            if slot_status == "ceiling":
                raise HTTPException(status_code=503, detail="the free tier is paused")
            is_free_job = True
            free_reserved = True
            u = usage(user)
        else:
            # Amendment 2 ceiling, before dispatch, as on every
            # paid path.
            reload_state = {}
            if not ceiling_allows(user, pricing.IMAGE_MEASURED_COST_CENTS):
                attempt_auto_reload(user, reload_state)
            if not ceiling_allows(user, pricing.IMAGE_MEASURED_COST_CENTS):
                raise HTTPException(
                    status_code=402,
                    detail=reload_fail_detail(reload_state, "this job would exceed the total generation your payments cover"),
                )
            payment = _image_payment(user)
            if payment["method"] == "included":
                used_budget = float(pricing.IMAGE_MEASURED_COST_CENTS)
            elif payment["method"] == "balance":
                charged = payment["charge_cents"]
            elif attempt_auto_reload(
                    user, reload_state,
                    needed_cents=int(payment["charge_cents"])) \
                    and _image_payment(user)["method"] == "balance":
                # Autopay (Jack, 2026-11-27): the one automatic
                # top up landed, so the balance rail now covers
                # the frame.
                charged = payment["charge_cents"]
            else:
                raise HTTPException(
                    status_code=402,
                    detail=reload_fail_detail(reload_state, f"included budget used up. A first frame costs {payment['charge_cents']} cents of prepaid balance"))
            job_cost_cents = float(pricing.IMAGE_MEASURED_COST_CENTS)
        # The house image lane runs on the Kaggle ComfyUI
        # worker (2026-11-19), like the house video lanes: no
        # synchronous dispatch, the record below queues the
        # job and the commit is its acceptance.
        worker_job_id = None
        # Commit the quota/balance only after the worker accepted
        # the job, exactly like the video lanes.
        if is_free_job and not free_reserved:
            u["free_jobs"] += 1
            user["free_jobs_total"] = free_jobs_total(user) + 1
            meta["freecount:total"] = int(meta.get("freecount:total") or 0) + 1
        if not is_free_job:
            # Paid house photos count toward the 5 free too
            # (the free counter rule, 2026-11-20).
            count_generation(user)
        if used_budget:
            u["included_cost_cents"] = included_cost_used(user) + used_budget
        if charged:
            user["balance_cents"] = user.get("balance_cents", 0) - charged
        if job_cost_cents:
            user["cost_settled_cents"] = (
                float(user.get("cost_settled_cents") or 0.0) + job_cost_cents
            )
        user["usage"] = u
        save_user(user)
        job = {
            "id": pysecrets.token_hex(8),
            "user_id": user["id"],
            "worker_job_id": worker_job_id,
            "provider": "kaggle-comfy",
            "route": "kaggle",
            "kind": "image",
            "lane": "image",
            "model": None,
            "prompt": prompt,
            "seed": body.get("seed"),
            "user_prompt": prompt,
            "camera_presets": [],
            "camera_preset_names": [],
            "camera_look": {},
            "status": "queued",
            "error": None,
            "bytes": None,
            "created_at": _now(),
            "charged_cents": charged,
            "free_tier": is_free_job,
            "included_cost_cents": used_budget,
            "cost_cents": job_cost_cents,
            "music_prompt": None,
            "plan_at_job": user["plan"],
            "retry_of": body.get("retry_of"),
            "last_poll": 0,
            "aspect_ratio": aspect,
        }
        jobs[job["id"]] = job
        _index_job(job)
        _comfy_maybe_trigger()
        return JSONResponse(
            {**public_job(job), "quote": pricing.image_quote(owner=is_owner(user))},
            status_code=202)

    @web.post("/api/jobs/{job_id}/regenerate")
    async def regenerate(job_id: str, request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        parent = jobs.get(job_id)
        if not parent or parent.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        if parent["status"] not in ("done", "error"):
            raise HTTPException(status_code=409, detail="job is still running")
        root_id = parent.get("retry_of") or parent["id"]
        children = 0
        free_retries = 0
        # The retry chain belongs to the parent's owner, so
        # the count reads the owner's indexed records instead
        # of walking the whole store (perf pass 3).
        for other in _indexed_records(
                user["id"],
                [e[0] for e in
                 (_user_job_index(user["id"]).get("ids") or [])]):
            if other.get("retry_of") == root_id:
                children += 1
                if other.get("free_retry"):
                    free_retries += 1
        body = await request.json()
        new_body = {
            "lane": parent["lane"],
            # Recompose from the original prompt and the stored
            # camera selection, so a regenerate runs the identical
            # final prompt instead of composing a second time on top
            # of the already-composed one.
            "prompt": parent.get("user_prompt") or parent["prompt"],
            "camera_presets": parent.get("camera_presets") or [],
            "camera_look": parent.get("camera_look") or {},
            "camera_speed": parent.get("camera_speed"),
            "music_prompt": parent.get("music_prompt"),
            "speech_script": parent.get("speech_script"),
            "speech_voice": parent.get("speech_voice"),
            "captions": parent.get("captions"),
            "model": parent.get("model") or DEFAULT_MODEL,
            "duration_seconds": parent.get("duration_seconds"),
            "resolution": parent.get("resolution"),
            "reference_video_seconds": parent.get("reference_video_seconds"),
            "reference_image_urls": parent.get("reference_image_urls"),
            "reference_video_urls": parent.get("reference_video_urls"),
            "reference_audio_urls": parent.get("reference_audio_urls"),
            "segments": parent.get("segments_total") or 1,
            "effect": parent.get("effect"),
            "aspect_ratio": parent.get("aspect_ratio") or "9:16",
            "start_image_png_b64": parent.get("start_image_png_b64"),
            "end_image_png_b64": parent.get("end_image_png_b64"),
            "retry_of": root_id,
            "challenge_id": body.get("challenge_id"),
            "challenge_nonce": body.get("challenge_nonce"),
            "turnstile_token": body.get("turnstile_token"),
        }
        # A worker-side error earns free retries (Rule 8), capped.
        # The composed body goes to create_job_core directly
        # (2026-11-27 fix): a request._body substitution never
        # reaches the core, because the parse above already
        # cached this request's json and create_job's own
        # request.json() answers from that cache. create_job's
        # wrapper checks run here against the composed body
        # instead, the same checks in the same order.
        if _rate_limited("jobcreate", user["id"], 10):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        if not bot_check_ok(new_body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        result = create_job_core(
            user, new_body, base_url(request), client_ip(request))
        created = json.loads(result.body)
        if parent["status"] == "error" and free_retries < MAX_FREE_RETRIES:
            child = jobs.get(created["id"])
            if child and child.get("charged_cents"):
                user = users.get(f"id:{user['id']}")
                user["balance_cents"] = user.get("balance_cents", 0) + child["charged_cents"]
                child["charged_cents"] = 0
                child["free_retry"] = True
                save_user(user)
                jobs[child["id"]] = child
                created["charged_cents"] = 0
        return created

    @web.post("/api/jobs/{job_id}/retry")
    async def retry_job(job_id: str, request: Request, mf_session: str = Cookie(default="")):
        """Retry an errored generation from its stored record
        (Jack, 2026-11-24): every error card in the studio and
        the library carries a Retry button beside Delete, and
        this is the one door behind it. The retry is a fresh
        creation rebuilt from the original inputs, so every
        creation gate applies again (illegal content, upload
        scan, ceilings, bot check) and the normal price is
        charged at retry time — the failed attempt charged
        nothing (its holds were restored), so there is no
        double charge. Video generations ride the existing
        regenerate path above, free retries for worker-side
        errors included; the other kinds rebuild the body
        their own create route takes and call it the same
        way. Kinds whose inputs are not kept on the record
        refuse plainly instead of guessing."""
        user = require_user(request, mf_session)
        parent = jobs.get(job_id)
        if not parent or parent.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        if parent.get("status") != "error":
            raise HTTPException(
                status_code=409,
                detail="only a failed generation can be retried")
        try:
            body = await request.json()
        except Exception:
            body = {}
        if not isinstance(body, dict):
            body = {}
        bot = {k: body.get(k) for k in (
            "challenge_id", "challenge_nonce", "turnstile_token")}
        kind = parent.get("kind")
        root_id = parent.get("retry_of") or parent["id"]

        def link_retry(created_id):
            child = jobs.get(created_id) if created_id else None
            if child and not child.get("retry_of"):
                child["retry_of"] = root_id
                jobs[child["id"]] = child

        if kind == "drama":
            # An errored episode retries the way a paused one
            # resumes: the failed shots go back to ready and
            # the episode makes them again. The episode was
            # already counted and held at creation; a resume
            # never counts or charges again. The account-state
            # checks and the lifetime attempt cap are shared
            # with resume (security fix, 2026-11-27,
            # drama-resume-resets-attempts and the suspension
            # record's retry branch).
            _drama_resume_checks(user, request)
            if not bot_check_ok(bot, client_ip(request), user):
                raise HTTPException(
                    status_code=403, detail="bot check failed")
            rec = dramas.get(parent.get("drama_id") or "")
            if not rec:
                raise HTTPException(status_code=404,
                                    detail="episode not found")
            if not _drama_requeue_failed_shots(rec):
                raise HTTPException(
                    status_code=409,
                    detail="That shot has been tried too many times to make again.")
            rec["status"] = "making"
            dramas[rec["id"]] = rec
            parent["status"] = "running"
            parent["error"] = None
            parent["drama_state"] = "making"
            parent["stage"] = "Starting again"
            jobs[parent["id"]] = parent
            return public_job(parent)

        if kind == "short":
            lines = parent.get("short_lines") or []
            if not lines:
                raise HTTPException(
                    status_code=422,
                    detail="the words of this short were not kept, so it cannot be retried")
            new_body = {
                "script": "\n".join(lines),
                "split": parent.get("short_split") or "auto",
                "voice": parent.get("speech_voice")
                or DEFAULT_SPEECH_VOICE,
                "visuals": parent.get("short_visuals") or "stock",
                "style": parent.get("short_style") or "",
                "music": parent.get("short_music") or "none",
                "music_prompt": parent.get("music_prompt") or "",
                "caption_style":
                    parent.get("short_caption_style") or "",
                "beat_sync": bool(parent.get("short_beat_sync")),
                "draft_model": parent.get("short_draft_model") or "",
                **bot,
            }
            if new_body["voice"] == CLONE_VOICE_ID:
                # The clone reference clip is kept on the
                # volume under the original job's id, so a
                # cloned-voice short retries with the same
                # voice. Without the file there is nothing to
                # clone from, and the retry refuses plainly.
                ext = parent.get("clone_reference_ext")
                ref = (FILES_DIR / "voice_refs"
                       / f"{parent['id']}.{ext}") if ext else None
                if ref is None or not ref.exists():
                    raise HTTPException(
                        status_code=422,
                        detail="the voice recording this short used was not kept, so it cannot be retried")
                new_body["clone_reference_audio_b64"] = \
                    base64.b64encode(ref.read_bytes()).decode()
                new_body["clone_reference_text"] = \
                    parent.get("clone_reference_text") or ""
            # The composed body goes to the creation core
            # directly (2026-11-27 fix): a request._body
            # substitution never reaches a wrapper's cached
            # request.json(). The wrapper's checks run here
            # against the composed body instead, so every
            # creation gate applies again, as this endpoint's
            # own docstring promises.
            if _rate_limited("shortcreate", user["id"], 10):
                raise HTTPException(status_code=429, detail="too many jobs, slow down")
            if not user["verified"]:
                raise HTTPException(status_code=403, detail="verify your email before creating")
            if user.get("past_due"):
                raise HTTPException(status_code=403, detail="your subscription payment is past due")
            if not bot_check_ok(new_body, client_ip(request), user):
                raise HTTPException(status_code=403, detail="bot check failed")
            result = create_short_core(
                user, new_body, client_ip(request))
            created = json.loads(result.body)
            link_retry(created.get("id"))
            return created

        if kind == "image":
            if parent.get("image_model"):
                lane = pricing.IMAGE_LANES.get(
                    parent["image_model"]) or {}
                if lane.get("edit") \
                        and parent.get("has_source_image"):
                    # Edit lanes never kept the source picture
                    # on the record (see create_image), so
                    # there is nothing to rebuild the edit
                    # from.
                    raise HTTPException(
                        status_code=422,
                        detail="the picture this edit started from was not kept, so it cannot be retried. Make it again with the picture")
                if lane.get("references") \
                        and parent.get("has_source_image"):
                    # Reference pictures are not kept on the
                    # record either (see create_image_core), so
                    # a frame made from a character and a
                    # product photo cannot be rebuilt without
                    # them; it refuses plainly like an edit.
                    raise HTTPException(
                        status_code=422,
                        detail="the pictures this one was made from were not kept, so it cannot be retried. Make it again with the pictures")
                new_body = {
                    "prompt": parent.get("prompt"),
                    "image_model": parent["image_model"],
                    "image_size": parent.get("image_size"),
                    "aspect_ratio": parent.get("aspect_ratio")
                    or "9:16",
                    **bot,
                }
                # The composed body goes to the creation core
                # directly, with the wrapper's checks run here
                # against it (2026-11-27 fix; see the short
                # branch above for why).
                if _rate_limited("imagecreate", user["id"], 10):
                    raise HTTPException(status_code=429, detail="too many jobs, slow down")
                if not user["verified"]:
                    raise HTTPException(status_code=403, detail="verify your email before creating")
                if user.get("past_due"):
                    raise HTTPException(status_code=403, detail="your subscription payment is past due")
                if not bot_check_ok(new_body, client_ip(request), user):
                    raise HTTPException(status_code=403, detail="bot check failed")
                result = create_image_core(
                    user, new_body, client_ip(request))
                if isinstance(result, JSONResponse):
                    created = json.loads(result.body)
                else:
                    created = result
                link_retry(created.get("id")
                           or created.get("job_id"))
                return created
            new_body = {
                "prompt": parent.get("prompt"),
                "aspect_ratio": parent.get("aspect_ratio") or "9:16",
                "seed": parent.get("seed"),
                "retry_of": root_id,
                **bot,
            }
            # The composed body goes to the creation core
            # directly, with the wrapper's checks run here
            # against it (2026-11-27 fix; see the short branch
            # above for why).
            if _rate_limited("imagecreate", user["id"], 10):
                raise HTTPException(status_code=429, detail="too many jobs, slow down")
            if not user["verified"]:
                raise HTTPException(status_code=403, detail="verify your email before creating")
            if user.get("past_due"):
                raise HTTPException(status_code=403, detail="your subscription payment is past due")
            if not bot_check_ok(new_body, client_ip(request), user):
                raise HTTPException(status_code=403, detail="bot check failed")
            result = create_image_core(
                user, new_body, client_ip(request))
            return json.loads(result.body)

        if kind == "clip_output":
            # A clip is one cut of its parent clipping job:
            # retrying it means running that job again.
            clip_parent = jobs.get(parent.get("clip_parent") or "")
            if not clip_parent \
                    or clip_parent.get("user_id") != user["id"]:
                raise HTTPException(
                    status_code=422,
                    detail="the clipping job this clip came from is gone, so it cannot be retried")
            parent = clip_parent
            kind = "clip_job"

        if kind == "clip_job":
            new_body = {
                "clip_count": parent.get("clip_count") or 3,
                "length": parent.get("length") or "medium",
                "caption_style": parent.get("caption_style")
                or clipping.NO_CAPTION_STYLE,
                "layout": parent.get("layout") or "blur",
                **bot,
            }
            if parent.get("source_url"):
                new_body["url"] = parent["source_url"]
            elif parent.get("upload_path"):
                # The create route reads uploads through their
                # upload record, so the retry registers the
                # stored file under a fresh upload id and rides
                # the same path (and the same hold) as a new
                # clipping.
                uid = pysecrets.token_hex(8)
                meta[f"clipupload:{uid}"] = {
                    "user_id": user["id"],
                    "path": parent["upload_path"],
                    "duration": float(
                        parent.get("duration_seconds") or 0),
                    "filename": parent.get("source_title") or "",
                }
                new_body["upload_id"] = uid
            else:
                raise HTTPException(
                    status_code=422,
                    detail="the video this clipping came from was not kept, so it cannot be retried")
            # The composed body goes to the creation core
            # directly, with the wrapper's checks run here
            # against it (2026-11-27 fix; see the short branch
            # above for why).
            if _rate_limited("clipcreate", user["id"], 6):
                raise HTTPException(status_code=429, detail="too many jobs, slow down")
            if not user["verified"]:
                raise HTTPException(status_code=403, detail="verify your email before creating")
            if user.get("past_due"):
                raise HTTPException(status_code=403, detail="your subscription payment is past due")
            if not bot_check_ok(new_body, client_ip(request), user):
                raise HTTPException(status_code=403, detail="bot check failed")
            result = create_clip_core(
                user, new_body, client_ip(request))
            created = json.loads(result.body)
            link_retry(created.get("id"))
            return created

        if kind == "template":
            new_body = {
                "template": parent.get("template"),
                **(parent.get("hf_fields") or {}),
                **bot,
            }
            if parent.get("template") == "captions":
                if not parent.get("upload_path"):
                    raise HTTPException(
                        status_code=422,
                        detail="the clip this title card was made from was not kept, so it cannot be retried")
                uid = pysecrets.token_hex(8)
                meta[f"templateupload:{uid}"] = {
                    "user_id": user["id"],
                    "path": parent["upload_path"],
                    "duration": float(
                        parent.get("source_duration") or 0),
                }
                new_body["upload_id"] = uid
            # The composed body goes to the creation core
            # directly, with the wrapper's checks run here
            # against it (2026-11-27 fix; see the short branch
            # above for why).
            if _rate_limited("templatecreate", user["id"], 10):
                raise HTTPException(status_code=429, detail="too many jobs, slow down")
            if not user["verified"]:
                raise HTTPException(status_code=403, detail="verify your email before creating")
            if user.get("past_due"):
                raise HTTPException(status_code=403, detail="your subscription payment is past due")
            if not bot_check_ok(new_body, client_ip(request), user):
                raise HTTPException(status_code=403, detail="bot check failed")
            result = create_template_core(
                user, new_body, client_ip(request))
            created = json.loads(result.body)
            link_retry(created.get("id"))
            return created

        if kind == "assembly":
            # A failed movie rebuilds from the picks kept on
            # its record, through the same creation core, so
            # every assembly rule applies again (the picks are
            # revalidated against the live records) and the
            # retry still carries no charge.
            if not bot_check_ok(bot, client_ip(request), user):
                raise HTTPException(
                    status_code=403, detail="bot check failed")
            created = create_assembly_core(
                user,
                {"job_ids": parent.get("assembly_sources") or []},
                client_ip(request))
            link_retry(created["id"])
            return public_job(created)

        if kind in ("edit_source", "hook_clip", "ec_character"):
            # Edit/Clone steps are not generations: there is no
            # creation body to rebuild. The step is simply run
            # again from the Clone section.
            raise HTTPException(
                status_code=422,
                detail="this cannot be retried from here, run it again from the Clone section")

        # Every other error card is a video generation: the
        # existing regenerate path rebuilds it from the same
        # stored inputs. regenerate re-reads this request's
        # body itself, and the parse above already cached that
        # body on the request, so it sees the same dict; the
        # old request._body re-encode of the same body changed
        # nothing and is gone (2026-11-27).
        return await regenerate(job_id, request, mf_session)

    def _fal_upload_bytes(data: bytes, content_type: str, file_name: str):
        """Upload bytes to fal storage and return the hosted file
        URL. The lip sync endpoint and the character trainer take
        URLs, not bytes. Returns None on any failure."""
        try:
            resp = requests.post(
                "https://rest.alpha.fal.ai/storage/upload/initiate",
                headers=_fal_headers(),
                json={"content_type": content_type, "file_name": file_name},
                timeout=30,
            )
            if resp.status_code != 200:
                return None
            info = resp.json() or {}
            put = requests.put(
                info["upload_url"], data=data,
                headers={"Content-Type": content_type}, timeout=300)
            if put.status_code not in (200, 201, 204):
                return None
            return info.get("file_url")
        except Exception:
            return None

    def _lip_sync_for_job(job: dict, video_path: Path, voice_path: Path):
        """The built-in lip sync stage (Jack's rule, 2026-11-17):
        re-render the finished picture so the mouth matches the
        spoken line, via fal's Sync Lipsync v2 (the cheapest
        reliable hosted route with a published per-second price).
        Runs only for jobs flagged at creation: a spoken line the
        platform voices in post, on a lane that does not speak
        natively. The same rule covers dubbing: the voice track is
        the job's own spoken line, and the mouth is matched to it.
        Any failure flags the job and returns None: the un-synced
        video still delivers, the same way a failed voiceover
        never blocks delivery."""
        out_path = FILES_DIR / f"{job['id']}.lipsync.mp4"
        if out_path.exists():
            job["lipsync_status"] = "applied"
            jobs[job["id"]] = job
            return out_path
        try:
            video_url = _fal_upload_bytes(
                video_path.read_bytes(), "video/mp4", f"{job['id']}.mp4")
            audio_url = _fal_upload_bytes(
                voice_path.read_bytes(), "audio/wav", f"{job['id']}.wav")
            if not video_url or not audio_url:
                raise RuntimeError("fal storage upload failed")
            resp = requests.post(
                f"https://queue.fal.run/{pricing.LIPSYNC_MODEL}",
                headers=_fal_headers(),
                json={"video_url": video_url, "audio_url": audio_url},
                timeout=30,
            )
            if resp.status_code != 200:
                raise RuntimeError(f"lip sync submit {resp.status_code}")
            sub = resp.json() or {}
            status_url = sub.get("status_url")
            response_url = sub.get("response_url")
            if not status_url or not response_url:
                raise RuntimeError("lip sync submit returned no queue urls")
            result_url = None
            deadline = _now() + 900
            while _now() < deadline:
                time.sleep(10)
                st = requests.get(
                    status_url, headers=_fal_headers(), timeout=15)
                if st.status_code != 200:
                    continue
                status = (st.json() or {}).get("status")
                if status == "COMPLETED":
                    got = requests.get(
                        response_url, headers=_fal_headers(), timeout=30)
                    body = got.json() or {}
                    payload = body.get("data") or body
                    result_url = ((payload.get("video") or {}).get("url"))
                    break
                if status in ("FAILED", "ERROR"):
                    break
            if not result_url:
                raise RuntimeError("lip sync produced no result")
            got = requests.get(result_url, timeout=300)
            if got.status_code != 200:
                raise RuntimeError("lip sync download failed")
            out_path.write_bytes(got.content)
            job["lipsync_status"] = "applied"
            jobs[job["id"]] = job
            return out_path
        except Exception:
            job["lipsync_status"] = "unavailable"
            jobs[job["id"]] = job
            return None

    def _store_clone_reference(job: dict, clone_reference,
                               clone_reference_text: str):
        """Store a job's voice cloning reference clip on the
        data Volume and stamp the job record with where it
        lives. The voice worker downloads the clip through the
        worker endpoints when it claims a clone child of this
        job. Runs at creation on both video create paths and
        on shorts create."""
        if clone_reference is None:
            return
        raw, ext = clone_reference
        ref_dir = FILES_DIR / "voice_refs"
        ref_dir.mkdir(parents=True, exist_ok=True)
        (ref_dir / f"{job['id']}.{ext}").write_bytes(raw)
        job["clone_reference_ext"] = ext
        job["clone_reference_text"] = clone_reference_text or ""
        jobs[job["id"]] = job
        try:
            data_volume.commit()
        except Exception:
            pass

    def _voiceover_for_job(job: dict):
        """The Kokoro voiceover stage (Jack's correction,
        2026-11-16): speak the job's speech_script with Kokoro
        (Apache-2.0, the shippable TTS) and cache the wav per job
        on the data Volume. The synthesis runs on the Kaggle
        audio worker (the _audio_bytes seam), as of the
        2026-11-24 audio move. Since the parallel-audio change
        (2026-11-16) the synthesis is normally spawned at dispatch
        and only collected here; the synchronous call below remains
        as the fallback for jobs with no spawned call. If the stage
        cannot produce the wav either way, the lookup fails cleanly
        here: the job is flagged voiceover_status "unavailable",
        delivery proceeds with the lane's own audio and any music
        bed, and nothing is charged or blocked. A music bed is never
        silently passed off as speech: the flag on the job record
        says exactly what happened."""
        script = (job.get("speech_script") or "").strip()
        if not script:
            return None
        voice_file = FILES_DIR / "voice" / f"{job['id']}.wav"
        if voice_file.exists():
            if job.get("voiceover_status") != "ready":
                job["voiceover_status"] = "ready"
                jobs[job["id"]] = job
            return voice_file
        if job.get("speech_voice") == CLONE_VOICE_ID:
            # Voice cloning (2026-11-21): the cloned voice comes
            # from the Kaggle voice worker through the clone
            # child machinery, never from Kokoro: a requested
            # clone is never silently replaced by a stock voice.
            # Failure lands exactly where a Kokoro failure
            # lands: the job is flagged unavailable, delivery
            # proceeds with the lane's own audio, and the clone
            # charge has already gone back inside the wait
            # helper whenever no clone was delivered.
            cloned = _wait_clone_child(job, script)
            if cloned is not None:
                voice_file.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(cloned, voice_file)
                try:
                    data_volume.commit()
                except Exception:
                    pass
                job["voiceover_status"] = "ready"
                jobs[job["id"]] = job
                return voice_file
            job["voiceover_status"] = "unavailable"
            job["audio_fallback"] = True
            jobs[job["id"]] = job
            return None
        try:
            data = _audio_bytes(
                "voiceover",
                {"text": script,
                 "voice": job.get("speech_voice")
                 or DEFAULT_SPEECH_VOICE},
                job, AUDIO_WEB_WAIT_SECONDS)
            voice_file.parent.mkdir(parents=True, exist_ok=True)
            voice_file.write_bytes(data)
            job["voiceover_status"] = "ready"
            jobs[job["id"]] = job
            return voice_file
        except Exception:
            job["voiceover_status"] = "unavailable"
            job["audio_fallback"] = True
            jobs[job["id"]] = job
            return None

    def _word_check_for_job(job: dict, out_path: Path):
        """The word check stage (Jack's call, 2026-11-18, the UGC
        Studio word fix idea rebuilt for Moonfactory): once the
        delivered file exists, its final audio is transcribed word
        by word and aligned against the job's speech_script by the
        word check stage on the Kaggle audio worker (the
        sinclip-audio app's word_check callable until the
        2026-11-26 move). Running
        against the final audio means the check sees what the
        customer hears, after lip sync, native generation and the
        voiceover mix alike. Jobs the platform voiced itself carry
        a same-voice clean track, so the stage may also splice a
        corrected word back in; when it returns repaired audio, the
        delivered file's audio track is swapped for it here.
        Outcomes land on the job record: passed, fixed, flagged
        (with word_check_listen_at naming the seconds to listen
        to), take_failed (more than a fifth of the script still
        wrong; the video still delivers), or unavailable (the stage
        itself failed). Like every audio stage here, a failure
        never blocks delivery and never changes the price: the
        check is a finishing stage, not a charge."""
        script = (job.get("speech_script") or "").strip()
        if not script or job.get("word_check_status"):
            return
        audio_path = FILES_DIR / f"{job['id']}.wordcheck.wav"
        fixed_path = FILES_DIR / f"{job['id']}.wordfix.wav"
        swapped_path = FILES_DIR / f"{job['id']}.wordfix.mp4"
        try:
            proc = subprocess.run(
                ["ffmpeg", "-y", "-i", str(out_path), "-vn",
                 "-acodec", "pcm_s16le", str(audio_path)],
                capture_output=True, text=True, timeout=600)
            if proc.returncode != 0 or not audio_path.exists():
                raise RuntimeError("final audio extraction failed")
            # The fix pass is only possible where the platform's
            # Kokoro stage voiced the job: that clean track is the
            # same voice. Native lanes get the check and the flag.
            # A cloned voice gets the check and the flag too: no
            # Kokoro voice can repair a clone's words, so the fix
            # pass stays off for the clone pick.
            voice = ""
            if job.get("voiceover_status") == "ready" \
                    and job.get("speech_voice") != CLONE_VOICE_ID:
                voice = job.get("speech_voice") or "af_heart"
            result = _word_check_via_kaggle(
                audio_path.read_bytes(), script, voice, job)
            fixed = result.pop("audio", None)
            heard_words = result.pop("words", None)
            if heard_words:
                # One transcription of the final audio serves
                # both finishing stages: the captions stage burns
                # these same words in when the job asked for it.
                _CAPTION_TRANSCRIPTS[job["id"]] = heard_words
            if fixed:
                fixed_path.write_bytes(fixed)
                proc = subprocess.run(
                    ["ffmpeg", "-y", "-i", str(out_path),
                     "-i", str(fixed_path),
                     "-map", "0:v:0", "-map", "1:a:0",
                     "-c:v", "copy", "-c:a", "aac", "-b:a", "160k",
                     "-shortest", "-movflags", "+faststart", str(swapped_path)],
                    capture_output=True, text=True, timeout=1800)
                if proc.returncode != 0 or not swapped_path.exists():
                    raise RuntimeError("fixed audio swap failed")
                swapped_path.replace(out_path)
            job["word_check_status"] = result.get("status") \
                or "unavailable"
            job["word_check_listen_at"] = \
                result.get("listen_at") or []
            job["word_check_wrong"] = result.get("wrong") or []
            jobs[job["id"]] = job
        except Exception:
            job["word_check_status"] = "unavailable"
            jobs[job["id"]] = job
        finally:
            for path in (audio_path, fixed_path, swapped_path):
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass

    def _captions_for_job(job: dict, out_path: Path):
        """The captions stage (Jack's call, 2026-11-18): a job
        created with the captions box checked gets word timed
        captions burned into its delivered file here, in the
        Shorts lane's house style. The words and their timings
        are the faster-whisper transcription of the final audio:
        the one the word check stage just produced when it ran
        (it waits in _CAPTION_TRANSCRIPTS), or a fresh run of the
        same transcription through the audio worker's transcribe
        stage when the job has none. The choice exists only
        at generation time; existing gallery videos are never
        captioned after the fact, and an unchecked job takes
        exactly the path it always took. Outcomes land on the
        job record: applied, no_speech (the job carries no
        spoken line, or its final audio has no words to caption),
        or unavailable (the transcription or the burn in itself
        failed). Like every finishing stage here, a failure never
        blocks delivery and never changes the price.

        The lower third (2026-11-23) rides this same stage: a
        job that carries one gets it burned into the same pass,
        with or without captions, and it needs no speech at
        all, so a silent video can still wear its name. Its
        outcome lands on lower_third_status the same way."""
        want_captions = bool(job.get("captions"))
        lower_third = job.get("lower_third") or None
        if not want_captions and not lower_third:
            return
        if want_captions and job.get("captions_status"):
            return
        if lower_third and job.get("lower_third_status"):
            lower_third = None
            if not want_captions:
                return
        has_speech = bool((job.get("speech_script") or "").strip()) \
            or job.get("voiceover_status") in ("ready", "native")
        if want_captions and not has_speech:
            job["captions_status"] = "no_speech"
            jobs[job["id"]] = job
            if not lower_third:
                return
        audio_path = FILES_DIR / f"{job['id']}.captions.wav"
        ass_path = FILES_DIR / f"{job['id']}.captions.ass"
        burned_path = FILES_DIR / f"{job['id']}.captioned.mp4"
        try:
            words = []
            if want_captions and has_speech:
                words = _CAPTION_TRANSCRIPTS.pop(job["id"], None)
                if not words:
                    proc = subprocess.run(
                        ["ffmpeg", "-y", "-i", str(out_path), "-vn",
                         "-acodec", "pcm_s16le", str(audio_path)],
                        capture_output=True, text=True, timeout=600)
                    if proc.returncode != 0 or not audio_path.exists():
                        raise RuntimeError("final audio extraction failed")
                    result = _transcribe_via_kaggle(
                        audio_path.read_bytes(), job)
                    words = result.get("words") or []
                words = [w for w in words
                         if str(w.get("word", "")).strip()]
                if not words:
                    job["captions_status"] = "no_speech"
                    jobs[job["id"]] = job
                    if not lower_third:
                        return
            proc = subprocess.run(
                ["ffprobe", "-v", "error", "-select_streams", "v:0",
                 "-show_entries", "stream=width,height",
                 "-of", "csv=p=0", str(out_path)],
                capture_output=True, text=True, timeout=60)
            parts = (proc.stdout or "").strip().split(",")
            if len(parts) != 2:
                raise RuntimeError("finished file has no readable size")
            width, height = int(parts[0]), int(parts[1])
            if width <= 0 or height <= 0:
                raise RuntimeError("finished file has no readable size")
            ass_path.write_text(
                build_captions_ass(
                    words, width, height,
                    style=job.get("caption_style")
                    or VIDEO_CAPTION_STYLE_DEFAULT,
                    lower_third=lower_third),
                encoding="utf-8")
            proc = subprocess.run(
                ["ffmpeg", "-y", "-i", str(out_path),
                 "-vf", f"subtitles={ass_path.name}",
                 "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
                 "-c:a", "copy", "-movflags", "+faststart", str(burned_path)],
                capture_output=True, text=True, timeout=1800,
                cwd=FILES_DIR)
            if proc.returncode != 0 or not burned_path.exists():
                raise RuntimeError("caption burn in failed")
            burned_path.replace(out_path)
            if words:
                job["captions_status"] = "applied"
            if lower_third:
                job["lower_third_status"] = "applied"
            jobs[job["id"]] = job
        except Exception:
            if want_captions and not job.get("captions_status"):
                job["captions_status"] = "unavailable"
            if lower_third:
                job["lower_third_status"] = "unavailable"
            jobs[job["id"]] = job
        finally:
            for path in (audio_path, ass_path, burned_path):
                try:
                    path.unlink(missing_ok=True)
                except Exception:
                    pass

    def _bed_for_job(job: dict):
        """The music bed for a job's delivery. Jobs without a music
        prompt get the house bed. Jobs with one (paid customers
        only, gated at creation) get an ACE-Step bed generated from the prompt,
        cached per job on the data Volume. Any audio-stage failure
        falls back to the house bed and is flagged on the job record,
        so delivery never breaks on the music stage."""
        prompt = (job.get("music_prompt") or "").strip()
        if not prompt:
            return BED_PATH if BED_PATH.exists() else None
        bed_file = FILES_DIR / "beds" / f"{job['id']}.wav"
        if bed_file.exists():
            return bed_file
        try:
            data = _audio_bytes(
                "bed", _bed_payload_for_job(job), job,
                AUDIO_WEB_WAIT_SECONDS)
            bed_file.parent.mkdir(parents=True, exist_ok=True)
            bed_file.write_bytes(data)
            return bed_file
        except Exception:
            job["audio_fallback"] = True
            jobs[job["id"]] = job
            return BED_PATH if BED_PATH.exists() else None

    def _chain_concat(job: dict) -> Path:
        """Join a chained length's finished segments into one
        raw file (CPU re-encode: segment files from one lane
        share a shape, but the join must not depend on their
        stream layout matching to the byte)."""
        job_id = job["id"]
        joined = FILES_DIR / f"{job_id}.chain.mp4"
        if joined.exists():
            return joined
        seg_paths = [
            _chain_segment_file(job, idx, url)
            for idx, url in enumerate(job.get("chain_results") or [])
        ]
        list_path = FILES_DIR / f"{job_id}.chain.txt"
        list_path.write_text(
            "".join(
                f"file '{p.name}'\n" for p in seg_paths),
            encoding="utf-8")
        audio = ["-c:a", "aac", "-b:a", "160k"] \
            if _has_audio_stream(seg_paths[0]) else ["-an"]
        cmd = ["ffmpeg", "-y", "-f", "concat", "-safe", "0",
               "-i", str(list_path),
               "-c:v", "libx264", "-preset", "veryfast", "-crf", "20",
               *audio, str(joined)]
        proc = subprocess.run(cmd, capture_output=True, text=True,
                              timeout=1800)
        if proc.returncode != 0 or not joined.exists():
            raise HTTPException(
                status_code=502,
                detail="finished file is not available yet")
        data_volume.commit()
        return joined

    def ensure_processed(job: dict) -> Path:
        """Fetch the finished file if needed and produce the
        delivered file (music muxed, watermark for free-tier jobs;
        per-second-lane files keep their own sound, finished by
        _process_api_file)."""
        job_id = job["id"]
        FILES_DIR.mkdir(parents=True, exist_ok=True)
        out_path = FILES_DIR / f"{job_id}.mp4"
        if out_path.exists() and job.get("status") == "done":
            # A finished file with no output verdict yet (its
            # finishing-stage classification failed or predates
            # a retry): judge it now, on the owner's own fetch.
            # A no-op once a score is stamped, and capped after
            # a few attempts, so this costs a dict read per serve.
            classify_job_output(job, out_path)
            _gallery_feed_finished(job)
        if job.get("provider") == "clip":
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no single file")
        if job.get("provider") == "hyperframes":
            # The Kaggle worker uploads the finished file itself;
            # there is no raw stage and no finishing chain.
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no file yet")
        if job.get("provider") == "shorts":
            # The shorts processor assembles the finished file
            # itself, captions, narration, bed and all; there is
            # no raw stage and no finishing chain here either.
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no file yet")
        if job.get("provider") == "drama":
            # The drama driver assembles the episode file from
            # its shot jobs; like the shorts lane there is no raw
            # stage and no finishing chain here.
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no file yet")
        if job.get("provider") == "editclone":
            # Edit/Clone sources and hooks land finished from
            # their worker, exactly as they should play back:
            # no finishing chain ever touches them.
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no file yet")
        if job.get("provider") == "assembly":
            # A put-together movie lands finished from its
            # worker, exactly as it should play back: the
            # joining already happened, so no finishing chain
            # ever touches it.
            if not out_path.exists():
                try:
                    data_volume.reload()
                except Exception:
                    pass
            if out_path.exists():
                return out_path
            raise HTTPException(status_code=404, detail="this job has no file yet")
        if not out_path.exists():
            raw_path = FILES_DIR / f"{job_id}.raw.mp4"
            if len(job.get("chain_results") or []) > 1:
                # A chained length: the delivered video is the
                # segments joined, never just the last segment.
                raw_path = _chain_concat(job)
            elif not raw_path.exists():
                if job.get("provider") in URL_RESULT_PROVIDERS:
                    if not job.get("result_url"):
                        raise HTTPException(status_code=502, detail="finished file is not available yet")
                    # Scheme control (security fix, 2026-11-27,
                    # provider-result-download-uncontrolled-url):
                    # a provider result is fetched only over
                    # https, the same control the chain path
                    # already applied; the user-influence leg
                    # of that record stays unsettled (it needs
                    # a recorded live payload), but no result
                    # URL can steer this fetch off-scheme.
                    if not str(job["result_url"]).startswith("https://"):
                        raise HTTPException(status_code=502, detail="finished file is not available yet")
                    resp = requests.get(job["result_url"], timeout=300)
                    if resp.status_code != 200:
                        raise HTTPException(status_code=502, detail="finished file is not available yet")
                    raw_path.write_bytes(resp.content)
                else:
                    resp = requests.get(
                        f"{WORKER_BASE}/jobs/{job['worker_job_id']}/file",
                        headers=_worker_headers(), timeout=120,
                    )
                    if resp.status_code != 200:
                        raise HTTPException(status_code=502, detail="finished file is not available yet")
                    raw_path.write_bytes(resp.content)
            # Voiceover resolution (Jack's correction, 2026-11-16):
            # a speech script on a speech-native lane is performed
            # by the model itself; on any other lane the Kokoro
            # voiceover stage speaks it in post. No script, no
            # voiceover: a music bed is never passed off as speech.
            voice = None
            if job.get("speech_script"):
                if lane_audio(job.get("model") or DEFAULT_MODEL)["native_speech"]:
                    if job.get("voiceover_status") != "native":
                        job["voiceover_status"] = "native"
                        job["lipsync_status"] = "native"
                        jobs[job["id"]] = job
                else:
                    voice = _voiceover_for_job(job)
            if voice is not None and job.get("lip_sync"):
                # Built-in lip sync: the picture is re-rendered
                # against the job's own voice track before the
                # normal finishing mux, so the delivered video's
                # mouth matches the spoken line.
                synced = _lip_sync_for_job(job, raw_path, voice)
                if synced is not None:
                    raw_path = synced
            if job.get("provider") in URL_RESULT_PROVIDERS:
                bed = _bed_for_job(job) if job.get("music_prompt") else None
                try:
                    _process_api_file(raw_path, out_path, bed_path=bed,
                                      voice_path=voice)
                except Exception:
                    # Delivery never breaks on the finishing stage:
                    # fall back to the standard mux with a bed.
                    job["audio_fallback"] = True
                    jobs[job["id"]] = job
                    _process_file(raw_path, out_path, watermark=False,
                                  bed_path=_bed_for_job(job),
                                  voice_path=voice)
            else:
                # Watermark marks free-tier work, not a plan name:
                # a pay-per-video job on a free-plan account was
                # paid for and ships clean (Amendment 3). Jobs from
                # before the flag fall back to the plan recorded at
                # creation.
                _process_file(raw_path, out_path,
                              watermark=bool(job.get(
                                  "free_tier",
                                  job.get("plan_at_job") == "free")),
                              bed_path=_bed_for_job(job),
                              voice_path=voice)
            # Word check (2026-11-18): the delivered file's final
            # audio is checked against the spoken line, and a
            # same-voice repair is spliced in when one is possible.
            # The stage flags the job record and never blocks the
            # delivery above.
            _word_check_for_job(job, out_path)
            # Captions (2026-11-18): after the word check, so the
            # burned words are timed from the final audio exactly
            # as delivered, repaired track included. Only jobs
            # created with the box checked enter the stage.
            _captions_for_job(job, out_path)
            # Content fingerprint (2026-11-24): the delivered
            # file is final at this point, word check and
            # captions included, so the SHA-256 of this stored
            # original goes on the record. The web remux derived
            # from it at serve time is never stamped.
            stamp_content_hash(job, out_path)
            # Output classifier (2026-11-24): the delivered file
            # is final here too, so its gallery verdict is
            # stamped from the same bytes.
            classify_job_output(job, out_path)
            data_volume.commit()
            _gallery_feed_finished(job)
        return out_path

    def _moov_first(path: Path) -> bool:
        """True when the mp4's index (moov) sits ahead of its
        media data (mdat), the layout phones can start playing
        from the first bytes. Several producers write the index
        at the end instead, and phone browsers sit on a black
        player rather than fetch the tail first."""
        try:
            with open(path, "rb") as fh:
                head = fh.read(1 << 20)
        except Exception:
            return True
        moov = head.find(b"moov")
        mdat = head.find(b"mdat")
        if moov == -1:
            return False
        return mdat == -1 or moov < mdat

    def ensure_web_file(job: dict, src: Path) -> Path:
        """The copy of a finished video the players are served:
        the delivered file itself when its index is already up
        front, else a one time stream copy remux with the index
        moved to the front, cached beside it. No re-encode, the
        picture and sound are byte identical streams."""
        if _moov_first(src):
            return src
        web_path = FILES_DIR / f"{job['id']}.web.mp4"
        if not web_path.exists():
            try:
                data_volume.reload()
            except Exception:
                pass
        if web_path.exists() and _moov_first(web_path):
            return web_path
        tmp_path = FILES_DIR / f"{job['id']}.web.tmp.mp4"
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:
            pass
        try:
            subprocess.run(
                ["ffmpeg", "-y", "-i", str(src), "-c", "copy",
                 "-movflags", "+faststart", str(tmp_path)],
                check=True, capture_output=True, timeout=600)
            tmp_path.replace(web_path)
            data_volume.commit()
        except Exception:
            try:
                tmp_path.unlink(missing_ok=True)
            except Exception:
                pass
            return src
        return web_path

    def ensure_poster(job: dict) -> Path:
        """The preview picture for a finished video, its first
        frame, cut with ffmpeg the first time anyone needs it and
        cached beside the job's files under the same name the
        clipping pipeline already uses for its thumbnails. Later
        calls serve the cached picture."""
        poster_path = FILES_DIR / f"{job['id']}.jpg"
        if not poster_path.exists():
            try:
                data_volume.reload()
            except Exception:
                pass
        if poster_path.exists():
            return poster_path
        src = ensure_processed(job)
        tmp_path = FILES_DIR / f"{job['id']}.poster.tmp.jpg"
        try:
            tmp_path.unlink(missing_ok=True)
        except Exception:
            pass
        for seek in ("0.5", None):
            cmd = ["ffmpeg", "-y"]
            if seek:
                cmd += ["-ss", seek]
            cmd += ["-i", str(src), "-vframes", "1", "-q:v", "3",
                    str(tmp_path)]
            try:
                proc = subprocess.run(cmd, capture_output=True,
                                      text=True, timeout=120)
            except Exception:
                proc = None
            if (proc is not None and proc.returncode == 0
                    and tmp_path.exists()
                    and tmp_path.stat().st_size > 0):
                break
            try:
                tmp_path.unlink(missing_ok=True)
            except Exception:
                pass
        if not tmp_path.exists():
            raise HTTPException(status_code=404,
                                detail="no preview picture")
        tmp_path.replace(poster_path)
        data_volume.commit()
        return poster_path

    def _media_cache(job: dict, public: bool = False) -> str:
        """Cache lifetime for a job's media (perf pass,
        2026-11-24). A finished job's files never change under
        its id, so they cache for a year as immutable. The one
        exception is a drama episode: a shot retake re-renders
        the episode under the same id, so its media caches for
        an hour only."""
        scope = "public" if public else "private"
        if public:
            # Public gallery media is removable (security
            # fix, 2026-11-27, gallery-media-immutable-
            # cache): a year of immutable caching made
            # removal and opt-out unrecallable, so gallery
            # copies revalidate after an hour instead. The
            # owner's own media keeps the long cache: those
            # files never change under the job id and are
            # not the removal surface.
            return "public, max-age=3600, must-revalidate"
        if job.get("kind") == "drama":
            return f"{scope}, max-age=3600"
        return f"{scope}, max-age=31536000, immutable"

    def ensure_image_file(job: dict) -> Path:
        """Fetch a finished start image from the worker once and
        cache it on the data Volume. Images are delivered as made:
        no post chain, no watermark, no music stage."""
        FILES_DIR.mkdir(parents=True, exist_ok=True)
        out_path = FILES_DIR / f"{job['id']}.png"
        if not out_path.exists():
            try:
                data_volume.reload()
            except Exception:
                pass
        if not out_path.exists():
            resp = requests.get(
                f"{WORKER_BASE}/image-jobs/{job['worker_job_id']}/file",
                headers=_worker_headers(), timeout=120,
            )
            if resp.status_code != 200:
                raise HTTPException(status_code=502, detail="finished file is not available yet")
            out_path.write_bytes(resp.content)
            data_volume.commit()
        if not job.get("content_sha256"):
            # House image jobs land their file only here (the
            # worker keeps it until the first fetch), so theirs
            # is stamped now; shelf and worker-uploaded images
            # were already stamped when their bytes landed,
            # which makes this a no-op for them.
            stamp_content_hash(job, out_path)
        # The gallery verdict rides the same first fetch: a
        # no-op once the record carries a score.
        classify_job_output(job, out_path)
        _gallery_feed_finished(job)
        return out_path

    @web.get("/api/jobs/{job_id}/file")
    def job_file(job_id: str, request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        return job_file_core(user, job_id)

    def job_file_core(user: dict, job_id: str):
        """The one finished file read behind both file surfaces
        (the website's /api/jobs/{id}/file and the customer
        API's /api/v1/jobs/{id}/file): the owner's own finished
        job only."""
        job = jobs.get(job_id)
        if not job or job.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        job = mirror_status(job)
        if job["status"] != "done":
            raise HTTPException(status_code=409, detail=f"job status is {job['status']}")
        if job.get("kind") == "image":
            return FileResponse(
                ensure_image_file(job), media_type="image/png",
                filename=f"moonfactory-{job_id}.png",
                headers={"Cache-Control": _media_cache(job)})
        if job.get("kind") == "clip_job":
            raise HTTPException(status_code=409, detail="this clip job made several clips, open one of them")
        out_path = ensure_processed(job)
        try:
            # The finished file exists now, so its gallery preview
            # picture can be cut and cached with it.
            ensure_poster(job)
        except Exception:
            pass
        # Players get the web copy (index up front) inline, not
        # as a download: an attachment header plus an index at
        # the end of the file leaves phone browsers on a black
        # player (Jack, 2026-11-21).
        resp = FileResponse(ensure_web_file(job, out_path),
                            media_type="video/mp4",
                            filename=f"moonfactory-{job_id}.mp4",
                            headers={"Cache-Control": _media_cache(job)})
        resp.headers["content-disposition"] = (
            f'inline; filename="moonfactory-{job_id}.mp4"')
        return resp

    @web.get("/api/jobs/{job_id}/gif")
    def job_gif(job_id: str, request: Request,
                mf_session: str = Cookie(default="")):
        """The GIF a template job asked for (2026-11-27): the
        owner's own finished job only, served as a download.
        A job whose render predates the option, or whose GIF
        never landed, answers a plain 404."""
        user = require_user(request, mf_session)
        job = jobs.get(job_id)
        if not job or job.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        job = mirror_status(job)
        if job["status"] != "done" or not job.get("gif"):
            raise HTTPException(status_code=404, detail="this job has no gif")
        gif_path = FILES_DIR / f"{job_id}.gif"
        if not gif_path.exists():
            try:
                data_volume.reload()
            except Exception:
                pass
        if not gif_path.exists():
            raise HTTPException(status_code=404, detail="this job has no gif")
        return FileResponse(
            gif_path, media_type="image/gif",
            filename=f"moonfactory-{job_id}.gif",
            headers={"Content-Disposition":
                     f'attachment; filename="moonfactory-{job_id}.gif"'})

    @web.get("/api/jobs/{job_id}/poster")
    def job_poster(job_id: str, request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        job = jobs.get(job_id)
        if not job or job.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        job = mirror_status(job)
        if job["status"] != "done" or job.get("kind") == "image":
            raise HTTPException(status_code=409, detail="no poster")
        return FileResponse(ensure_poster(job), media_type="image/jpeg",
                            filename=f"moonfactory-{job_id}.jpg",
                            headers={"Cache-Control": _media_cache(job)})

    @web.delete("/api/jobs/{job_id}")
    def delete_job(job_id: str, request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        job = jobs.get(job_id)
        if not job or job.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown job")
        if job.get("kind") == "drama":
            # Deleting an episode takes its shot jobs and its
            # drama record with it. An unsettled parent settles
            # its finished shots first, so the hold never strands:
            # finished shots charge, the rest refunds.
            rec = dramas.get(job.get("drama_id") or "")
            child_ids = []
            if rec:
                for shot in rec.get("shots") or []:
                    if shot.get("child_job_id"):
                        child_ids.append(shot["child_job_id"])
                if rec.get("retake_child_id"):
                    child_ids.append(rec["retake_child_id"])
            if not job.get("settled"):
                fresh = users.get(f"id:{user['id']}") or user
                _drama_settle_finished(job, rec, fresh)
                job = jobs.get(job_id) or job
            for cid in child_ids:
                child = jobs.get(cid)
                if child:
                    if child.get("status") == "done" \
                            and not child.get("content_sha256"):
                        stamp_content_hash(
                            child, FILES_DIR / f"{cid}.mp4")
                    write_job_tombstone(child)
                    del jobs[cid]
                    _unindex_job(child.get("user_id"), cid)
                if not legal_hold_active(cid):
                    _unlink_job_files(cid, child)
            carry = FILES_DIR / f"{job_id}.carry.png"
            try:
                carry.unlink(missing_ok=True)
            except Exception:
                pass
            if rec:
                del dramas[rec["id"]]
        if job.get("status") == "done" \
                and not job.get("content_sha256"):
            # A done job whose stored original exists but was
            # never stamped (its finishing hook has not run for
            # it) is stamped from that file now, so the
            # tombstone below still carries its fingerprint.
            stamp_content_hash(
                job, FILES_DIR / (f"{job_id}.png"
                                  if job.get("kind") == "image"
                                  else f"{job_id}.mp4"))
        write_job_tombstone(job)
        del jobs[job_id]
        _unindex_job(user["id"], job_id)
        _gallery_cache_clear(job_id)
        # Every derivative on the shared manifest goes with
        # the record (fix, 2026-11-27,
        # delete-job-leaves-file-derivatives) -- except a
        # held job's files, which the hold preserves.
        if not legal_hold_active(job_id):
            _unlink_job_files(job_id, job)
        data_volume.commit()
        return {"status": "deleted"}


    # -- clipping (CLIPPING-DESIGN.md sections 4, 6, 8) --------------------
    # Clip jobs are platform jobs: same accounts, holds, ceilings,
    # library and gallery rules as generation jobs. Free accounts are
    # refused (no free clipping at launch). Creator subscribers debit
    # the shared included budget at the 0.9c per source minute floor
    # rate; everyone else pays 5c per source minute from balance. The
    # exact charge is quoted before the job runs, from the probed
    # duration rounded up to whole minutes.

    def _clip_quote_for(user: dict, duration_seconds: float) -> dict:
        q = pricing.clip_quote(duration_seconds, owner=is_owner(user))
        remaining = included_budget_remaining(user)
        if user["plan"] == "creator" and remaining >= q["included_debit_cents"]:
            method = "included"
        elif int(user.get("balance_cents", 0)) >= q["balance_charge_cents"] \
                or is_owner(user):
            # The owner pays from balance even when the balance
            # cannot cover it (Jack, 2026-11-17), matching create.
            method = "balance"
        else:
            method = "insufficient"
        return {
            **q,
            "duration_seconds": round(float(duration_seconds), 2),
            "method": method,
            "ceiling_ok": ceiling_allows(user, q["worst_case_cost_cents"]),
            "included_budget_remaining_cents": round(remaining, 2),
            "balance_cents": int(user.get("balance_cents", 0)),
        }

    @web.post("/api/clips/quote")
    async def quote_clip(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="clipping is a paid feature")
        body = await request.json()
        if body.get("url"):
            try:
                clipping.validate_fetch_url(body["url"])
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            try:
                info = clip_probe.remote(body["url"])
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            except Exception:
                raise HTTPException(status_code=502,
                                    detail=clipping.LINK_DEAD_MESSAGE)
            duration = float(info.get("duration") or 0)
            if duration <= 0:
                raise HTTPException(status_code=422, detail="that link has no readable duration")
            if duration > pricing.CLIP_MAX_SOURCE_SECONDS:
                raise HTTPException(status_code=422, detail="this video is longer than the 3 hour clipping limit")
            return {**_clip_quote_for(user, duration),
                    "title": info.get("title") or ""}
        try:
            duration = float(body.get("duration_seconds") or 0)
        except (TypeError, ValueError):
            duration = 0
        if duration <= 0:
            raise HTTPException(status_code=422, detail="duration_seconds or a link is required")
        if duration > pricing.CLIP_MAX_SOURCE_SECONDS:
            raise HTTPException(status_code=422, detail="this video is longer than the 3 hour clipping limit")
        return _clip_quote_for(user, duration)

    # Retained-upload quota (security fix, 2026-11-27,
    # retained-uploads-unbounded): an account's retained
    # upload sources are capped in total bytes -- 1 GiB for
    # an account that has never paid (the template lane is
    # its only upload surface, at 200 MB a file) and 4 GiB
    # for a paying account (a single clip source may be
    # 2 GiB). Consumption and the reaper free space back.
    UPLOAD_CAP_FREE_BYTES = 1 * 1024 ** 3
    UPLOAD_CAP_PAID_BYTES = 4 * 1024 ** 3

    def _upload_bytes_retained(user_id: str) -> int:
        total = 0
        for key in list(meta.keys()):
            if not key.startswith(UPLOAD_RECORD_PREFIXES):
                continue
            rec = meta.get(key) or {}
            if rec.get("user_id") == user_id and rec.get("path"):
                total += int(rec.get("bytes") or 0)
        return total

    UPLOAD_QUOTA_DETAIL = (
        "your saved uploads are full. Finish or delete "
        "something that uses an older upload, or wait for "
        "old uploads to clear")

    def _upload_quota_allows(user: dict, incoming: int) -> bool:
        cap = UPLOAD_CAP_PAID_BYTES if is_paid(user) \
            else UPLOAD_CAP_FREE_BYTES
        return _upload_bytes_retained(user["id"]) + incoming <= cap

    @web.post("/api/clips/upload")
    async def upload_clip_source(request: Request, file: UploadFile = File(...),
                                 mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="clipping is a paid feature")
        if _rate_limited("clipupload", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many uploads, slow down")
        upload_id = pysecrets.token_hex(8)
        src_dir = Path("/data/clip-sources")
        src_dir.mkdir(parents=True, exist_ok=True)
        suffix = Path(file.filename or "upload.mp4").suffix.lower()
        if suffix not in (".mp4", ".mov", ".mkv", ".webm", ".m4v"):
            suffix = ".mp4"
        dest = src_dir / f"{upload_id}{suffix}"
        size = 0
        with dest.open("wb") as fh:
            while True:
                chunk = await file.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > pricing.CLIP_MAX_UPLOAD_BYTES:
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail="file is larger than the 2 GiB upload limit")
                if not _upload_quota_allows(user, size):
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail=UPLOAD_QUOTA_DETAIL)
                fh.write(chunk)
        data_volume.commit()
        try:
            info = clipping.probe(dest)
        except Exception as exc:
            dest.unlink(missing_ok=True)
            raise HTTPException(status_code=422, detail=str(exc)[:200])
        if float(info["duration"]) > pricing.CLIP_MAX_SOURCE_SECONDS:
            dest.unlink(missing_ok=True)
            raise HTTPException(status_code=422, detail="this video is longer than the 3 hour clipping limit")
        meta[f"clipupload:{upload_id}"] = {
            "user_id": user["id"], "path": str(dest),
            "bytes": size,
            "duration": float(info["duration"]),
            "filename": (file.filename or "upload")[:120],
            "created_at": _now(),
        }
        return {"upload_id": upload_id,
                **_clip_quote_for(user, float(info["duration"]))}

    @web.post("/api/clips")
    async def create_clip(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if _rate_limited("clipcreate", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        body = await request.json()
        if not bot_check_ok(body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        return create_clip_core(user, body, client_ip(request))

    def create_clip_core(user: dict, body: dict, ip: str):
        """The one clipping creation path behind both create
        surfaces (the website's /api/clips and the job retry
        path, which rebuilds the body from the stored record
        and calls this core directly with it): every gate
        below the website wrapper runs here. The website
        wrapper adds only its session auth, its pace limit,
        and the browser bot check."""
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="clipping is a paid feature")
        # "auto" is a real clip count (2026-11-27, Jack's
        # order): the job stores it as-is and the pipeline
        # resolves it from the source itself, the duration
        # cap plus the picker's strong moments (see
        # clipping.auto_clip_cap and find_clips' min_score).
        raw_count = body.get("clip_count")
        if isinstance(raw_count, str) \
                and raw_count.strip().lower() == "auto":
            clip_count = "auto"
        else:
            try:
                clip_count = int(raw_count or 3)
            except (TypeError, ValueError):
                clip_count = 3
            if clip_count < 1 or clip_count > pricing.CLIP_MAX_CLIPS_PER_JOB:
                raise HTTPException(
                    status_code=422,
                    detail=f"clip count must be between 1 and {pricing.CLIP_MAX_CLIPS_PER_JOB}")
        length = body.get("length") or "medium"
        if length not in clipping.LENGTH_RANGES:
            raise HTTPException(status_code=422, detail="length must be auto, short, medium or long")
        caption_style = body.get("caption_style") or clipping.NO_CAPTION_STYLE
        if caption_style not in clipping.CAPTION_STYLES:
            raise HTTPException(
                status_code=422,
                detail="caption style must be one of "
                + ", ".join(clipping.CAPTION_STYLES.values()))
        layout = body.get("layout") or "blur"
        if layout == "crop":
            # Jobs made before the no-crop rule (2026-11-27)
            # carry "crop"; it renders as the blur fit now,
            # the whole frame kept.
            layout = "blur"
        if layout not in clipping.LAYOUTS:
            raise HTTPException(
                status_code=422,
                detail="layout must be one of "
                + ", ".join(clipping.LAYOUTS.values()))
        upload_path = None
        source_url = None
        source_title = ""
        if body.get("upload_id"):
            rec = meta.get(f"clipupload:{body['upload_id']}")
            if not rec or rec.get("user_id") != user["id"]:
                raise HTTPException(status_code=404, detail="unknown upload")
            upload_path = rec["path"]
            duration = float(rec["duration"])
            source_title = rec.get("filename") or ""
        elif body.get("url"):
            try:
                source_url = clipping.validate_fetch_url(body["url"])
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            try:
                info = clip_probe.remote(source_url)
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            except Exception:
                raise HTTPException(status_code=502,
                                    detail=clipping.LINK_DEAD_MESSAGE)
            duration = float(info.get("duration") or 0)
            source_title = info.get("title") or ""
            if duration <= 0:
                raise HTTPException(status_code=422, detail="that link has no readable duration")
        else:
            raise HTTPException(status_code=422, detail="paste a link or upload a file")
        # The illegal-content gate (Jack, 2026-11-24): a clip
        # takes no typed prompt, so the gate reads the source
        # title, the only words the job carries, and the call
        # is also what bars a suspended account from the lane.
        enforce_prompt_gate(
            user, "clip", ip, source_title)
        if duration > pricing.CLIP_MAX_SOURCE_SECONDS:
            raise HTTPException(status_code=422, detail="this video is longer than the 3 hour clipping limit")
        q = pricing.clip_quote(duration, owner=is_owner(user))
        reload_state = {}
        if not ceiling_allows(user, q["worst_case_cost_cents"]):
            attempt_auto_reload(user, reload_state,
                                needed_cents=int(q["balance_charge_cents"]))
        if not ceiling_allows(user, q["worst_case_cost_cents"]):
            raise HTTPException(
                status_code=402,
                detail=reload_fail_detail(reload_state, "this job would exceed the total generation your payments cover"))
        # Hold the exact charge before dispatch (Rule 1). Included
        # budget pays first for subscribers; balance is the other rail.
        u = usage(user)
        if user["plan"] == "creator" and included_budget_remaining(user) >= q["included_debit_cents"]:
            hold_kind = "included"
            hold_amount = q["included_debit_cents"]
            u["included_cost_cents"] = included_cost_used(user) + hold_amount
            user["usage"] = u
        elif int(user.get("balance_cents", 0)) >= q["balance_charge_cents"]:
            hold_kind = "balance"
            hold_amount = q["balance_charge_cents"]
            user["balance_cents"] = int(user.get("balance_cents", 0)) - int(hold_amount)
        elif is_owner(user):
            # The owner answers to the provider only (Jack,
            # 2026-11-17): the hold is taken against his balance
            # whatever it holds, before the auto reload branch, so
            # a reload never fires for his account.
            hold_kind = "balance"
            hold_amount = q["balance_charge_cents"]
            user["balance_cents"] = int(user.get("balance_cents", 0)) - int(hold_amount)
        elif attempt_auto_reload(user, reload_state, needed_cents=int(q["balance_charge_cents"])) and int(user.get("balance_cents", 0)) >= q["balance_charge_cents"]:
            hold_kind = "balance"
            hold_amount = q["balance_charge_cents"]
            user["balance_cents"] = int(user.get("balance_cents", 0)) - int(hold_amount)
        else:
            raise HTTPException(
                status_code=402,
                detail=reload_fail_detail(reload_state, f"included budget used up; clipping this video costs {q['balance_charge_cents']} cents of prepaid balance"))
        save_user(user)
        job = {
            "id": pysecrets.token_hex(8),
            "user_id": user["id"],
            "worker_job_id": None,
            "provider": "clip",
            "kind": "clip_job",
            "lane": "clip",
            "model": "clip",
            "prompt": source_title or source_url or "Uploaded video",
            "user_prompt": source_title or source_url or "Uploaded video",
            "camera_presets": [],
            "camera_preset_names": [],
            "camera_look": {},
            "status": "queued",
            "stage": CLIP_STAGES[0],
            "error": None,
            "created_at": _now(),
            "created_ip": ip,
            "charged_cents": 0,
            "source_url": source_url,
            "upload_path": upload_path,
            "source_title": source_title,
            "duration_seconds": round(duration, 2),
            "source_minutes": q["source_minutes"],
            "clip_count": clip_count,
            "length": length,
            "caption_style": caption_style,
            "layout": layout,
            "hold_kind": hold_kind,
            "hold_amount": hold_amount,
            "plan_at_job": user["plan"],
            "free_tier": False,
            "music_prompt": None,
            "clip_ids": [],
        }
        jobs[job["id"]] = job
        _index_job(job)
        process_clip_job.spawn(job["id"])
        return JSONResponse({**public_job(job), "quote": q}, status_code=202)

    # -- Clone (2026-11-26) ------------------------------------------------
    # The Clone tab: ingest a source from any
    # link, an upload, or the library; cut its hook; build a
    # character from its frames; and clone it through the normal
    # job creation path on the model the user picks in the
    # section's own picker. Ingest, hook and character building
    # are free for paid accounts (the character store's own
    # precedent: creation is free, only training charges); the
    # clone is an ordinary paid job.


    def _editclone_source_job(user: dict, source_job_id) -> dict:
        """An owned, finished video whose file is in the library:
        the one shape every Edit/Clone step starts from."""
        job = jobs.get(str(source_job_id or ""))
        if not job or job.get("user_id") != user["id"]:
            raise HTTPException(status_code=404, detail="unknown video")
        if job.get("kind") == "image":
            raise HTTPException(
                status_code=422, detail="that is a picture, pick a video")
        if job.get("status") != "done":
            raise HTTPException(
                status_code=409, detail="that video is not ready yet")
        if not (FILES_DIR / f"{job['id']}.mp4").exists():
            # A worker may have landed the file after this web
            # container last refreshed the volume (hit by the
            # 2026-11-27 link ingest proof, cloning a source
            # ingested minutes earlier): refresh once before
            # calling the file gone.
            try:
                data_volume.reload()
            except Exception:
                pass
        if not (FILES_DIR / f"{job['id']}.mp4").exists():
            raise HTTPException(
                status_code=422,
                detail="that video's file is not in your library anymore")
        return job

    def _editclone_new_job(user: dict, request: Request, **fields) -> dict:
        # The suspension bar (security fix, 2026-11-27,
        # suspension-not-enforced-on-all-create-paths): every
        # Clone creation is built here, and this path never
        # crossed the gate, so a suspended account could keep
        # creating. The gate with no texts is the bar alone.
        enforce_prompt_gate(user, "editclone", client_ip(request))
        job = {
            "id": pysecrets.token_hex(8),
            "user_id": user["id"],
            "worker_job_id": None,
            "provider": "editclone",
            "lane": "editclone",
            "model": "editclone",
            "camera_presets": [],
            "camera_preset_names": [],
            "camera_look": {},
            "status": "queued",
            "stage": EDITCLONE_STAGES[0],
            "error": None,
            "created_at": _now(),
            "created_ip": client_ip(request),
            "charged_cents": 0,
            "plan_at_job": user["plan"],
            "free_tier": False,
            "music_prompt": None,
            # A source or a hook is the user's own working
            # material, never a public gallery piece.
            "gallery_public": False,
        }
        job.update(fields)
        jobs[job["id"]] = job
        _index_job(job)
        return job

    @web.post("/api/editclone/upload")
    async def upload_editclone_source(request: Request,
                                      file: UploadFile = File(...),
                                      mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="Clone is a paid feature")
        if _rate_limited("ecupload", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many uploads, slow down")
        upload_id = pysecrets.token_hex(8)
        src_dir = Path("/data/ec-sources")
        src_dir.mkdir(parents=True, exist_ok=True)
        suffix = Path(file.filename or "upload.mp4").suffix.lower()
        if suffix not in (".mp4", ".mov", ".mkv", ".webm", ".m4v"):
            suffix = ".mp4"
        dest = src_dir / f"{upload_id}{suffix}"
        size = 0
        with dest.open("wb") as fh:
            while True:
                chunk = await file.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > EDITCLONE_MAX_UPLOAD_BYTES:
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail="file is larger than the 1 GiB upload limit")
                if not _upload_quota_allows(user, size):
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail=UPLOAD_QUOTA_DETAIL)
                fh.write(chunk)
        data_volume.commit()
        try:
            info = clipping.probe_media(dest)
        except Exception as exc:
            dest.unlink(missing_ok=True)
            raise HTTPException(status_code=422, detail=str(exc)[:200])
        if float(info["duration"]) > EDITCLONE_MAX_SOURCE_SECONDS:
            dest.unlink(missing_ok=True)
            raise HTTPException(status_code=422, detail="this video is longer than the Clone limit of 10 minutes")
        meta[f"ecupload:{upload_id}"] = {
            "user_id": user["id"], "path": str(dest),
            "bytes": size,
            "duration": float(info["duration"]),
            "filename": (file.filename or "upload")[:120],
            "created_at": _now(),
        }
        return {"upload_id": upload_id,
                "duration_seconds": round(float(info["duration"]), 2)}

    @web.post("/api/editclone/ingest")
    async def create_editclone_source(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if _rate_limited("ecingest", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        body = await request.json()
        if not bot_check_ok(body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="Clone is a paid feature")
        upload_path = None
        source_url = None
        source_title = ""
        duration = 0.0
        if body.get("upload_id"):
            rec = meta.get(f"ecupload:{body['upload_id']}")
            if not rec or rec.get("user_id") != user["id"]:
                raise HTTPException(status_code=404, detail="unknown upload")
            upload_path = rec["path"]
            duration = float(rec["duration"])
            source_title = rec.get("filename") or ""
        elif body.get("url"):
            try:
                source_url = clipping.validate_ingest_url(body["url"])
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            try:
                info = _editclone_probe_any(source_url)
            except ValueError as exc:
                raise HTTPException(status_code=422, detail=str(exc))
            except Exception:
                raise HTTPException(status_code=502,
                                    detail=clipping.LINK_DEAD_MESSAGE)
            duration = float(info.get("duration") or 0)
            source_title = info.get("title") or ""
            if duration > EDITCLONE_MAX_SOURCE_SECONDS:
                raise HTTPException(status_code=422, detail="this video is longer than the Clone limit of 10 minutes")
        else:
            raise HTTPException(status_code=422, detail="paste a link or upload a file")
        # The illegal-content gate reads the source title, the
        # only words an ingest carries (the clip path's rule).
        enforce_prompt_gate(
            user, "editclone", client_ip(request), source_title)
        job = _editclone_new_job(
            user, request,
            kind="edit_source",
            prompt=source_title or source_url or "Uploaded video",
            user_prompt=source_title or source_url or "Uploaded video",
            ec_action="ingest",
            source_url=source_url,
            upload_path=upload_path,
            source_title=source_title,
            duration_seconds=round(duration, 2),
        )
        process_editclone_job.spawn(job["id"])
        return JSONResponse(public_job(job), status_code=202)

