    @web.post("/api/editclone/character")
    async def create_editclone_character(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if _rate_limited("eccharacter", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="characters are a paid feature")
        body = await request.json()
        name = (body.get("name") or "").strip()[:60]
        if not name:
            raise HTTPException(status_code=422, detail="a character needs a name")
        # The character name is user text the choke-point
        # gate call does not see (security fix, 2026-11-27,
        # suspension-not-enforced-on-all-create-paths): gate
        # it here, before the job is built.
        enforce_prompt_gate(
            user, "editclone", client_ip(request), name)
        if len(user.get("characters") or []) >= MAX_CHARACTERS:
            raise HTTPException(
                status_code=422,
                detail=f"an account holds up to {MAX_CHARACTERS} characters")
        src = _editclone_source_job(user, body.get("source_job_id"))
        job = _editclone_new_job(
            user, request,
            kind="ec_character",
            prompt=name,
            user_prompt=name,
            ec_action="character",
            character_name=name,
            source_job_id=src["id"],
        )
        process_editclone_job.spawn(job["id"])
        return JSONResponse(public_job(job), status_code=202)

    def _editclone_hosted_source(src: dict) -> str:
        """The source video at a public URL: the reference
        branches send Video1 to the lane, and lanes take URLs,
        not bytes. The ingest hosts the source as it lands; a
        source that predates that (or whose hosting failed) is
        hosted now, at create time, from its library file."""
        hosted = src.get("hosted_url")
        if hosted:
            return hosted
        hosted = _fal_upload_bytes(
            (FILES_DIR / f"{src['id']}.mp4").read_bytes(),
            "video/mp4", f"{src['id']}.mp4")
        if not hosted:
            raise HTTPException(
                status_code=503,
                detail="that video could not be prepared for cloning, try again")
        src["hosted_url"] = hosted
        jobs[src["id"]] = src
        return hosted

    def _editclone_char_image_url(character: dict):
        """Image1 at a public URL: the character's first hosted
        picture, hosted from its stored bytes when the record
        carries no hosted copy."""
        images = character.get("images") or []
        for im in images:
            if im.get("fal_url"):
                return im["fal_url"]
        for im in images:
            if im.get("b64"):
                try:
                    data = base64.b64decode(im["b64"])
                except Exception:
                    continue
                url = _fal_upload_bytes(data, "image/png", "character.png")
                if url:
                    return url
        return None

    def _editclone_source_frame_urls(src: dict, duration: float) -> list:
        """Still frames from the source at a public URL each:
        the opening frame plus a spread across the clip, for
        the lanes that take reference images but no reference
        video. Grabbed with the same clipping helper the
        character builder uses, hosted like the source video."""
        work = Path(tempfile.mkdtemp(prefix="ec-frames-", dir="/data"))
        try:
            frames = clipping.grab_frames(
                FILES_DIR / f"{src['id']}.mp4", work, "frame",
                duration, fractions=EDITCLONE_FRAME_FRACTIONS)
            # Judged before they are hosted (security fix,
            # 2026-11-27, input-classifier-character-
            # laundering): the frames' bytes are in hand
            # here, and the Clone lanes are regular lanes,
            # so a flagged or unjudged frame set refuses
            # like any other upload.
            blobs = [fp.read_bytes() for fp in frames]
            verdict = classify_input_images(
                b64_images=[base64.b64encode(b).decode()
                            for b in blobs])
            refusal = input_gate_refusal(
                {"model": "editclone", "lane": "editclone"},
                verdict)
            if refusal:
                raise HTTPException(
                    status_code=400, detail=refusal)
            urls = []
            for fp, blob in zip(frames, blobs):
                url = _fal_upload_bytes(
                    blob, "image/jpeg", fp.name)
                if not url:
                    raise HTTPException(
                        status_code=503,
                        detail="that video could not be prepared for cloning, try again")
                urls.append(url)
            return urls
        except HTTPException:
            raise
        except Exception:
            raise HTTPException(
                status_code=503,
                detail="that video could not be prepared for cloning, try again")
        finally:
            shutil.rmtree(work, ignore_errors=True)

    def _editclone_out_seconds(natives: list, target: float) -> int:
        """The native length at or below the target seconds
        (the no-trim rule: a clone never asks a lane for a
        length the lane does not make)."""
        chosen = natives[0]
        for n in natives:
            if n <= target:
                chosen = n
        return chosen

    def _editclone_clone_body(user: dict, body: dict) -> dict:
        """The /api/jobs body for a character-swap clone of a
        library source, on the model the user picked in the
        section's own picker (any video model the Create
        picker offers). The platform adapts the inputs to the
        picked lane (editclone_clone_adaptation): Video1 and
        Image1 ride as references where the lane takes both;
        a lane that takes reference images only gets Image1
        plus still frames from the source; a start-image lane
        gets Image1 as the start image; Wan Motion gets
        Image1 as its subject and Video1 as its driving
        video; a lane that takes no visual input gets the
        prompt alone. A house lane rides the house job path
        instead: Image1 as the start image on the lane's own
        image-to-video shape, the source's length in house
        segments, and the lane's own segment pricing, never
        the per-second machinery. Building the body here,
        once, means the quote and the create can never
        disagree about the composition."""
        model = body.get("model") or EDITCLONE_CLONE_MODEL
        if model not in PER_SECOND_MODELS \
                and model not in HOUSE_MODEL_PRICING_LANE:
            raise HTTPException(status_code=422, detail="unknown model")
        src = _editclone_source_job(user, body.get("source_job_id"))
        character = _find_character(user, body.get("character_id") or "")
        if not character:
            raise HTTPException(status_code=404, detail="unknown character")
        images = character.get("images") or []
        char_b64 = images[0].get("b64") if images else None
        if not char_b64 and images and images[0].get("fal_url"):
            # A record whose first picture is hosted only:
            # fetch the bytes back so the start-image branches
            # can carry it.
            try:
                resp = requests.get(images[0]["fal_url"], timeout=30)
                if resp.status_code == 200:
                    char_b64 = base64.b64encode(resp.content).decode()
            except Exception:
                char_b64 = None
        char_url = _editclone_char_image_url(character) if images else None
        if not char_b64 and not char_url:
            raise HTTPException(
                status_code=422,
                detail="that character has no usable picture yet")
        duration = float(src.get("duration_seconds") or 0)
        if duration <= 0:
            try:
                duration = float(
                    clipping.probe_media(
                        FILES_DIR / f"{src['id']}.mp4")["duration"])
            except Exception:
                duration = 0.0
        if duration <= 0:
            raise HTTPException(
                status_code=422,
                detail="that video has no readable length")
        width = int(src.get("source_width") or 0)
        height = int(src.get("source_height") or 0)
        if width and height and width > height:
            aspect = "16:9"
        elif width and height and width == height:
            aspect = "1:1"
        else:
            aspect = "9:16"
        prompt = (body.get("prompt") or CLONE_PROMPT_TEMPLATE).strip()
        if model in HOUSE_MODEL_PRICING_LANE:
            # The house lanes: the clone is a house job, built
            # in the house body's own shape. The character
            # picture is the start image (every house lane
            # runs image-to-video; HunyuanVideo 1.5's
            # step-distilled I2V included, and the Uncut lane
            # requires one), the length is the source's
            # length in house segments (LTX-2.5 Uncensored
            # renders one clip per job, so its clone is one
            # segment however long the source runs), and
            # create_job prices and settles it on the lane's
            # own segment accounting exactly like a normal
            # house generation. The house dispatch carries
            # no reference channel, so no frame of the source
            # is sent: the prompt template carries the clone,
            # and the picker's feed line says so plainly.
            if not char_b64:
                raise HTTPException(
                    status_code=422,
                    detail="that character has no usable picture yet")
            if model == "ltx25_unc":
                segments = 1
            else:
                segments = min(
                    MAX_SEGMENTS,
                    max(1, math.ceil(duration / SEGMENT_SECONDS)))
            house_body = {
                "model": model,
                "prompt": prompt,
                "aspect_ratio": aspect,
                "start_image_png_b64": char_b64,
                "segments": segments,
            }
            if model == "wan2.2":
                # Wan 2.2's image-to-video lane is Production
                # (Draft is its text lane, and a clone always
                # carries the start image); the other three
                # house models select their lane by the model
                # alone, so no lane field rides along.
                house_body["lane"] = "production"
            return house_body
        adaptation = editclone_clone_adaptation(model)
        natives = native_lengths(model)
        new_body = {
            "model": model,
            "prompt": prompt,
            "resolution": pricing.MODEL_RESOLUTIONS.get(
                model, pricing.RESOLUTIONS)[0],
            "aspect_ratio": aspect,
        }
        if adaptation == "both":
            if not char_url:
                raise HTTPException(
                    status_code=422,
                    detail="that character has no usable picture yet")
            ref_cap = float(MODEL_REF_VIDEO_SECONDS_CAP.get(
                model, 15.0))
            ref_seconds = min(duration, ref_cap)
            new_body["duration_seconds"] = _editclone_out_seconds(
                natives, ref_seconds)
            new_body["reference_video_urls"] = [
                _editclone_hosted_source(src)]
            new_body["reference_video_seconds"] = round(ref_seconds, 2)
            new_body["reference_image_urls"] = [char_url]
        elif adaptation == "motion":
            if not char_b64:
                raise HTTPException(
                    status_code=422,
                    detail="that character has no usable picture yet")
            driving = min(duration, 30.0)
            if driving < 2:
                raise HTTPException(
                    status_code=422,
                    detail="that video is too short to clone with this model")
            new_body["duration_seconds"] = int(round(driving))
            new_body["reference_video_urls"] = [
                _editclone_hosted_source(src)]
            new_body["reference_video_seconds"] = round(driving, 2)
            new_body["start_image_png_b64"] = char_b64
        elif adaptation == "frames":
            if not char_url:
                raise HTTPException(
                    status_code=422,
                    detail="that character has no usable picture yet")
            frame_urls = _editclone_source_frame_urls(src, duration)
            cap_images = ref_caps_for(model)[0]
            new_body["duration_seconds"] = _editclone_out_seconds(
                natives, duration)
            new_body["reference_image_urls"] = (
                [char_url] + frame_urls)[:cap_images]
        elif adaptation == "start":
            if not char_b64:
                raise HTTPException(
                    status_code=422,
                    detail="that character has no usable picture yet")
            new_body["duration_seconds"] = _editclone_out_seconds(
                natives, duration)
            new_body["start_image_png_b64"] = char_b64
        else:  # "text": the prompt alone carries the clone.
            new_body["duration_seconds"] = _editclone_out_seconds(
                natives, duration)
        return new_body

    @web.post("/api/editclone/clone/quote")
    async def quote_editclone_clone(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="Clone is a paid feature")
        body = await request.json()
        new_body = _editclone_clone_body(user, body)
        if new_body["model"] in HOUSE_MODEL_PRICING_LANE:
            # A house clone quotes on the lane's own segment
            # accounting (quote_job's house answer is the
            # whole price table, not this job's price), in
            # the same answer shape the section renders for
            # a per-second quote: the included rail when the
            # subscription budget covers the segments at
            # create_job's house unit, else the lane's job
            # price times the segments from the balance. The
            # create below charges exactly this, because it
            # is create_job's own house accounting read early.
            lane = HOUSE_MODEL_PRICING_LANE[new_body["model"]]
            segments = int(new_body["segments"])
            answer = {
                "model": new_body["model"],
                "model_label": MODEL_LABELS[new_body["model"]],
                "segments": segments,
                "balance_debit_cents": 0,
                "payment": {"method": "balance"},
            }
            if pricing.lane_paused(lane):
                answer["lane_paused"] = True
                answer["payment"] = {"method": "unavailable"}
                return answer
            included_unit = pricing.MEASURED_COST_CENTS["production"]
            remaining = included_budget_remaining(user)
            if user["plan"] == "creator" \
                    and remaining >= included_unit * segments:
                answer["payment"] = {
                    "method": "included",
                    "included_debit_cents": round(
                        included_unit * segments, 2),
                    "included_budget_remaining_cents": round(
                        remaining, 2),
                }
                return answer
            answer["balance_debit_cents"] = pricing.job_price_cents(
                lane, owner=is_owner(user)) * segments
            return answer
        # The composed body goes to quote_job_core directly
        # (2026-11-27 fix): a request._body substitution never
        # reaches quote_job's cached request.json(), so a
        # per-second clone quoted the raw request body instead
        # of the composition the builder made.
        return quote_job_core(user, new_body)

    @web.post("/api/editclone/clone")
    async def create_editclone_clone(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not is_paid(user):
            raise HTTPException(status_code=403, detail="Clone is a paid feature")
        body = await request.json()
        new_body = _editclone_clone_body(user, body)
        for key in ("challenge_id", "challenge_nonce", "turnstile_token"):
            if body.get(key):
                new_body[key] = body[key]
        # The composed body goes to create_job_core directly
        # (2026-11-27 fix): a request._body substitution never
        # reaches the core, because the parse above already
        # cached this request's json and create_job's own
        # request.json() answers from that cache, so the core
        # read the raw request and every composed field (the
        # template prompt, the character picture as the start
        # image, the segments, the production lane, the aspect)
        # was dropped. create_job's wrapper checks run here
        # against the composed body instead, the same checks in
        # the same order.
        if _rate_limited("jobcreate", user["id"], 10):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        if not bot_check_ok(new_body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        result = create_job_core(
            user, new_body, base_url(request), client_ip(request))
        try:
            created = json.loads(result.body)
            created_id = created.get("id")
            if created_id:
                created_job = jobs.get(created_id)
                if created_job:
                    created_job["editclone_source_id"] = \
                        body.get("source_job_id")
                    jobs[created_id] = created_job
        except Exception:
            pass
        return result

    # -- template lane (HyperFrames on Kaggle) ----------------------------
    # Free motion graphics: title cards, captions over a clip, stat
    # cards, promo cards. Zero credits and zero charge. A Kaggle
    # kernel does the rendering; the platform only queues, wakes
    # the kernel, and serves the finished file. The worker
    # endpoints below are how the kernel talks back, guarded by a
    # dedicated key that lives in the moonfactory-secrets store on
    # this side and in a private Kaggle dataset on that side.

    def _hf_maybe_trigger():
        """Wake the Kaggle worker when a queued template job has
        no live kernel. A push of a fresh kernel version is what
        makes Kaggle run it. Throttled by the heartbeat's freshness
        and a minimum gap between attempts, and it never raises:
        a failed wake simply leaves the job queued for the next
        nudge, inside its poll bound."""
        try:
            now = _now()
            if now - float(meta.get("hf:heartbeat") or 0) \
                    < HF_HEARTBEAT_STALE_SECONDS:
                return
            if now - float(meta.get("hf:last_trigger") or 0) \
                    < HF_TRIGGER_MIN_INTERVAL_SECONDS:
                return
            token = os.environ.get("KAGGLE_API_TOKEN", "")
            if not token:
                return
            meta["hf:last_trigger"] = now
            try:
                script_text = HF_WORKER_SCRIPT_PATH.read_text()
            except Exception:
                return
            ok, detail = hf_kaggle_push(token, script_text)
            meta["hf:last_trigger_result"] = {
                "ok": ok, "detail": detail, "at": now}
        except Exception:
            pass

    def _hf_worker_ok(x_api_key: str) -> bool:
        return _family_worker_ok("TEMPLATE", x_api_key)

    # -- worker plane auth (security fix, 2026-11-27) ---------------------
    # Audit findings worker-endpoints-no-claim-binding (HIGH),
    # worker-key-readable-by-in-session-third-party-code
    # (HIGH), worker-result-body-buffered-before-cap,
    # worker-upload-verification-fail-open, and
    # audio-result-arbitrary-json-trusted (MEDIUMs). The
    # worker plane used to be one shared key and nothing
    # else: any holder of the key could read any job's
    # inputs and post results or failures for any job,
    # including jobs never claimed (failing one triggers
    # refunds). Now:
    #   * each family has its own key (env <FAMILY>_WORKER_KEY,
    #     falling back to the shared TEMPLATE_WORKER_KEY so
    #     the rollout needs no flag day), and each family's
    #     previous key is accepted during rotation
    #     (<NAME>_PREV), so a key that leaks inside one
    #     Kaggle session no longer opens the other families;
    #   * a claim that carries X-Claim-Bind: 1 is issued a
    #     per-job claim token (only its SHA-256 is stored);
    #     every per-job endpoint then requires that token,
    #     so the shared key alone can no longer touch a
    #     claimed job, and a token is bound to the one job
    #     its session claimed;
    #   * source endpoints refuse jobs that are done, and
    #     fail endpoints refuse jobs that were never claimed.

    def _family_worker_ok(family: str, provided: str) -> bool:
        names = [f"{family}_WORKER_KEY", f"{family}_WORKER_KEY_PREV",
                 "TEMPLATE_WORKER_KEY", "TEMPLATE_WORKER_KEY_PREV"]
        for name in names:
            expected = os.environ.get(name, "")
            if expected and hmac.compare_digest(provided or "",
                                                 expected):
                return True
        return False

    def _issue_claim_token(job: dict, bind: str):
        if bind != "1":
            return None
        token = pysecrets.token_urlsafe(32)
        job["claim_token_hash"] = hashlib.sha256(
            token.encode()).hexdigest()
        return token

    def _require_claim(job: dict, x_claim_token: str):
        want = job.get("claim_token_hash")
        if not want:
            return  # legacy claim: key-only, pre-token kernels
        got = hashlib.sha256(
            (x_claim_token or "").encode()).hexdigest()
        if not hmac.compare_digest(got, want):
            raise HTTPException(
                status_code=403,
                detail="this job was claimed by another worker session")

    def _refuse_finished_source(job: dict):
        if job.get("status") in ("done", "error"):
            raise HTTPException(
                status_code=404, detail="the job is finished")

    def _check_declared_size(request: Request, cap: int):
        declared = request.headers.get("content-length")
        if declared:
            try:
                if int(declared) > cap:
                    raise HTTPException(
                        status_code=413, detail="bad file size")
            except ValueError:
                pass

    def _claim_candidates(family: str, match) -> list:
        """Queued jobs for one worker family: the claim
        queue first (each id verified against its record),
        a full scan only when the queue yields nothing, and
        the scan refreshes the queue for the next poll."""
        ids = list(meta.get(f"claimq:{family}") or [])
        found, keep = [], []
        for jid in ids:
            job = jobs.get(jid)
            if job and match(job):
                found.append(job)
                keep.append(jid)
        if found:
            if keep != ids:
                meta[f"claimq:{family}"] = keep
            return found
        scanned = []
        for key in list(jobs.keys()):
            job = jobs.get(key)
            if job and match(job):
                scanned.append(job)
        meta[f"claimq:{family}"] = [j["id"] for j in scanned][-1000:]
        return scanned

    def _validate_audio_result(job: dict, body) -> dict:
        """The word check verdict, rebuilt server side from
        validated fields only (security fix, 2026-11-27):
        the worker's JSON used to be stored and trusted
        verbatim, so a compromised session could stamp any
        outcome onto a job it never checked. Only the fields
        the waiting caller reads survive, each type checked,
        and only for the stage that produces them."""
        if not isinstance(body, dict):
            raise HTTPException(status_code=400, detail="bad result")
        stage = job.get("audio_stage")
        if stage not in ("wordcheck", "transcribe"):
            raise HTTPException(
                status_code=400,
                detail="this stage takes no result")

        def word_list(value, cap):
            out = []
            if isinstance(value, list):
                for item in value[:cap]:
                    if isinstance(item, dict):
                        entry = {}
                        for key in ("word", "start", "end", "at"):
                            val = item.get(key)
                            if isinstance(val, (str, int, float)) \
                                    and not isinstance(val, bool):
                                entry[key] = val
                        out.append(entry)
            return out

        if stage == "transcribe":
            return {"words": word_list(body.get("words"), 5000)}
        status = body.get("status")
        if status not in ("passed", "take_failed", "fixed",
                          "flagged"):
            raise HTTPException(
                status_code=400, detail="bad result status")
        clean = {"status": status,
                 "wrong": word_list(body.get("wrong"), 200),
                 "words": word_list(body.get("words"), 5000)}
        listen = body.get("listen_at")
        clean["listen_at"] = [
            float(x) for x in (listen or [])[:200]
            if isinstance(x, (int, float))
            and not isinstance(x, bool)] \
            if isinstance(listen, list) else []
        for key in ("wrong_ratio", "initial_wrong_ratio"):
            val = body.get(key)
            if isinstance(val, (int, float)) \
                    and not isinstance(val, bool):
                clean[key] = min(1.0, max(0.0, float(val)))
        return clean

    def _hf_daily_used(user: dict) -> int:
        # Counted off the per-user index facts (kind and
        # creation time ride the entry), no record fetches.
        day_start = _now() - (_now() % 86400)
        ent = _user_job_index(user["id"])
        return sum(1 for e in (ent.get("ids") or [])
                   if e[2] == "template" and e[1] >= day_start)

