    @web.post("/api/templates/upload")
    async def upload_template_source(request: Request, file: UploadFile = File(...),
                                     mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if _rate_limited("templateupload", user["id"], 6):
            raise HTTPException(status_code=429, detail="too many uploads, slow down")
        upload_id = pysecrets.token_hex(8)
        src_dir = Path("/data/template-sources")
        src_dir.mkdir(parents=True, exist_ok=True)
        suffix = Path(file.filename or "upload.mp4").suffix.lower()
        # The photo presenter's source is a picture, not a
        # clip: it lands under its image suffix with no probe,
        # and the create path classifies it through the same
        # input gate every image input crosses. The record
        # carries the kind so a photo can never be spent as a
        # clip or the other way round.
        is_image = suffix in (".jpg", ".jpeg", ".png", ".webp")
        if not is_image and suffix not in (".mp4", ".mov", ".mkv", ".webm", ".m4v"):
            suffix = ".mp4"
        dest = src_dir / f"{upload_id}{suffix}"
        size = 0
        with dest.open("wb") as fh:
            while True:
                chunk = await file.read(1024 * 1024)
                if not chunk:
                    break
                size += len(chunk)
                if size > TEMPLATE_MAX_UPLOAD_BYTES:
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail="that file is too big, keep it under 200 MB")
                if not _upload_quota_allows(user, size):
                    fh.close()
                    dest.unlink(missing_ok=True)
                    raise HTTPException(status_code=413, detail=UPLOAD_QUOTA_DETAIL)
                fh.write(chunk)
        data_volume.commit()
        if is_image:
            meta[f"templateupload:{upload_id}"] = {
                "user_id": user["id"], "path": str(dest),
                "bytes": size,
                "kind": "image", "duration": 0.0,
                "filename": (file.filename or "upload")[:120],
                "created_at": _now(),
            }
            return {"upload_id": upload_id, "kind": "image"}
        try:
            info = clipping.probe(dest)
        except Exception as exc:
            dest.unlink(missing_ok=True)
            raise HTTPException(status_code=422, detail=str(exc)[:200])
        duration = float(info["duration"])
        if duration > TEMPLATE_MAX_SOURCE_SECONDS:
            dest.unlink(missing_ok=True)
            raise HTTPException(
                status_code=422,
                detail="that clip is too long for this one, keep it under a minute")
        meta[f"templateupload:{upload_id}"] = {
            "user_id": user["id"], "path": str(dest),
            "bytes": size,
            "kind": "video",
            "duration": duration,
            "filename": (file.filename or "upload")[:120],
            "created_at": _now(),
        }
        return {"upload_id": upload_id,
                "duration_seconds": round(duration, 2)}

    @web.post("/api/templates")
    async def create_template(request: Request, mf_session: str = Cookie(default="")):
        user = require_user(request, mf_session)
        if _rate_limited("templatecreate", user["id"], 10):
            raise HTTPException(status_code=429, detail="too many jobs, slow down")
        if not user["verified"]:
            raise HTTPException(status_code=403, detail="verify your email before creating")
        if user.get("past_due"):
            raise HTTPException(status_code=403, detail="your subscription payment is past due")
        body = await request.json()
        if not bot_check_ok(body, client_ip(request), user):
            raise HTTPException(status_code=403, detail="bot check failed")
        return create_template_core(user, body, client_ip(request))

    def create_template_core(user: dict, body: dict, ip: str):
        """The one template creation path behind both create
        surfaces (the website's /api/templates and the job
        retry path, which rebuilds the body from the stored
        record and calls this core directly with it): every
        gate below the website wrapper runs here. The website
        wrapper adds only its session auth, its pace limit,
        and the browser bot check."""
        template_id = str(body.get("template") or "")
        try:
            fields = hf_clean_fields(template_id, body)
        except ValueError as exc:
            raise HTTPException(status_code=422, detail=str(exc))
        # The illegal-content gate (Jack, 2026-11-24): every
        # word a template renders is user text, checked
        # before any free count or dispatch below.
        enforce_prompt_gate(
            user, "template", ip,
            *[v for v in fields.values() if isinstance(v, str)])
        upload_path = None
        source_duration = 0.0
        if template_id == "captions":
            rec = meta.get(f"templateupload:{body.get('upload_id') or ''}")
            if not rec or rec.get("user_id") != user["id"]:
                raise HTTPException(status_code=422, detail="upload your clip first, then make it")
            upload_path = rec["path"]
            source_duration = float(rec["duration"])
        showcase_verdict = None
        if template_id == "showcase3d":
            rec = meta.get(f"templateupload:{body.get('upload_id') or ''}")
            if (not rec or rec.get("user_id") != user["id"]
                    or rec.get("kind") != "image"):
                raise HTTPException(status_code=422, detail="upload your product photo first, then make it")
            upload_path = rec["path"]
            # The showcase's photo crosses the STANDARD input
            # gate (2026-11-26): the presenter's own-photo
            # exemption does not extend here, so a flagged
            # photo refuses and an unjudged one refuses,
            # exactly like every regular lane, and the verdict
            # stamps the job so a flagged showcase never
            # reaches the gallery.
            import base64 as _b64_showcase
            showcase_photo_b64 = _b64_showcase.b64encode(
                Path(upload_path).read_bytes()).decode()
            showcase_verdict = classify_input_images(
                b64_images=[showcase_photo_b64])
            refusal = input_gate_refusal(
                {"model": "hyperframes", "lane": "template"},
                showcase_verdict)
            if refusal:
                raise HTTPException(status_code=400, detail=refusal)
        presenter_verdict = None
        if template_id == "presenter":
            rec = meta.get(f"templateupload:{body.get('upload_id') or ''}")
            if (not rec or rec.get("user_id") != user["id"]
                    or rec.get("kind") != "image"):
                raise HTTPException(status_code=422, detail="upload your photo first, then make it")
            upload_path = rec["path"]
            # The photo is classified by the same input
            # classifier every image input crosses, before any
            # free count or dispatch, and the verdict stamps
            # the job record below. The refusal rule is this
            # entry's own (Jack, 2026-11-25): a flagged photo
            # passes, because the presenter exists to animate
            # the user's own photo; an unjudged one still
            # fails closed. Every other lane keeps
            # input_gate_refusal's rule.
            import base64 as _b64
            photo_b64 = _b64.b64encode(
                Path(upload_path).read_bytes()).decode()
            presenter_verdict = classify_input_images(
                b64_images=[photo_b64])
            refusal = presenter_input_refusal(presenter_verdict)
            if refusal:
                raise HTTPException(status_code=422, detail=refusal)
        is_free_job = False
        free_reserved = False
        if not is_paid(user):
            # Atomic free-slot claim (check and count in one
            # step), as in create_job.
            slot_status, user = reserve_free_slot(user)
            if slot_status == "cap":
                raise HTTPException(
                    status_code=403,
                    detail=f"your free clips are used up. The free plan is {FREE_CLIPS_TOTAL} clips in total")
            if slot_status == "ceiling":
                raise HTTPException(status_code=503, detail="the free tier is paused")
            is_free_job = True
            free_reserved = True
        else:
            if _hf_daily_used(user) >= TEMPLATE_DAILY_CAP_PAID:
                raise HTTPException(
                    status_code=429,
                    detail="you have made your free titles for today, the rest wait until tomorrow")
        spec = HF_TEMPLATES[template_id]
        if template_id == "story":
            plan = hf_story_plan(fields["title"],
                                 fields["lines"].split("\n"))
            duration = plan[-1]["b"]
        elif template_id == "kinetic":
            duration = hf_kinetic_duration(
                len(fields["words"].split("\n")))
        elif template_id == "captions":
            duration = source_duration
        elif template_id == "presenter":
            # A placeholder from the script's length (about
            # 150 spoken words a minute); the claim path
            # replaces it with the finished voiceover's real
            # length before the composition is built.
            duration = max(4.0, min(
                60.0, len(fields["script"].split()) / 2.5))
        else:
            duration = float(spec["duration"])
        display = (
            fields.get("headline") or fields.get("caption")
            or fields.get("stat") or fields.get("title")
            or (fields.get("words") or "").split("\n")[0]
            or (fields.get("script") or "")[:60]
            or spec["name"])
        job = {
            "id": pysecrets.token_hex(8),
            "user_id": user["id"],
            "worker_job_id": None,
            "provider": "hyperframes",
            "kind": "template",
            "lane": "template",
            "model": "hyperframes",
            "template": template_id,
            "template_name": spec["name"],
            "hf_fields": fields,
            "prompt": display,
            "user_prompt": display,
            "camera_presets": [],
            "camera_preset_names": [],
            "camera_look": {},
            "status": "queued",
            "stage": "Waiting for the free renderer",
            "error": None,
            "created_at": _now(),
            "created_ip": ip,
            "charged_cents": 0,
            "upload_path": upload_path,
            "source_duration": source_duration,
            "duration_seconds": round(duration, 2),
            "aspect_ratio": "9:16",
            "resolution": "1080x1920",
            "plan_at_job": user["plan"],
            "free_tier": is_free_job,
            "music_prompt": None,
        }
        jobs[job["id"]] = job
        _index_job(job)
        if template_id == "showcase3d":
            stamp_input_verdict(job, showcase_verdict)
            jobs[job["id"]] = job
        if template_id == "presenter":
            # The voiceover rides the audio child seam the
            # faceless shorts use (Kokoro on the Kaggle audio
            # worker, $0 like the rest of the wing). The job
            # waits at this stage until the wav lands; the
            # claim path skips it until then and fails it if
            # the voice stage errors.
            stamp_input_verdict(job, presenter_verdict)
            voice_child = _queue_audio_child(
                "voiceover",
                {"text": fields["script"],
                 "voice": DEFAULT_SPEECH_VOICE},
                job)
            job["voice_child_id"] = (voice_child or {}).get("id")
            job["stage"] = "Making the voiceover"
            jobs[job["id"]] = job
        if is_free_job and not free_reserved:
            u = usage(user)
            u["free_jobs"] += 1
            user["free_jobs_total"] = free_jobs_total(user) + 1
            user["usage"] = u
            meta["freecount:total"] = int(meta.get("freecount:total") or 0) + 1
            save_user(user)
        if not is_free_job:
            # Paid title and motion videos count toward the
            # 5 free too (the free counter rule, 2026-11-20).
            count_generation(user)
            save_user(user)
        _hf_maybe_trigger()
        return JSONResponse(public_job(job), status_code=202)


    @web.post("/api/worker/hf/heartbeat")
    def hf_heartbeat(x_api_key: str = Header(default="")):
        if not _hf_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        meta["hf:heartbeat"] = _now()
        return {"ok": True}

    @web.get("/api/worker/hf/jobs/next")
    def hf_next_job(x_api_key: str = Header(default=""),
                    x_claim_bind: str = Header(default="")):
        if not _hf_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        meta["hf:heartbeat"] = _now()
        queued = _claim_candidates(
            "hf", lambda o: o.get("kind") == "template"
            and o.get("status") == "queued")
        if not queued:
            return {"job": None}
        queued.sort(key=lambda j: j["created_at"])
        job = None
        for cand in queued:
            if cand.get("template") == "presenter":
                # A presenter renders only once its voiceover
                # exists: skip it while the wav is cooking (the
                # worker claims the next job instead of idling
                # on this one), and fail it here if the voice
                # stage already failed, so it never waits
                # forever on a voice that will not come.
                child_id = cand.get("voice_child_id")
                child = jobs.get(child_id) if child_id else None
                if child and child.get("status") == "error":
                    cand["status"] = "error"
                    cand["stage"] = "Could not make it"
                    cand["error"] = (child.get("error")
                                     or "the voiceover failed")
                    jobs[cand["id"]] = cand
                    continue
                voice_path = (_audio_child_path(child_id)
                              if child_id else None)
                if not voice_path or not Path(voice_path).exists():
                    continue
            job = cand
            break
        if job is None:
            return {"job": None}
        job["status"] = "running"
        job["stage"] = "Rendering now"
        job["claimed_at"] = _now()
        claim_token = _issue_claim_token(job, x_claim_bind)
        jobs[job["id"]] = job
        payload = {
            "id": job["id"],
            "template": job["template"],
            "fields": job.get("hf_fields") or {},
            "html": build_hf_composition(
                job["template"], job.get("hf_fields") or {},
                job.get("source_duration") or 0.0),
            "has_source": bool(job.get("upload_path")),
        }
        if (job.get("hf_fields") or {}).get("gif"):
            # The GIF option (2026-11-27): the worker makes a
            # GIF of the render's first stretch after rendering
            # and posts it back before the MP4, while the job
            # is still running.
            payload["gif"] = True
        if job["template"] == "story":
            # The worker stages the scene script beside the
            # composition and synthesizes the score before
            # rendering. The plan rides along so the music and
            # the scene change sounds land on the scene cuts.
            fields = job.get("hf_fields") or {}
            plan = hf_story_plan(fields.get("title") or "",
                                 (fields.get("lines") or "").split("\n"))
            payload["motion"] = True
            payload["audio_plan"] = {
                "duration": plan[-1]["b"],
                "scenes": [span["a"] for span in plan],
            }
        if job["template"] in FORGE3D_TEMPLATES:
            # The worker stages the 3D scene bundle beside the
            # composition and renders on the motion bound.
            payload["forge3d"] = True
        if job["template"] == "showcase3d":
            # The product photo stages beside the composition
            # under its own name through the generic source
            # download (has_source above), and the composition
            # is rebuilt with that name in its props so the
            # scene loads the staged file.
            fields = dict(job.get("hf_fields") or {})
            fields["photo"] = Path(job["upload_path"]).name
            payload["fields"] = fields
            payload["html"] = build_hf_composition(
                "showcase3d", fields, 0.0)
            payload["source_name"] = Path(job["upload_path"]).name
        if job["template"] == "presenter":
            # The voiceover is ready (the selection above
            # guaranteed it): measure it, rebuild the
            # composition at its real length with the photo's
            # staged name, and flag the job so the worker
            # pulls the voice down and computes the mouth
            # curve before rendering.
            voice_path = _audio_child_path(job["voice_child_id"])
            try:
                voice_seconds = float(
                    clipping.probe_audio(voice_path)["duration"])
            except Exception:
                voice_seconds = float(job.get("duration_seconds") or 0)
            duration = round(max(1.0, voice_seconds), 2)
            job["duration_seconds"] = duration
            fields = dict(job.get("hf_fields") or {})
            fields["duration"] = duration
            fields["photo"] = Path(job["upload_path"]).name
            payload["fields"] = fields
            payload["html"] = build_hf_composition(
                "presenter", fields, 0.0)
            payload["presenter"] = True
            payload["source_name"] = Path(job["upload_path"]).name
            payload["has_voice"] = True
            jobs[job["id"]] = job
        if claim_token:
            payload["claim_token"] = claim_token
        return {"job": payload}

    @web.get("/api/worker/hf/jobs/{job_id}/source")
    def hf_job_source(job_id: str, x_api_key: str = Header(default=""),
                      x_claim_token: str = Header(default="")):
        if not _hf_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        job = jobs.get(job_id)
        if not job or job.get("kind") != "template" \
                or not job.get("upload_path"):
            raise HTTPException(status_code=404, detail="unknown job")
        _require_claim(job, x_claim_token)
        _refuse_finished_source(job)
        path = Path(job["upload_path"])
        if not path.exists():
            try:
                data_volume.reload()
            except Exception:
                pass
        if not path.exists():
            raise HTTPException(status_code=404, detail="the uploaded file is missing")
        return FileResponse(path, media_type="video/mp4",
                            filename=path.name)

