    # -- Kaggle ComfyUI worker (the house lanes, 2026-11-19) --------------
    # The house video lanes and the house image lane run on the
    # Kaggle ComfyUI worker kernel (worker-kaggle/
    # comfy_worker_kernel.py). The worker authenticates with
    # the same worker key as the template worker: the endpoints
    # are separate, and the key never leaves its two homes (the
    # moonfactory-secrets Modal secret and the private key
    # dataset the kernel reads). The claim shape mirrors the
    # template lane: heartbeat, claim, file, fail.

    def _comfy_worker_ok(x_api_key: str) -> bool:
        return _family_worker_ok("COMFY", x_api_key)

    def _comfy_maybe_trigger() -> None:
        """Wake the ComfyUI kernel when a job waits and no
        kernel heartbeat is fresh: the same discipline as
        _hf_maybe_trigger, with its own meta keys and kernel.
        Never raises: a failed wake leaves the job queued and
        the mirror retries on its next pass. The work itself
        lives in the module level _wake_comfy_kernel, which the
        CPU processors call for the jobs they queue."""
        _wake_comfy_kernel()

    def _settle_comfy_partial(job: dict) -> None:
        """The partial delivery settlement, carried over from
        the Modal mirror's math exactly: the delivered
        fraction of the segments stands at its pro rated
        price and cost, the rest comes back."""
        user = users.get(f"id:{job['user_id']}")
        if not user:
            return
        total = max(1, int(job.get("segments_total") or 1))
        done = max(0, int(job.get("segments_done") or 0))
        frac = done / total
        charged = int(job.get("charged_cents") or 0)
        if charged and not job.get("partial_refunded"):
            refund = int(round(charged * (1 - frac)))
            if refund > 0:
                user["balance_cents"] = (
                    user.get("balance_cents", 0) + refund)
                job["partial_refunded"] = True
                job["partial_refund_cents"] = refund
        settled = float(job.get("cost_cents") or 0.0)
        if settled and not job.get("partial_cost_released"):
            release = round(settled * (1 - frac), 4)
            if release > 0:
                user["cost_settled_cents"] = max(
                    0.0, float(user.get("cost_settled_cents") or 0.0)
                    - release)
                job["partial_cost_released"] = True
                job["partial_cost_release_cents"] = release
        save_user(user)

    def _fail_comfy_job(job: dict, error_text: str,
                        internal: str) -> None:
        """Fail a ComfyUI job with the restores its Modal route
        made: an image job restores everything through
        _restore_house_image; a video job restores the balance
        charge and the settled cost, exactly the Modal mirror's
        error legs (the included budget debit was never
        restored on the house video route)."""
        job["status"] = "error"
        job["error"] = error_text
        job["internal_error"] = internal[:300]
        if job.get("kind") == "image":
            _restore_house_image(job)
        else:
            user = users.get(f"id:{job['user_id']}")
            if user:
                if job.get("charged_cents") and not job.get("refunded"):
                    user["balance_cents"] = (
                        user.get("balance_cents", 0)
                        + int(job["charged_cents"]))
                    job["refunded"] = True
                if job.get("cost_cents") and not job.get("cost_released"):
                    user["cost_settled_cents"] = max(
                        0.0, float(user.get("cost_settled_cents") or 0.0)
                        - float(job["cost_cents"]))
                    job["cost_released"] = True
                save_user(user)
        jobs[job["id"]] = job

    @web.post("/api/worker/comfy/heartbeat")
    async def comfy_heartbeat(request: Request,
                              x_api_key: str = Header(default="")):
        if not _comfy_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        meta["comfy:heartbeat"] = _now()
        # The kernel reports its current phase with each
        # heartbeat (2026-11-19): a render on the free GPU
        # class can run long, and the note is the difference
        # between watching a phase and guessing at one. The
        # body is optional; older kernel versions send none.
        try:
            body = await request.json()
        except Exception:
            body = {}
        if isinstance(body, dict) and body.get("note"):
            meta["comfy:note"] = str(body["note"])[:200]
            meta["comfy:note_age_s"] = body.get("note_age_s")
            meta["comfy:session_age_s"] = body.get("session_age_s")
        session = (body.get("session") if isinstance(body, dict)
                   else None)
        # Security fix (2026-11-27, comfy-heartbeat-session-
        # spoof-requeue): the requeue below used to trust any
        # session string in a heartbeat body, so any holder
        # of the shared key could orphan a rival session's
        # running jobs at will. A session may now orphan only
        # jobs claimed more than ten minutes ago, and only
        # when the server has seen that session claim work
        # itself (sessions are recorded at claim time). The
        # claim token on file/fail is the hard binding; this
        # keeps the heartbeat from being a free requeue lever.
        known_sessions = meta.get("comfy:claim_sessions") or {}
        if session and session in known_sessions:
            # A job is worked by the session that claimed it,
            # and Kaggle replaces a session wholesale when a
            # new version is pushed: a heartbeat from any
            # other session proves the claiming session is
            # gone, so its running jobs go back to queued for
            # the live session to claim. Without this, an
            # orphaned job reads as alive on the new session's
            # heartbeats until the six hour cap.
            for key in list(jobs.keys()):
                other = jobs.get(key)
                if other and other.get("provider") == "kaggle-comfy" \
                        and other.get("status") == "running" \
                        and other.get("worker_session") != session \
                        and float(other.get("claimed_at") or 0) \
                        < _now() - 600:
                    other["status"] = "queued"
                    other["worker_job_id"] = None
                    other.pop("claim_token_hash", None)
                    other["requeued_at"] = _now()
                    jobs[other["id"]] = other
        return {"ok": True}

    @web.get("/api/worker/comfy/jobs/next")
    def comfy_job_next(x_api_key: str = Header(default=""),
                       x_comfy_session: str = Header(default=""),
                       x_claim_bind: str = Header(default="")):
        if not _comfy_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        meta["comfy:heartbeat"] = _now()
        queued = _claim_candidates(
            "comfy", lambda j: j.get("provider") == "kaggle-comfy"
            and j.get("status") == "queued")
        if not queued:
            return {"job": None}
        queued.sort(key=lambda j: float(j.get("created_at") or 0))
        job = queued[0]
        job["status"] = "running"
        job["worker_job_id"] = job["id"]
        job["worker_session"] = x_comfy_session or None
        job["claimed_at"] = _now()
        claim_token = _issue_claim_token(job, x_claim_bind)
        jobs[job["id"]] = job
        if x_comfy_session:
            sessions = meta.get("comfy:claim_sessions") or {}
            sessions[x_comfy_session] = _now()
            if len(sessions) > 50:
                sessions = dict(sorted(
                    sessions.items(), key=lambda kv: kv[1])[-50:])
            meta["comfy:claim_sessions"] = sessions
        payload = {
            "id": job["id"],
            "kind": job.get("kind") or "video",
            "lane": job.get("lane"),
            "prompt": job.get("prompt"),
            "negative_prompt": job.get("negative_prompt"),
            "seed": job.get("seed"),
            "aspect_ratio": job.get("aspect_ratio") or "9:16",
            "segments": int(job.get("segments_total") or 1),
            "camera_pose": job.get("camera_pose"),
            "camera_speed": job.get("camera_speed"),
            "camera_recipe": job.get("camera_recipe"),
            "effect": job.get("effect"),
            "has_start_image": bool(job.get("start_image_png_b64")),
            "has_end_image": bool(job.get("end_image_png_b64")),
            "image_model": job.get("image_model"),
            "image_size": job.get("image_size"),
        }
        if claim_token:
            payload["claim_token"] = claim_token
        return {"job": payload}

    def _comfy_job_image(job_id: str, field: str,
                         x_api_key: str, x_claim_token: str = ""):
        if not _comfy_worker_ok(x_api_key):
            raise HTTPException(status_code=401, detail="bad worker key")
        job = jobs.get(job_id)
        if not job or job.get("provider") != "kaggle-comfy":
            raise HTTPException(status_code=404, detail="unknown job")
        _require_claim(job, x_claim_token)
        _refuse_finished_source(job)
        encoded = job.get(field)
        if not encoded:
            raise HTTPException(status_code=404, detail="no such image")
        return Response(content=base64.b64decode(encoded),
                        media_type="image/png")

